import { $ } from "bun";

const main = async () => {
	await $`next build`.cwd("webview");
	await $`bun run build:sidecar:bin`;
};

main().catch((error: unknown) => {
	console.error(error);
	process.exitCode = 1;
});

import { $ } from "bun";
import { telemetryDefineArgs } from "./telemetry-define-args";

const resolveTargetTriple = async (): Promise<string> => {
	const fromEnv = process.env.TAURI_ENV_TARGET_TRIPLE ?? process.env.TARGET;
	if (fromEnv?.trim()) {
		return fromEnv.trim();
	}

	const rustcVersion = await $`rustc -vV`.text();
	const hostLine = rustcVersion
		.split("\n")
		.find((line) => line.startsWith("host: "));
	const host = hostLine?.slice("host: ".length).trim();
	if (!host) {
		throw new Error("failed to resolve Rust host target triple");
	}
	return host;
};

// Bun cross-compiles --compile binaries, so a CI runner can produce the
// sidecar for a different architecture than its own (e.g. the x86_64 macOS
// bundle from an arm64 runner). Without an explicit --target, bun always
// emits a host-arch binary even when Tauri is building for another triple.
const resolveBunCompileTarget = (targetTriple: string): string | undefined => {
	if (targetTriple.startsWith("aarch64-apple-darwin"))
		return "bun-darwin-arm64";
	if (targetTriple.startsWith("x86_64-apple-darwin")) return "bun-darwin-x64";
	if (targetTriple.startsWith("x86_64-pc-windows")) return "bun-windows-x64";
	if (targetTriple.startsWith("x86_64-unknown-linux")) return "bun-linux-x64";
	if (targetTriple.startsWith("aarch64-unknown-linux"))
		return "bun-linux-arm64";
	return undefined;
};

const sidecarOutfile = (targetTriple: string): string => {
	const extension = targetTriple.includes("windows") ? ".exe" : "";
	return `./src-tauri/bin/code-sidecar-${targetTriple}${extension}`;
};

const buildSidecar = async (targetTriple: string): Promise<string> => {
	const outfile = sidecarOutfile(targetTriple);
	const bunTarget = resolveBunCompileTarget(targetTriple);
	// Telemetry config must be inlined into the compiled binary: a packaged
	// app launched from Finder/the Dock has no OTEL_* env at runtime, so
	// without this the sidecar silently ships with telemetry disabled.
	// Verify with `<binary> --telemetry-selfcheck` after building.
	const defines = telemetryDefineArgs();
	if (bunTarget) {
		await $`bun build ./sidecar/index.ts --compile --target=${bunTarget} ${defines} --outfile ${outfile}`;
	} else {
		await $`bun build ./sidecar/index.ts --compile ${defines} --outfile ${outfile}`;
	}
	return outfile;
};

// Tauri's universal-apple-darwin pseudo-target lipos the Rust binary itself
// but expects sidecars (externalBin) to already be fat binaries named
// `<name>-universal-apple-darwin`, so build both slices and merge them here.
const buildUniversalMacSidecar = async (): Promise<void> => {
	const arm64 = await buildSidecar("aarch64-apple-darwin");
	const x64 = await buildSidecar("x86_64-apple-darwin");
	const outfile = sidecarOutfile("universal-apple-darwin");
	await $`lipo -create -output ${outfile} ${arm64} ${x64}`;
	await $`chmod +x ${outfile}`;
	await $`lipo -info ${outfile}`;
};

const main = async () => {
	const targetTriple = await resolveTargetTriple();
	await $`mkdir -p src-tauri/bin`;
	if (targetTriple === "universal-apple-darwin") {
		await buildUniversalMacSidecar();
		return;
	}
	await buildSidecar(targetTriple);
};

main().catch((error: unknown) => {
	console.error(error);
	process.exitCode = 1;
});

import { describe, expect, test } from "bun:test";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { buildUpdateManifest } from "./generate-update-manifest";

const makeUniversalArtifactDir = (): string => {
	const dir = mkdtempSync(path.join(tmpdir(), "update-manifest-"));
	writeFileSync(path.join(dir, "Cline-Code_0.1.0_universal.app.tar.gz"), "tar");
	writeFileSync(
		path.join(dir, "Cline-Code_0.1.0_universal.app.tar.gz.sig"),
		"sig-universal\n",
	);
	writeFileSync(path.join(dir, "Cline-Code_0.1.0_universal.dmg"), "dmg");
	return dir;
};

const makePerArchArtifactDir = (): string => {
	const dir = mkdtempSync(path.join(tmpdir(), "update-manifest-"));
	writeFileSync(path.join(dir, "Cline-Code_0.1.0_aarch64.app.tar.gz"), "tar");
	writeFileSync(
		path.join(dir, "Cline-Code_0.1.0_aarch64.app.tar.gz.sig"),
		"sig-aarch64\n",
	);
	writeFileSync(path.join(dir, "Cline-Code_0.1.0_x86_64.app.tar.gz"), "tar");
	writeFileSync(
		path.join(dir, "Cline-Code_0.1.0_x86_64.app.tar.gz.sig"),
		"sig-x86_64\n",
	);
	writeFileSync(path.join(dir, "Cline-Code_0.1.0_aarch64.dmg"), "dmg");
	return dir;
};

describe("buildUpdateManifest", () => {
	test("maps a universal artifact to both darwin platform entries", () => {
		const dir = makeUniversalArtifactDir();
		const manifest = buildUpdateManifest({
			version: "0.1.0",
			tag: "desktop-v0.1.0",
			dir,
			repo: "cline/cline",
			notes: "notes",
			pubDate: "2026-07-21T00:00:00.000Z",
		});

		expect(manifest.version).toBe("0.1.0");
		const universalEntry = {
			signature: "sig-universal",
			url: "https://github.com/cline/cline/releases/download/desktop-v0.1.0/Cline-Code_0.1.0_universal.app.tar.gz",
		};
		expect(manifest.platforms["darwin-aarch64"]).toEqual(universalEntry);
		expect(manifest.platforms["darwin-x86_64"]).toEqual(universalEntry);
		// The DMG is a first-install artifact, not an updater artifact.
		expect(Object.keys(manifest.platforms)).toHaveLength(2);
	});

	test("maps per-arch updater artifacts to darwin platform entries", () => {
		const dir = makePerArchArtifactDir();
		const manifest = buildUpdateManifest({
			version: "0.1.0",
			tag: "desktop-v0.1.0",
			dir,
			repo: "cline/cline",
			notes: "notes",
			pubDate: "2026-07-21T00:00:00.000Z",
		});

		expect(manifest.version).toBe("0.1.0");
		expect(manifest.platforms["darwin-aarch64"]).toEqual({
			signature: "sig-aarch64",
			url: "https://github.com/cline/cline/releases/download/desktop-v0.1.0/Cline-Code_0.1.0_aarch64.app.tar.gz",
		});
		expect(manifest.platforms["darwin-x86_64"]).toEqual({
			signature: "sig-x86_64",
			url: "https://github.com/cline/cline/releases/download/desktop-v0.1.0/Cline-Code_0.1.0_x86_64.app.tar.gz",
		});
		expect(Object.keys(manifest.platforms)).toHaveLength(2);
	});

	test("throws when universal and per-arch artifacts claim the same platform", () => {
		const dir = makePerArchArtifactDir();
		writeFileSync(
			path.join(dir, "Cline-Code_0.1.0_universal.app.tar.gz"),
			"tar",
		);
		writeFileSync(
			path.join(dir, "Cline-Code_0.1.0_universal.app.tar.gz.sig"),
			"sig-universal\n",
		);
		expect(() =>
			buildUpdateManifest({
				version: "0.1.0",
				tag: "desktop-v0.1.0",
				dir,
				repo: "cline/cline",
				notes: "notes",
				pubDate: "2026-07-21T00:00:00.000Z",
			}),
		).toThrow(/multiple updater artifacts/);
	});

	test("throws when a signature file is missing", () => {
		const dir = mkdtempSync(path.join(tmpdir(), "update-manifest-"));
		writeFileSync(path.join(dir, "Cline-Code_0.1.0_aarch64.app.tar.gz"), "tar");
		expect(() =>
			buildUpdateManifest({
				version: "0.1.0",
				tag: "desktop-v0.1.0",
				dir,
				repo: "cline/cline",
				notes: "notes",
				pubDate: "2026-07-21T00:00:00.000Z",
			}),
		).toThrow();
	});

	test("throws when no updater artifacts exist", () => {
		const dir = mkdtempSync(path.join(tmpdir(), "update-manifest-"));
		writeFileSync(path.join(dir, "Cline-Code_0.1.0_aarch64.dmg"), "dmg");
		expect(() =>
			buildUpdateManifest({
				version: "0.1.0",
				tag: "desktop-v0.1.0",
				dir,
				repo: "cline/cline",
				notes: "notes",
				pubDate: "2026-07-21T00:00:00.000Z",
			}),
		).toThrow(/no updater artifacts/);
	});
});

// Generates the Tauri updater manifest (latest.json) from the updater
// artifacts produced by the desktop-publish workflow. The manifest is uploaded
// to the rolling `desktop-latest` GitHub release, which is the static endpoint
// configured in src-tauri/tauri.conf.json; its platform URLs point back at the
// immutable per-version release assets.
//
// Usage:
//   bun scripts/generate-update-manifest.ts \
//     --version 0.1.0 --tag desktop-v0.1.0 --dir dist/desktop \
//     --out dist/desktop/latest.json [--repo cline/cline] [--notes-file notes.md]

import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

type UpdaterPlatformEntry = {
	signature: string;
	url: string;
};

export type UpdateManifest = {
	version: string;
	notes: string;
	pub_date: string;
	platforms: Record<string, UpdaterPlatformEntry>;
};

// Maps the arch token embedded in artifact file names (see the "Collect
// artifacts" workflow step) to the platform keys the Tauri updater requests.
// A universal (fat) bundle serves both macOS architectures: each slice of the
// installed app requests its own compile-time arch key at runtime, and both
// keys point at the same artifact and signature.
const PLATFORM_KEYS_BY_ARCH_SUFFIX: Record<string, string[]> = {
	aarch64: ["darwin-aarch64"],
	x86_64: ["darwin-x86_64"],
	universal: ["darwin-aarch64", "darwin-x86_64"],
};

const getArgValue = (args: string[], name: string): string | undefined => {
	const index = args.indexOf(name);
	if (index >= 0 && args[index + 1] && !args[index + 1].startsWith("--")) {
		return args[index + 1];
	}
	const prefix = `${name}=`;
	const inline = args.find((arg) => arg.startsWith(prefix));
	return inline?.slice(prefix.length);
};

const archOfUpdaterArtifact = (fileName: string): string | undefined => {
	if (!fileName.endsWith(".app.tar.gz")) {
		return undefined;
	}
	return Object.keys(PLATFORM_KEYS_BY_ARCH_SUFFIX).find((arch) =>
		fileName.includes(`_${arch}`),
	);
};

export const buildUpdateManifest = (options: {
	version: string;
	tag: string;
	dir: string;
	repo: string;
	notes: string;
	pubDate: string;
}): UpdateManifest => {
	const platforms: Record<string, UpdaterPlatformEntry> = {};

	for (const fileName of readdirSync(options.dir).sort()) {
		const arch = archOfUpdaterArtifact(fileName);
		if (!arch) {
			continue;
		}
		const signaturePath = path.join(options.dir, `${fileName}.sig`);
		const signature = readFileSync(signaturePath, "utf8").trim();
		if (!signature) {
			throw new Error(`empty updater signature at ${signaturePath}`);
		}
		for (const platformKey of PLATFORM_KEYS_BY_ARCH_SUFFIX[arch]) {
			if (platforms[platformKey]) {
				throw new Error(
					`multiple updater artifacts claim platform ${platformKey}; found ${fileName} after ${platforms[platformKey].url}`,
				);
			}
			platforms[platformKey] = {
				signature,
				url: `https://github.com/${options.repo}/releases/download/${options.tag}/${encodeURIComponent(fileName)}`,
			};
		}
	}

	if (Object.keys(platforms).length === 0) {
		throw new Error(
			`no updater artifacts (*.app.tar.gz with a known arch suffix) found in ${options.dir}`,
		);
	}

	return {
		version: options.version,
		notes: options.notes,
		pub_date: options.pubDate,
		platforms,
	};
};

const main = () => {
	const args = process.argv.slice(2);
	const version = getArgValue(args, "--version");
	const tag = getArgValue(args, "--tag");
	const dir = getArgValue(args, "--dir");
	const out = getArgValue(args, "--out");
	const repo =
		getArgValue(args, "--repo") ??
		process.env.GITHUB_REPOSITORY ??
		"cline/cline";
	const notesFile = getArgValue(args, "--notes-file");

	if (!version || !tag || !dir || !out) {
		throw new Error(
			"usage: generate-update-manifest.ts --version X.Y.Z --tag desktop-vX.Y.Z --dir <artifact dir> --out <latest.json> [--repo owner/repo] [--notes-file <file>]",
		);
	}

	const notes = notesFile
		? readFileSync(notesFile, "utf8").trim()
		: `Cline Code v${version}`;

	const manifest = buildUpdateManifest({
		version,
		tag,
		dir,
		repo,
		notes,
		pubDate: new Date().toISOString(),
	});

	writeFileSync(out, `${JSON.stringify(manifest, null, "\t")}\n`);
	console.log(`wrote ${out}`);
	for (const [platform, entry] of Object.entries(manifest.platforms)) {
		console.log(`- ${platform}: ${entry.url}`);
	}
};

if (import.meta.main) {
	main();
}

import {
	cpSync,
	existsSync,
	mkdirSync,
	readdirSync,
	rmSync,
	statSync,
} from "node:fs";
import path from "node:path";
import { $ } from "bun";

type DesktopPlatform = "mac" | "windows" | "linux";

const BOOLEAN_FLAGS = new Set(["--allow-unsigned-mac", "--skip-build"]);
const VALUE_FLAGS = new Set(["--platform", "--target"]);
const VALID_FLAGS = [...BOOLEAN_FLAGS, ...VALUE_FLAGS];

const APP_NAME = "Cline Code";
const APP_ROOT = path.resolve(import.meta.dir, "..");
const BUNDLE_ROOT = path.join(
	APP_ROOT,
	"src-tauri",
	"target",
	"release",
	"bundle",
);
const PACKAGE_ROOT = path.join(APP_ROOT, "dist", "desktop");

process.chdir(APP_ROOT);

const validateArgs = (): void => {
	const args = process.argv.slice(2);

	for (let index = 0; index < args.length; index++) {
		const arg = args[index];
		if (BOOLEAN_FLAGS.has(arg)) {
			continue;
		}

		if (VALUE_FLAGS.has(arg)) {
			const value = args[index + 1];
			if (!value || value.startsWith("--")) {
				throw new Error(`missing value for ${arg}`);
			}
			index += 1;
			continue;
		}

		if (VALID_FLAGS.some((flag) => arg.startsWith(`${flag}=`))) {
			continue;
		}

		if (arg.startsWith("--")) {
			const suggestion = VALID_FLAGS.find((flag) => flag.startsWith(arg));
			throw new Error(
				suggestion
					? `unknown option ${arg}. Did you mean ${suggestion}?`
					: `unknown option ${arg}`,
			);
		}

		throw new Error(`unexpected argument ${arg}`);
	}
};

const getArgValue = (name: string): string | undefined => {
	const prefix = `${name}=`;
	const inline = process.argv.find((arg) => arg.startsWith(prefix));
	if (inline) {
		return inline.slice(prefix.length);
	}

	const index = process.argv.indexOf(name);
	if (index >= 0) {
		return process.argv[index + 1];
	}

	return undefined;
};

const hasArg = (name: string): boolean => process.argv.includes(name);

const hostPlatform = (): DesktopPlatform => {
	if (process.platform === "darwin") {
		return "mac";
	}
	if (process.platform === "win32") {
		return "windows";
	}
	if (process.platform === "linux") {
		return "linux";
	}
	throw new Error(`unsupported desktop packaging host: ${process.platform}`);
};

const resolveRequestedPlatform = (): DesktopPlatform => {
	const platform =
		getArgValue("--platform") ?? getArgValue("--target") ?? "current";
	if (platform === "current") {
		return hostPlatform();
	}
	if (platform === "mac" || platform === "windows" || platform === "linux") {
		return platform;
	}
	throw new Error(
		`unsupported platform "${platform}". Use mac, windows, linux, or current.`,
	);
};

const sanitizeName = (value: string): string =>
	value.replace(/[^a-zA-Z0-9._-]+/g, "-").replace(/^-|-$/g, "");

const packageVersion = async (): Promise<string> => {
	const packageJson = await Bun.file(
		path.join(APP_ROOT, "package.json"),
	).json();
	return String(packageJson.version ?? "0.0.0");
};

const macDistributionCredentialsConfigured = (): boolean => {
	const hasCertificate = Boolean(
		process.env.APPLE_CERTIFICATE || process.env.APPLE_SIGNING_IDENTITY,
	);
	const hasAppleIdNotarization = Boolean(
		process.env.APPLE_ID &&
			process.env.APPLE_PASSWORD &&
			process.env.APPLE_TEAM_ID,
	);
	const hasApiKeyNotarization = Boolean(
		(process.env.APPLE_API_KEY || process.env.APPLE_API_KEY_PATH) &&
			process.env.APPLE_API_KEY_ID &&
			process.env.APPLE_API_ISSUER,
	);
	return hasCertificate && (hasAppleIdNotarization || hasApiKeyNotarization);
};

const assertCanBuildPlatform = (platform: DesktopPlatform): void => {
	const host = hostPlatform();
	if (platform !== host) {
		throw new Error(
			[
				`cannot build ${platform} desktop bundles from ${host}.`,
				"Tauri desktop bundles are produced on the target OS because the native bundle tools and sidecar binary are platform-specific.",
				"Run this same package script on macOS, Windows, and Linux runners to produce all three artifact sets.",
			].join("\n"),
		);
	}
};

const assertMacDistributionReady = (allowUnsignedMac: boolean): void => {
	if (hostPlatform() !== "mac") {
		return;
	}
	if (macDistributionCredentialsConfigured() || allowUnsignedMac) {
		return;
	}

	throw new Error(
		[
			"refusing to create a shareable macOS package without Developer ID signing and notarization credentials.",
			"Unsigned quarantined macOS downloads can show as damaged on a teammate's Mac.",
			"Set APPLE_CERTIFICATE or APPLE_SIGNING_IDENTITY plus notarization credentials before running this script.",
			"Supported notarization env sets: APPLE_ID + APPLE_PASSWORD + APPLE_TEAM_ID, or APPLE_API_KEY/APPLE_API_KEY_PATH + APPLE_API_KEY_ID + APPLE_API_ISSUER.",
			"For local-only testing, rerun with --allow-unsigned-mac or ALLOW_UNSIGNED_MAC=1.",
		].join("\n"),
	);
};

const walkFiles = (root: string): string[] => {
	if (!existsSync(root)) {
		return [];
	}

	const paths: string[] = [];
	for (const entry of readdirSync(root)) {
		const fullPath = path.join(root, entry);
		const stats = statSync(fullPath);
		if (stats.isDirectory()) {
			paths.push(...walkFiles(fullPath));
			continue;
		}
		paths.push(fullPath);
	}
	return paths;
};

const copyArtifact = (source: string, outputName: string): string => {
	const destination = path.join(PACKAGE_ROOT, outputName);
	rmSync(destination, { force: true, recursive: true });
	cpSync(source, destination, { recursive: true });
	return destination;
};

const signUnsignedMacApp = async (appPath: string): Promise<void> => {
	await $`codesign --force --deep --sign - ${appPath}`;
	await $`codesign --verify --deep --strict --verbose=2 ${appPath}`;
	await $`xattr -cr ${appPath}`;
};

const verifySignedMacApp = async (appPath: string): Promise<void> => {
	await $`codesign --verify --deep --strict --verbose=2 ${appPath}`;
	await $`spctl --assess --type execute --verbose ${appPath}`;
	await $`xattr -cr ${appPath}`;
};

const collectMacArtifacts = async (
	version: string,
	allowUnsignedMac: boolean,
): Promise<string[]> => {
	const appPath = path.join(BUNDLE_ROOT, "macos", `${APP_NAME}.app`);
	if (!existsSync(appPath)) {
		throw new Error(`macOS app bundle was not created at ${appPath}`);
	}

	if (allowUnsignedMac && !macDistributionCredentialsConfigured()) {
		console.warn(
			"creating a local-only ad-hoc signed macOS package; this is not suitable for quarantined downloads.",
		);
		await signUnsignedMacApp(appPath);
	} else {
		await verifySignedMacApp(appPath);
	}

	const arch = process.arch === "arm64" ? "arm64" : "x64";
	const suffix =
		allowUnsignedMac && !macDistributionCredentialsConfigured()
			? "-local-unsigned"
			: "";
	const zipName = `${sanitizeName(APP_NAME)}-${version}-macos-${arch}${suffix}.zip`;
	const zipPath = path.join(PACKAGE_ROOT, zipName);
	rmSync(zipPath, { force: true });
	await $`ditto -c -k --keepParent ${appPath} ${zipPath}`;

	const artifacts = [zipPath];
	if (!suffix) {
		for (const dmgPath of walkFiles(path.join(BUNDLE_ROOT, "dmg")).filter(
			(file) => file.endsWith(".dmg"),
		)) {
			artifacts.push(copyArtifact(dmgPath, path.basename(dmgPath)));
		}
	}

	return artifacts;
};

const collectWindowsArtifacts = (): string[] =>
	walkFiles(BUNDLE_ROOT)
		.filter((file) => file.endsWith(".msi") || file.endsWith(".exe"))
		.map((file) => copyArtifact(file, path.basename(file)));

const collectLinuxArtifacts = (): string[] =>
	walkFiles(BUNDLE_ROOT)
		.filter(
			(file) =>
				file.endsWith(".AppImage") ||
				file.endsWith(".deb") ||
				file.endsWith(".rpm"),
		)
		.map((file) => copyArtifact(file, path.basename(file)));

const collectArtifacts = async (
	platform: DesktopPlatform,
	allowUnsignedMac: boolean,
): Promise<string[]> => {
	const version = await packageVersion();
	rmSync(PACKAGE_ROOT, { force: true, recursive: true });
	mkdirSync(PACKAGE_ROOT, { recursive: true });

	if (platform === "mac") {
		return collectMacArtifacts(version, allowUnsignedMac);
	}
	if (platform === "windows") {
		return collectWindowsArtifacts();
	}
	return collectLinuxArtifacts();
};

const main = async () => {
	validateArgs();

	const platform = resolveRequestedPlatform();
	const allowUnsignedMac =
		hasArg("--allow-unsigned-mac") || process.env.ALLOW_UNSIGNED_MAC === "1";
	const skipBuild = hasArg("--skip-build");

	assertCanBuildPlatform(platform);
	if (platform === "mac") {
		assertMacDistributionReady(allowUnsignedMac);
	}

	if (!skipBuild) {
		await $`bun run build:binary`;
	}

	const artifacts = await collectArtifacts(platform, allowUnsignedMac);
	if (artifacts.length === 0) {
		throw new Error(
			`no ${platform} desktop artifacts were found under ${BUNDLE_ROOT}`,
		);
	}

	console.log(`Packaged ${platform} desktop artifacts:`);
	for (const artifact of artifacts) {
		console.log(`- ${path.relative(APP_ROOT, artifact)}`);
	}
};

main().catch((error: unknown) => {
	console.error(error instanceof Error ? error.message : error);
	process.exitCode = 1;
});

import { describe, expect, it } from "vitest";
import { telemetryDefineArgs } from "./telemetry-define-args";

function defineMap(args: string[]): Record<string, string> {
	const map: Record<string, string> = {};
	for (let index = 0; index < args.length; index += 2) {
		expect(args[index]).toBe("--define");
		const pair = args[index + 1];
		const separator = pair.indexOf("=");
		map[pair.slice(0, separator)] = pair.slice(separator + 1);
	}
	return map;
}

