export function createSidecarContext(
	workspaceRoot: string,
	observability: {
		logger?: BasicLogger;
		telemetry?: ITelemetryService;
	} = {},
): SidecarContext {
	return {
		liveSessions: new Map(),
		restoringWorkspacePaths: new Set(),
		streamIndices: new Map(),
		wsClients: new Set(),
		pendingApprovals: new Map(),
		pendingQuestions: new Map(),
		sessionManager: null,
		hubClient: null,
		workspaceRoot,
		logger: observability.logger,
		telemetry: observability.telemetry,
		unsubscribeSessionEvents: null,
		hubBuildMismatch: null,
	};
}

export async function disposeSidecarContext(
	ctx: SidecarContext,
	reason = "code_sidecar_shutdown",
): Promise<void> {
	const cleanup: Array<Promise<unknown>> = [];

	ctx.unsubscribeSessionEvents?.();
	ctx.unsubscribeSessionEvents = null;

	for (const [sessionId, session] of ctx.liveSessions) {
		discardAllTrackedAttachments(sessionId, session);
	}
	ctx.liveSessions.clear();

	for (const client of ctx.wsClients) {
		try {
			client.close?.();
		} catch {
			// Best-effort websocket close during shutdown.
		}
	}
	ctx.wsClients.clear();
	for (const pending of ctx.pendingApprovals.values()) {
		pending.resolve({ approved: false, reason });
	}
	ctx.pendingApprovals.clear();
	for (const pending of ctx.pendingQuestions.values()) {
		if (pending.timeoutId) clearTimeout(pending.timeoutId);
		pending.reject(new Error(reason));
	}
	ctx.pendingQuestions.clear();

	const hubClient = ctx.hubClient;
	ctx.hubClient = null;
	if (hubClient) {
		cleanup.push(hubClient.dispose());
	}

	const sessionManager = ctx.sessionManager;
	ctx.sessionManager = null;
	if (sessionManager) {
		cleanup.push(sessionManager.dispose(reason));
	}

	const results = await Promise.allSettled(cleanup);
	const firstFailure = results.find(
		(result): result is PromiseRejectedResult => result.status === "rejected",
	);
	if (firstFailure) {
		throw firstFailure.reason;
	}
}

function serializeQuestionContext(
	context: AgentToolContext,
): PendingAskQuestion["item"]["context"] {
	return {
		agentId: context.agentId,
		conversationId: context.conversationId,
		iteration: context.iteration,
		...(context.metadata ? { metadata: context.metadata } : {}),
	};
}

export function requestSidecarAskQuestion(
	ctx: SidecarContext,
	question: string,
	options: string[],
	context: AgentToolContext,
): Promise<string> {
	const sessionId = context.sessionId?.trim();
	if (!sessionId) {
		return Promise.reject(
			new Error("ask_question requires an active session ID"),
		);
	}
	const choices = options
		.map((option) => option.trim())
		.filter((option) => option.length > 0)
		.slice(0, 5);
	if (choices.length === 0) {
		return Promise.resolve("");
	}

	return new Promise<string>((resolve, reject) => {
		const requestId = randomUUID();
		const timeoutId = setTimeout(() => {
			ctx.pendingQuestions.delete(requestId);
			reject(
				new Error(
					`Ask question request timed out after ${ASK_QUESTION_TIMEOUT_MS}ms`,
				),
			);
			sendEvent(ctx, "ask_question_cancelled", {
				requestId,
				reason: "timeout",
			});
		}, ASK_QUESTION_TIMEOUT_MS);
		const pending: PendingAskQuestion = {
			item: {
				requestId,
				sessionId,
				createdAt: new Date().toISOString(),
				question,
				options: choices,
				context: serializeQuestionContext(context),
			},
			resolve,
			reject,
			timeoutId,
		};
		ctx.pendingQuestions.set(requestId, pending);
		sendEvent(ctx, "ask_question_requested", pending.item);
	});
}

export function resolveSidecarAskQuestion(
	ctx: SidecarContext,
	requestId: string,
	answer: string,
): boolean {
	const pending = ctx.pendingQuestions.get(requestId);
	if (!pending) {
		return false;
	}
	ctx.pendingQuestions.delete(requestId);
	if (pending.timeoutId) clearTimeout(pending.timeoutId);
	pending.resolve(answer);
	return true;
}

export function createSidecarRuntimeCapabilities(
	ctx: SidecarContext,
): RuntimeCapabilities {
	return {
		toolExecutors: {
			askQuestion: (question, options, context) =>
				requestSidecarAskQuestion(ctx, question, options, context),
		},
		requestToolApproval: (request) => requestSidecarToolApproval(ctx, request),
	};
}

function requestSidecarToolApproval(
	ctx: SidecarContext,
	request: ToolApprovalRequest,
): Promise<ToolApprovalResult> {
	return new Promise<ToolApprovalResult>((resolve) => {
		const requestId = randomUUID();
		const pending: PendingToolApproval = {
			item: {
				requestId,
				sessionId: request.sessionId,
				createdAt: new Date().toISOString(),
				toolCallId: request.toolCallId,
				toolName: request.toolName,
				input: request.input,
				iteration: request.iteration,
				agentId: request.agentId,
				conversationId: request.conversationId,
			},
			resolve,
		};
		ctx.pendingApprovals.set(requestId, pending);
		const sessionApprovals = Array.from(ctx.pendingApprovals.values())
			.filter((approval) => approval.item.sessionId === request.sessionId)
			.map((approval) => approval.item);
		sendEvent(ctx, "tool_approval_state", {
			sessionId: request.sessionId,
			items: sessionApprovals,
		});
	});
}

export function handleHubLiveEvent(
	ctx: SidecarContext,
	event: {
		event: string;
		sessionId?: string;
		payload?: Record<string, unknown>;
	},
): void {
	const sessionId = typeof event.sessionId === "string" ? event.sessionId : "";
	if (!sessionId) {
		return;
	}
	const session = ctx.liveSessions.get(sessionId);
	if (!session?.attachedViaHub) {
		return;
	}

	switch (event.event) {
		case "assistant.delta": {
			const text =
				typeof event.payload?.text === "string" ? event.payload.text : "";
			if (text) {
				emitChunk(ctx, sessionId, "chat_text", text);
			}
			return;
		}
		case "assistant.media": {
			const media = event.payload?.media;
			if (isGeneratedMedia(media)) {
				emitChunk(ctx, sessionId, "chat_media", JSON.stringify(media));
			}
			return;
		}
		case "reasoning.delta": {
			const text =
				typeof event.payload?.text === "string" ? event.payload.text : "";
			const redacted = event.payload?.redacted === true;
			if (!text && !redacted) {
				return;
			}
			emitChunk(
				ctx,
				sessionId,
				"chat_reasoning",
				JSON.stringify({ text, redacted }),
			);
			return;
		}
		case "tool.started": {
			emitChunk(
				ctx,
				sessionId,
				"chat_tool_call_start",
				JSON.stringify({
					toolCallId:
						typeof event.payload?.toolCallId === "string"
							? event.payload.toolCallId
							: undefined,
					toolName:
						typeof event.payload?.toolName === "string"
							? event.payload.toolName
							: "tool",
					input: event.payload?.input,
				}),
			);
			return;
		}
		case "tool.updated": {
			emitChunk(
				ctx,
				sessionId,
				"chat_tool_call_update",
				JSON.stringify({
					toolCallId:
						typeof event.payload?.toolCallId === "string"
							? event.payload.toolCallId
							: undefined,
					toolName:
						typeof event.payload?.toolName === "string"
							? event.payload.toolName
							: "tool",
					update: event.payload?.update,
				}),
			);
			return;
		}
		case "tool.finished": {
			emitChunk(
				ctx,
				sessionId,
				"chat_tool_call_end",
				JSON.stringify({
					toolCallId:
						typeof event.payload?.toolCallId === "string"
							? event.payload.toolCallId
							: undefined,
					toolName:
						typeof event.payload?.toolName === "string"
							? event.payload.toolName
							: "tool",
					output: event.payload?.output,
					error:
						typeof event.payload?.error === "string"
							? event.payload.error
							: undefined,
				}),
			);
			return;
		}
		case "run.started":
		case "session.attached":
		case "session.updated": {
			const payloadSession =
				event.payload?.session &&
				typeof event.payload.session === "object" &&
				!Array.isArray(event.payload.session)
					? (event.payload.session as Record<string, unknown>)
					: undefined;
			const status =
				typeof payloadSession?.status === "string"
					? payloadSession.status
					: event.event === "run.started"
						? "running"
						: session.status;
			session.status = status;
			session.busy = status === "running";
			sendEvent(ctx, "chat_session_status", { sessionId, status });
			return;
		}
		case "run.completed":
		case "run.failed":
		case "run.aborted": {
			const reason =
				typeof event.payload?.reason === "string"
					? event.payload.reason
					: event.event === "run.aborted"
						? "aborted"
						: event.event === "run.failed"
							? "error"
							: "completed";
			session.status = reason;
			session.busy = false;
			session.endedAt = nowMs();
			sendEvent(ctx, "chat_session_ended", { sessionId, reason });
			return;
		}
		default:
			return;
	}
}

export async function initializeSessionManager(
	ctx: SidecarContext,
): Promise<void> {
	setHomeDirIfUnset(homedir());
	const sessionManager = await ClineCore.create({
		clientName: "cline-code",
		backendMode: "hub",
		capabilities: createSidecarRuntimeCapabilities(ctx),
		logger: ctx.logger,
		telemetry: ctx.telemetry,
		hub: {
			strategy: "require-hub",
			workspaceRoot: ctx.workspaceRoot,
			cwd: ctx.workspaceRoot,
			clientType: "code-sidecar",
			displayName: "Code App sidecar",
		},
	});

	// Subscribe to all session events and relay them to WS clients
	const unsubscribe = sessionManager.subscribe((event: CoreSessionEvent) => {
		handleCoreSessionEvent(ctx, event);
	});

	try {
		await ensureSharedHubClient(ctx, sessionManager.runtimeAddress);
	} catch (error) {
		unsubscribe();
		await sessionManager.dispose("code_sidecar_hub_initialization_failed");
		throw error;
	}

	ctx.sessionManager = sessionManager;
	ctx.unsubscribeSessionEvents = unsubscribe;
}

export async function ensureSharedHubClient(
	ctx: SidecarContext,
	preferredUrl?: string,
): Promise<NodeHubClient> {
	if (ctx.hubClient) {
		return ctx.hubClient;
	}
	const pending = hubClientInitialization.get(ctx);
	if (pending) {
		return await pending;
	}

	const initialization = (async () => {
		const url =
			preferredUrl?.trim() ||
			(await ensureCompatibleLocalHubUrl({
				strategy: "require-hub",
				workspaceRoot: ctx.workspaceRoot,
				cwd: ctx.workspaceRoot,
			}));
		if (!url) {
			throw new Error("Unable to start or connect to the shared Cline Hub.");
		}

		const client = new NodeHubClient({
			url,
			clientType: "code-sidecar-observer",
			displayName: "Code App observer",
			workspaceRoot: ctx.workspaceRoot,
			cwd: ctx.workspaceRoot,
		});
		try {
			await client.connect();
			client.subscribe((event) => {
				handleHubLiveEvent(ctx, event);
			});
			ctx.hubClient = client;
			return client;
		} catch (error) {
			await client.dispose().catch(() => undefined);
			throw error;
		}
	})().finally(() => {
		hubClientInitialization.delete(ctx);
	});

	hubClientInitialization.set(ctx, initialization);
	return await initialization;
}

import { homedir } from "node:os";
import {
	createClineTelemetryServiceConfig,
	setHomeDirIfUnset,
	watchManagedHubBuildMismatch,
} from "@cline/core";
import { captureSdkError, claimHubDaemonProcess } from "@cline/shared";
import { prewarmWorkspaceMetadata } from "./chat-session";
import { configureConnectorCliLaunch } from "./connectors";
import {
	broadcastEvent,
	createSidecarContext,
	disposeSidecarContext,
	initializeSessionManager,
} from "./context";
import { createDesktopObservability } from "./observability";
import { resolveWorkspaceRoot } from "./paths";
import { startServer } from "./server";
import { ensureLoginShellPath } from "./shell-path";
import { buildTelemetrySelfcheckReport } from "./telemetry-selfcheck";
import { BunRuntime, SIDECAR_HOST, SIDECAR_MODE, SIDECAR_PORT } from "./types";

const SHUTDOWN_TIMEOUT_MS = 5_000;
let activeObservability:
	| ReturnType<typeof createDesktopObservability>
	| undefined;

function withTimeout<T>(promise: Promise<T>, timeoutMs: number): Promise<T> {
	let timeout: ReturnType<typeof setTimeout> | undefined;
	return Promise.race([
		promise,
		new Promise<T>((_, reject) => {
			timeout = setTimeout(
				() => reject(new Error(`shutdown timed out after ${timeoutMs}ms`)),
				timeoutMs,
			);
		}),
	]).finally(() => {
		if (timeout) {
			clearTimeout(timeout);
		}
	});
}

async function main() {
	if (!BunRuntime) {
		throw new Error("sidecar must be run with Bun");
	}

	// When launched from Finder/the Dock the app inherits launchd's minimal
	// PATH, so agent-spawned processes can't find shell-profile-installed
	// tools like `gh`. Kick resolution off first so it overlaps the rest of
	// startup, but await it before the session manager exists — that's what
	// spawns children (agent sessions, MCP servers, scheduled runs).
	const shellPathPromise = ensureLoginShellPath();

	const workspaceRoot = resolveWorkspaceRoot(process.cwd());
	setHomeDirIfUnset(homedir());
	configureConnectorCliLaunch(workspaceRoot);
	const observability = createDesktopObservability();
	activeObservability = observability;
	const ctx = createSidecarContext(workspaceRoot, observability);
	observability.logger.log("Desktop sidecar starting", {
		workspaceRoot,
		pid: process.pid,
	});

	prewarmWorkspaceMetadata(workspaceRoot);
	observability.logger.log(
		"Login shell PATH resolution",
		await shellPathPromise,
	);
	await initializeSessionManager(ctx);

	let shuttingDown = false;
	let handlingFatalError = false;
	const shutdown = async (reason = "code_sidecar_shutdown"): Promise<void> => {
		if (shuttingDown) {
			return;
		}
		shuttingDown = true;
		observability.logger.log("Desktop sidecar shutting down", { reason });
		await withTimeout(
			(async () => {
				try {
					await disposeSidecarContext(ctx, reason);
				} finally {
					await observability.dispose();
				}
			})(),
			SHUTDOWN_TIMEOUT_MS,
		);
	};

	const shutdownAndExit = (signal: string): void => {
		void shutdown(`code_sidecar_${signal.toLowerCase()}`).finally(() => {
			process.exit(signal === "SIGINT" ? 130 : 143);
		});
	};

	process.once("SIGINT", () => shutdownAndExit("SIGINT"));
	process.once("SIGTERM", () => shutdownAndExit("SIGTERM"));
	const handleFatalError = (kind: string, error: unknown): void => {
		if (handlingFatalError) {
			process.exit(1);
		}
		handlingFatalError = true;
		observability.logger.error?.("Desktop sidecar process error", {
			kind,
			error,
		});
		captureSdkError(observability.telemetry, {
			component: "desktop",
			operation: `sidecar.${kind}`,
			error,
			handled: false,
			severity: "fatal",
		});
		void shutdown(`code_sidecar_${kind}`).finally(() => process.exit(1));
	};
	process.on("uncaughtException", (error) => {
		handleFatalError("uncaught_exception", error);
	});
	process.on("unhandledRejection", (error) => {
		handleFatalError("unhandled_rejection", error);
	});
	process.once("beforeExit", () => {
		void shutdown("code_sidecar_before_exit");
	});

	const { port } = startServer(ctx, SIDECAR_PORT, shutdown);
	observability.logger.log("Desktop sidecar ready", {
		port,
		mode: SIDECAR_MODE,
	});

	// Another Cline installation (e.g. an updated CLI) can replace the shared
	// Hub daemon while this app is running. Surface that to the webview so it
	// can prompt the user to update and restart.
	watchManagedHubBuildMismatch({
		onMismatch: (mismatch) => {
			ctx.hubBuildMismatch = mismatch;
			observability.logger.log("Managed hub build mismatch detected", {
				hubBuildId: mismatch.hubBuildId,
				hubCoreVersion: mismatch.hubCoreVersion,
				reason: mismatch.reason,
			});
			broadcastEvent(ctx, "hub_build_mismatch", mismatch);
		},
	});

	// A wildcard bind isn't a dialable address; advertise loopback instead.
	const dialHost = SIDECAR_HOST === "0.0.0.0" ? "127.0.0.1" : SIDECAR_HOST;
	const endpoint = `http://${dialHost}:${port}`;
	const wsEndpoint = `ws://${dialHost}:${port}/transport`;
	process.stdout.write(
		`${JSON.stringify({
			type: "ready",
			endpoint,
			wsEndpoint,
			pid: process.pid,
			mode: SIDECAR_MODE,
		})}\n`,
	);
}

/**
 * Prints whether the telemetry configuration that was inlined at build time
 * (see scripts/telemetry-define-args.ts) actually made it into this binary,
 * then exits. CI runs this against the packaged sidecar and fails the
 * publish when a release-grade build reports `"enabled":false` or an
 * unusable OTLP endpoint, so a regression in the build-time inlining can
 * never ship silently again.
 */
function runTelemetrySelfcheck(): void {
	const report = buildTelemetrySelfcheckReport(
		createClineTelemetryServiceConfig(),
	);
	process.stdout.write(`${JSON.stringify(report)}\n`);
}

async function runEntrypoint(): Promise<void> {
	// Before the daemon-sentinel claim: the selfcheck only inspects build-time
	// config and must not consume the sentinel or start anything.
	if (process.argv.includes("--telemetry-selfcheck")) {
		runTelemetrySelfcheck();
		return;
	}
	// Claim rather than read: consuming the sentinel keeps daemon-hosted sessions
	// from handing it to every process they spawn.
	if (claimHubDaemonProcess()) {
		await import("@cline/core/hub/daemon-entry");
		return;
	}
	await main();
}

runEntrypoint().catch(async (error) => {
	const message = error instanceof Error ? error.message : String(error);
	activeObservability?.logger.error?.("Desktop sidecar process failed", {
		error,
	});
	captureSdkError(activeObservability?.telemetry, {
		component: "desktop",
		operation: "sidecar.startup",
		error,
		handled: false,
		severity: "fatal",
	});
	await activeObservability?.dispose();
	process.stderr.write(`${message}\n`);
	process.exit(1);
});

import {
	mkdirSync,
	mkdtempSync,
	readFileSync,
	rmSync,
	statSync,
	truncateSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";
import { createDesktopLoggerAdapter, DESKTOP_LOG_MAX_BYTES } from "./logging";

const originalEnv = {
	CLINE_LOG_ENABLED: process.env.CLINE_LOG_ENABLED,
	CLINE_LOG_LEVEL: process.env.CLINE_LOG_LEVEL,
	CLINE_LOG_NAME: process.env.CLINE_LOG_NAME,
	CLINE_LOG_PATH: process.env.CLINE_LOG_PATH,
};

afterEach(() => {
	for (const [key, value] of Object.entries(originalEnv)) {
		if (value === undefined) delete process.env[key];
		else process.env[key] = value;
	}
});

describe("desktop sidecar logging", () => {
	it("writes structured SDK logs to the configured file", () => {
		const directory = mkdtempSync(join(tmpdir(), "cline-code-logging-"));
		const destination = join(directory, "sidecar.log");
		process.env.CLINE_LOG_PATH = destination;
		process.env.CLINE_LOG_LEVEL = "debug";
		delete process.env.CLINE_LOG_ENABLED;

		try {
			const adapter = createDesktopLoggerAdapter();
			adapter.core.debug("desktop runtime event", { sessionId: "session-1" });
			adapter.dispose();

			const contents = readFileSync(destination, "utf8");
			expect(contents).toContain("desktop runtime event");
			expect(contents).toContain('"sessionId":"session-1"');
			expect(adapter.runtimeConfig.name).toBe("cline-code.sidecar");
		} finally {
			rmSync(directory, { recursive: true, force: true });
		}
	});

	it("warns once before falling back to stderr when the log file cannot open", () => {
		const directory = mkdtempSync(join(tmpdir(), "cline-code-fallback-"));
		process.env.CLINE_LOG_PATH = directory;
		delete process.env.CLINE_LOG_ENABLED;
		const stderr = vi.spyOn(process.stderr, "write").mockReturnValue(true);

		try {
			const adapter = createDesktopLoggerAdapter();
			adapter.dispose();

			expect(stderr).toHaveBeenCalledWith(
				expect.stringContaining("Unable to open log file"),
			);
			expect(stderr).toHaveBeenCalledWith(
				expect.stringContaining("falling back to stderr"),
			);
		} finally {
			stderr.mockRestore();
			rmSync(directory, { recursive: true, force: true });
		}
	});

	it("rotates the active log before a write exceeds the size limit", () => {
		const directory = mkdtempSync(join(tmpdir(), "cline-code-rotation-"));
		const destination = join(directory, "sidecar.log");
		process.env.CLINE_LOG_PATH = destination;
		delete process.env.CLINE_LOG_ENABLED;

		try {
			mkdirSync(directory, { recursive: true });
			writeFileSync(destination, "");
			truncateSync(destination, DESKTOP_LOG_MAX_BYTES - 1);
			const adapter = createDesktopLoggerAdapter();
			adapter.core.log("rotate before writing this entry");
			adapter.dispose();

			expect(statSync(destination).size).toBeLessThan(1_024);
			expect(readFileSync(destination, "utf8")).toContain(
				"rotate before writing this entry",
			);
		} finally {
			rmSync(directory, { recursive: true, force: true });
		}
	});
});

import {
	closeSync,
	mkdirSync,
	openSync,
	statSync,
	truncateSync,
} from "node:fs";
import { dirname, join } from "node:path";
import {
	type BasicLogger,
	type RuntimeLoggerConfig,
	resolveClineDataDir,
} from "@cline/core";
import pino, {
	type DestinationStream,
	type LevelWithSilent,
	type Logger as PinoLogger,
} from "pino";

const LOG_MAX_AGE_MS = 2 * 24 * 60 * 60 * 1_000;
export const DESKTOP_LOG_MAX_BYTES = 50 * 1024 * 1024;
const LOG_LEVELS: ReadonlySet<LevelWithSilent> = new Set([
	"trace",
	"debug",
	"info",
	"warn",
	"error",
	"fatal",
	"silent",
]);

export interface DesktopLoggerAdapter {
	readonly core: BasicLogger;
	readonly runtimeConfig: Required<RuntimeLoggerConfig>;
	flush(): void;
	dispose(): void;
}

function resolveLogLevel(value: string | undefined): LevelWithSilent {
	const candidate = value?.trim().toLowerCase() as LevelWithSilent | undefined;
	return candidate && LOG_LEVELS.has(candidate) ? candidate : "info";
}

function resolveRuntimeConfig(): Required<RuntimeLoggerConfig> {
	const enabledValue = process.env.CLINE_LOG_ENABLED?.trim().toLowerCase();
	return {
		enabled: enabledValue !== "0" && enabledValue !== "false",
		level: resolveLogLevel(process.env.CLINE_LOG_LEVEL),
		destination:
			process.env.CLINE_LOG_PATH?.trim() ||
			join(resolveClineDataDir(), "logs", "code.log"),
		name: process.env.CLINE_LOG_NAME?.trim() || "cline-code.sidecar",
		bindings: {},
	};
}

type ManagedDestination = DestinationStream & {
	flushSync(): void;
	end(): void;
};

type DestinationResult =
	| { destination: ManagedDestination; error?: never }
	| { destination?: never; error: unknown };

function createDestination(path: string): DestinationResult {
	try {
		mkdirSync(dirname(path), { recursive: true });
		const fd = openSync(path, "a");
		closeSync(fd);
		const initialStats = statSync(path);
		if (
			Date.now() - initialStats.mtimeMs >= LOG_MAX_AGE_MS ||
			initialStats.size >= DESKTOP_LOG_MAX_BYTES
		) {
			truncateSync(path, 0);
		}
		const rawDestination = pino.destination({
			dest: path,
			mkdir: true,
			sync: true,
		});
		const rawFlushSync = rawDestination.flushSync.bind(rawDestination);
		let currentSize = statSync(path).size;
		const destination: ManagedDestination = {
			write(message: string) {
				const messageSize = Buffer.byteLength(message);
				if (currentSize + messageSize > DESKTOP_LOG_MAX_BYTES) {
					try {
						rawFlushSync();
						truncateSync(path, 0);
						currentSize = 0;
					} catch {
						// Rotation is best-effort; preserve the log entry if it fails.
					}
				}
				rawDestination.write(message);
				currentSize += messageSize;
			},
			flushSync() {
				try {
					rawFlushSync();
				} catch {
					// The synchronous stream may already be closed during teardown.
				}
			},
			end() {
				rawDestination.end();
			},
		};
		return { destination };
	} catch (error) {
		return { error };
	}
}

function writeDestinationFallbackWarning(path: string, error: unknown): void {
	try {
		const message = error instanceof Error ? error.message : String(error);
		process.stderr.write(
			`[cline-code] Unable to open log file ${path}; falling back to stderr (${message})\n`,
		);
	} catch {
		// The fallback warning must never prevent sidecar startup.
	}
}

function flushDestination(destination: ManagedDestination | undefined): void {
	if (!destination) return;
	try {
		destination.flushSync();
	} catch {
		// Logging is best-effort during shutdown.
	}
}

function closeDestination(destination: ManagedDestination | undefined): void {
	if (!destination) return;
	try {
		destination.end();
	} catch {
		// Logging is best-effort during shutdown.
	}
}

function createFallbackDestination(): DestinationStream {
	return {
		write(message: string) {
			process.stderr.write(message);
		},
	};
}

/*
	The adapter intentionally owns the destination lifecycle. Pino receives a
	synchronous stream so telemetry and fatal-process logs can be flushed before
	the sidecar exits.
*/
function createPinoLogger(
	runtimeConfig: Required<RuntimeLoggerConfig>,
	destination: ManagedDestination | undefined,
): PinoLogger {
	return pino(
		{
			name: runtimeConfig.name,
			level: runtimeConfig.enabled ? runtimeConfig.level : "silent",
			enabled: runtimeConfig.enabled,
			timestamp: pino.stdTimeFunctions.isoTime,
		},
		destination ?? createFallbackDestination(),
	).child({ component: "sidecar" });
}

function flushLogger(logger: PinoLogger): void {
	try {
		logger.flush?.();
	} catch {
		// Logging is best-effort during shutdown.
	}
}

function toFields(
	metadata?: Record<string, unknown>,
): Record<string, unknown> | undefined {
	if (!metadata) return undefined;
	const { error, ...rest } = metadata;
	const fields = error === undefined ? rest : { ...rest, err: error };
	return Object.keys(fields).length > 0 ? fields : undefined;
}

function createCoreLogger(logger: PinoLogger): BasicLogger {
	return {
		debug(message, metadata) {
			const fields = toFields(metadata);
			fields ? logger.debug(fields, message) : logger.debug(message);
		},
		log(message, metadata) {
			const fields = toFields(metadata);
			const write =
				metadata?.severity === "error"
					? logger.error
					: metadata?.severity === "warn"
						? logger.warn
						: logger.info;
			fields
				? write.call(logger, fields, message)
				: write.call(logger, message);
		},
		error(message, metadata) {
			const fields = toFields(metadata);
			fields ? logger.error(fields, message) : logger.error(message);
		},
	};
}

export function createDesktopLoggerAdapter(): DesktopLoggerAdapter {
	const runtimeConfig = resolveRuntimeConfig();
	const destinationResult = runtimeConfig.enabled
		? createDestination(runtimeConfig.destination)
		: undefined;
	const destination = destinationResult?.destination;
	if (destinationResult?.error !== undefined) {
		writeDestinationFallbackWarning(
			runtimeConfig.destination,
			destinationResult.error,
		);
	}
	const logger = createPinoLogger(runtimeConfig, destination);
	let disposed = false;
	const flush = () => {
		flushDestination(destination);
		flushLogger(logger);
	};
	return {
		core: createCoreLogger(logger),
		runtimeConfig,
		flush,
		dispose() {
			if (disposed) return;
			disposed = true;
			flush();
			closeDestination(destination);
		},
	};
}

import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
	getOfficialPluginInstallPath,
	installMarketplaceEntry,
	listMarketplaceInstalledEntries,
} from "./marketplace";
import type { JsonRecord } from "./types";

const GOAL_ENTRY = {
	id: "goal",
	type: "plugin",
	name: "Goal",
	install: { args: ["goal"] },
};

let tempClineDir: string;
let previousClineDir: string | undefined;

beforeEach(async () => {
	tempClineDir = await mkdtemp(join(tmpdir(), "desktop-marketplace-"));
	previousClineDir = process.env.CLINE_DIR;
	process.env.CLINE_DIR = tempClineDir;
});

afterEach(async () => {
	if (previousClineDir === undefined) {
		delete process.env.CLINE_DIR;
	} else {
		process.env.CLINE_DIR = previousClineDir;
	}
	await rm(tempClineDir, { recursive: true, force: true });
});

function goalInstallDir(): string {
	const path = getOfficialPluginInstallPath("goal");
	if (!path) {
		throw new Error("expected an official install path for goal");
	}
	return path;
}

describe("official plugin install detection", () => {
	it("does not treat a leftover empty install directory as installed", async () => {
		// Regression: a failed or interrupted install can leave the directory
		// behind with nothing in it. The next install attempt then returned
		// "already installed" without running the CLI, so the UI flipped the
		// entry to Uninstall with no error while nothing actually worked.
		await mkdir(goalInstallDir(), { recursive: true });
		const spawnCommand = vi.fn(async () => ({
			exitCode: 1,
			stdout: "",
			stderr: "install exploded",
		}));

		await expect(
			installMarketplaceEntry({ entry: GOAL_ENTRY }, { spawnCommand }),
		).rejects.toThrow(/Plugin install failed/);
		expect(spawnCommand).toHaveBeenCalledTimes(1);
	});

	it("passes --force so a retry can reclaim the leftover directory", async () => {
		// Without --force the CLI refuses to replace the existing path
		// ("Plugin is already installed at ... Use --force to replace it."),
		// so every retry from the UI would fail against the stale directory.
		await mkdir(goalInstallDir(), { recursive: true });
		const spawnCommand = vi.fn(async (_command: string, _args: string[]) => ({
			exitCode: 0,
			stdout: "",
			stderr: "",
		}));

		const result = await installMarketplaceEntry(
			{ entry: GOAL_ENTRY },
			{ spawnCommand },
		);

		expect(result).toMatchObject({
			status: "installed",
			message: "Installed Goal.",
		});
		expect(spawnCommand.mock.calls[0]?.[1]).toContain("--force");
	});

	it("does not pass --force for a clean first install", async () => {
		const spawnCommand = vi.fn(async (_command: string, _args: string[]) => ({
			exitCode: 0,
			stdout: "",
			stderr: "",
		}));

		await installMarketplaceEntry({ entry: GOAL_ENTRY }, { spawnCommand });

		expect(spawnCommand.mock.calls[0]?.[1]).not.toContain("--force");
	});

	it("still short-circuits when the directory contains a plugin module", async () => {
		const installDir = goalInstallDir();
		await mkdir(join(installDir, "package"), { recursive: true });
		await writeFile(
			join(installDir, "package.json"),
			JSON.stringify({
				name: "goal",
				private: true,
				cline: { plugins: [{ paths: ["./package/index.ts"] }] },
			}),
		);
		await writeFile(
			join(installDir, "package", "index.ts"),
			"export default {};",
		);
		const spawnCommand = vi.fn(async () => ({
			exitCode: 0,
			stdout: "",
			stderr: "",
		}));

		const result = await installMarketplaceEntry(
			{ entry: GOAL_ENTRY },
			{ spawnCommand },
		);

		expect(result).toMatchObject({
			status: "installed",
			message: "Goal is already installed.",
		});
		expect(spawnCommand).not.toHaveBeenCalled();
	});

	it("excludes partial install directories from the installed entries list", async () => {
		await mkdir(goalInstallDir(), { recursive: true });

		const empty = listMarketplaceInstalledEntries({ entries: [GOAL_ENTRY] }, {
			plugins: [],
		} as JsonRecord);
		expect(empty.installedKeys).toEqual([]);

		const installDir = goalInstallDir();
		await mkdir(join(installDir, "package"), { recursive: true });
		await writeFile(
			join(installDir, "package", "index.ts"),
			"export default {};",
		);
		const populated = listMarketplaceInstalledEntries(
			{ entries: [GOAL_ENTRY] },
			{ plugins: [] } as JsonRecord,
		);
		expect(populated.installedKeys).toEqual(["plugin:goal"]);
	});
});

import { type SpawnOptions, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import {
	existsSync,
	mkdirSync,
	rmSync,
	statSync,
	unlinkSync,
	writeFileSync,
} from "node:fs";
import { homedir as osHomedir, platform } from "node:os";
import {
	basename,
	dirname,
	isAbsolute,
	join,
	relative,
	resolve,
} from "node:path";
import {
	type MarketplaceActionResult,
	type MarketplaceEntryInput,
	resolveSkillsConfigSearchPaths,
	resolveWorkflowsConfigSearchPaths,
	uninstallMarketplaceEntry as uninstallCoreMarketplaceEntry,
	uninstallPlugin as uninstallLocalPlugin,
} from "@cline/core";
import {
	discoverPluginModulePaths,
	resolveClineDir,
} from "@cline/shared/storage";
import { deleteMcpServer, readMcpServersResponse } from "./mcp";
import type { JsonRecord } from "./types";

type MarketplacePrimitiveType = "mcp" | "skill" | "plugin";
type LocalPrimitiveType = MarketplacePrimitiveType | "workflow";

type MarketplaceEnvVar = {
	name: string;
	required?: boolean;
	description?: string;
	url?: string;
};

type MarketplaceInstallInput = {
	id: string;
	type: MarketplacePrimitiveType;
	name?: string;
	install: {
		args?: string[];
		env?: MarketplaceEnvVar[];
		command?: string;
		notes?: string;
	};
};

type MarketplaceInstallResult = {
	id: string;
	type: LocalPrimitiveType;
	status: "installed" | "uninstalled";
	message: string;
	details?: JsonRecord;
	output?: string;
};

type MarketplaceInstallStatusResult = {
	installedKeys: string[];
};

type SpawnResult = {
	exitCode: number;
	stdout: string;
	stderr: string;
};

type SpawnCommand = (
	command: string,
	args: string[],
	options?: SpawnOptions,
) => Promise<SpawnResult>;
type CatalogFetch = (
	input: string | URL | Request,
	init?: RequestInit,
) => Promise<Response>;
type CatalogLoader = () => Promise<unknown>;

const MAX_OUTPUT_CHARS = 12_000;
const INSTALL_COMMAND_TIMEOUT_MS = 120_000;
const OFFICIAL_PLUGINS_REPO = "https://github.com/cline/plugins.git";
const MARKETPLACE_CATALOG_URL =
	process.env.CLINE_MARKETPLACE_CATALOG_URL?.trim() ||
	"https://cline.github.io/marketplace/catalog.json";
const SECRET_PATTERN =
	/(api[_ -]?key|access[_ -]?token|refresh[_ -]?token|auth(?:orization)?[_ -]?token|token|secret|password|authorization|credential)/i;
const SECRET_KEY_VALUE_PATTERN =
	/((?:^|[^\w])(?:[a-z0-9_]*?(?:api[_ -]?key|access[_ -]?token|refresh[_ -]?token|auth(?:orization)?[_ -]?token|token|secret|password|credential)[a-z0-9_]*)\s*[:=]\s*)(.+)$/gi;
const SECRET_BEARER_VALUE_PATTERN =
	/((?:^|[^\w])authorization\s*[:=]\s*)bearer\s+([^\s,"'}\]]+)/gi;
const SECRET_AUTHORIZATION_VALUE_PATTERN =
	/((?:^|[^\w])authorization\s*[:=])(?!\s*bearer\b)\s*(.+)$/gi;

export async function fetchMarketplaceCatalog(
	fetchImpl: CatalogFetch = fetch,
): Promise<unknown> {
	const response = await fetchImpl(MARKETPLACE_CATALOG_URL, {
		headers: { Accept: "application/json" },
	});
	if (!response.ok) {
		throw new Error(
			`Failed to fetch marketplace catalog: ${response.status} ${response.statusText}`.trim(),
		);
	}
	return response.json();
}

function isPrimitiveType(value: unknown): value is MarketplacePrimitiveType {
	return value === "mcp" || value === "skill" || value === "plugin";
}

function toStringArray(value: unknown): string[] {
	return Array.isArray(value)
		? value.filter((item): item is string => typeof item === "string")
		: [];
}

function readInstallInput(
	args?: Record<string, unknown>,
): MarketplaceInstallInput {
	const entry = readInstallRecord(args);
	const install =
		entry.install && typeof entry.install === "object"
			? (entry.install as Record<string, unknown>)
			: {};
	const installArgs = toStringArray(install.args);
	if (installArgs.length === 0) {
		throw new Error("marketplace install args are required");
	}
	const env = Array.isArray(install.env)
		? install.env
				.map((item): MarketplaceEnvVar | null => {
					if (!item || typeof item !== "object") return null;
					const candidate = item as Record<string, unknown>;
					if (typeof candidate.name !== "string") return null;
					const parsed: MarketplaceEnvVar = {
						name: candidate.name,
					};
					if (typeof candidate.required === "boolean") {
						parsed.required = candidate.required;
					}
					if (typeof candidate.description === "string") {
						parsed.description = candidate.description;
					}
					if (typeof candidate.url === "string") {
						parsed.url = candidate.url;
					}
					return parsed;
				})
				.filter((item): item is MarketplaceEnvVar => item !== null)
		: undefined;
	return {
		id: entry.id.trim(),
		type: entry.type,
		name: typeof entry.name === "string" ? entry.name : undefined,
		install: {
			args: installArgs,
			command:
				typeof install.command === "string" ? install.command : undefined,
			env,
			notes: typeof install.notes === "string" ? install.notes : undefined,
		},
	};
}

function readInstallRecord(
	args?: Record<string, unknown>,
): Record<string, unknown> & { id: string; type: MarketplacePrimitiveType } {
	const entry =
		args?.entry && typeof args.entry === "object"
			? (args.entry as Record<string, unknown>)
			: (args ?? {});
	if (typeof entry.id !== "string" || entry.id.trim().length === 0) {
		throw new Error("marketplace entry id is required");
	}
	if (!isPrimitiveType(entry.type)) {
		throw new Error("marketplace entry type must be mcp, skill, or plugin");
	}
	return entry as Record<string, unknown> & {
		id: string;
		type: MarketplacePrimitiveType;
	};
}

function readInstallRequest(args?: Record<string, unknown>) {
	const entry = readInstallRecord(args);
	return {
		id: entry.id.trim(),
		type: entry.type,
	};
}

function readLocalUninstallInput(args?: Record<string, unknown>): {
	id: string;
	type: LocalPrimitiveType;
	name?: string;
	path?: string;
} {
	const type = typeof args?.type === "string" ? args.type.trim() : "";
	if (
		type !== "mcp" &&
		type !== "skill" &&
		type !== "workflow" &&
		type !== "plugin"
	) {
		throw new Error(
			"local uninstall type must be mcp, skill, workflow, or plugin",
		);
	}
	const id =
		typeof args?.id === "string" && args.id.trim().length > 0
			? args.id.trim()
			: typeof args?.name === "string" && args.name.trim().length > 0
				? args.name.trim()
				: typeof args?.path === "string" && args.path.trim().length > 0
					? args.path.trim()
					: "";
	if (!id) {
		throw new Error("local uninstall id, name, or path is required");
	}
	return {
		id,
		type,
		name: typeof args?.name === "string" ? args.name.trim() : undefined,
		path: typeof args?.path === "string" ? args.path.trim() : undefined,
	};
}

function readInstallInputList(
	args?: Record<string, unknown>,
): MarketplaceInstallInput[] {
	const rawEntries = Array.isArray(args?.entries) ? args.entries : [];
	return rawEntries
		.map((entry) => {
			try {
				return readInstallInput({ entry });
			} catch {
				return null;
			}
		})
		.filter((entry): entry is MarketplaceInstallInput => entry !== null);
}

function readCatalogEntries(catalog: unknown): MarketplaceInstallInput[] {
	const catalogEntries =
		catalog && typeof catalog === "object"
			? (catalog as Record<string, unknown>).entries
			: undefined;
	if (!Array.isArray(catalogEntries)) {
		throw new Error("marketplace catalog entries are required");
	}
	return catalogEntries
		.map((entry) => {
			try {
				return readInstallInput({ entry });
			} catch {
				return null;
			}
		})
		.filter((entry): entry is MarketplaceInstallInput => entry !== null);
}

function marketplaceEntryKey(
	entry: Pick<MarketplaceInstallInput, "id" | "type">,
) {
	return `${entry.type}:${entry.id}`;
}

function redactOutput(value: string): string {
	const lines = value.split(/\r?\n/).map((line) => {
		if (!SECRET_PATTERN.test(line)) return line;
		return line
			.replace(SECRET_KEY_VALUE_PATTERN, "$1[redacted]")
			.replace(SECRET_BEARER_VALUE_PATTERN, "$1Bearer [redacted]")
			.replace(/\b(Bearer)\s+(?!\[redacted\])([^\s,"'}\]]+)/gi, "$1 [redacted]")
			.replace(SECRET_AUTHORIZATION_VALUE_PATTERN, "$1 [redacted]")
			.replace(
				/((?:^|[^\w])(?:api\s+key|access\s+token|refresh\s+token|auth(?:orization)?\s+token|secret|password|credential)\s+(?:is\s+)?)(\S+)/gi,
				"$1[redacted]",
			);
	});
	return lines.join("\n").slice(-MAX_OUTPUT_CHARS);
}

const defaultSpawnCommand: SpawnCommand = async (command, args, options = {}) =>
	new Promise<SpawnResult>((resolve, reject) => {
		let settled = false;
		let timedOut = false;
		const child = spawn(command, args, {
			...options,
			env: options.env ?? process.env,
			shell: options.shell ?? platform() === "win32",
			stdio: options.stdio ?? ["ignore", "pipe", "pipe"],
			windowsHide: true,
		});
		let stdout = "";
		let stderr = "";
		const forceKillTimeout = setTimeout(() => {
			if (!settled) {
				child.kill("SIGKILL");
			}
		}, INSTALL_COMMAND_TIMEOUT_MS + 5_000);
		const timeout = setTimeout(() => {
			timedOut = true;
			stderr += `\nTimed out after ${INSTALL_COMMAND_TIMEOUT_MS / 1000}s.`;
			child.kill("SIGTERM");
		}, INSTALL_COMMAND_TIMEOUT_MS);
		forceKillTimeout.unref?.();
		timeout.unref?.();
		child.stdout?.on("data", (chunk) => {
			stdout += String(chunk);
			if (stdout.length > MAX_OUTPUT_CHARS * 2) {
				stdout = stdout.slice(-MAX_OUTPUT_CHARS);
			}
		});
		child.stderr?.on("data", (chunk) => {
			stderr += String(chunk);
			if (stderr.length > MAX_OUTPUT_CHARS * 2) {
				stderr = stderr.slice(-MAX_OUTPUT_CHARS);
			}
		});
		child.once("error", (error) => {
			clearTimeout(timeout);
			clearTimeout(forceKillTimeout);
			reject(error);
		});
		child.once("close", (code, signal) => {
			settled = true;
			clearTimeout(timeout);
			clearTimeout(forceKillTimeout);
			const result = {
				exitCode: timedOut ? 124 : (code ?? (signal === "SIGINT" ? 130 : 1)),
				stdout,
				stderr,
			};
			resolve(result);
		});
	});

function normalizeTransport(value: string | undefined): string {
	const normalized = (value ?? "stdio").trim();
	if (normalized === "http" || normalized === "streamable-http") {
		return "streamableHttp";
	}
	if (
		normalized === "stdio" ||
		normalized === "sse" ||
		normalized === "streamableHttp"
	) {
		return normalized;
	}
	throw new Error(
		`Unsupported MCP transport "${normalized}". Expected stdio, sse, http, streamable-http, or streamableHttp.`,
	);
}

function assertUrl(value: string): void {
	let parsed: URL;
	try {
		parsed = new URL(value);
	} catch {
		throw new Error(`Invalid MCP server URL: ${value}`);
	}
	if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
		throw new Error(`Invalid MCP server URL: ${value}`);
	}
}

export function buildMarketplaceMcpInput(args: string[]): JsonRecord {
	const [rawName, ...rest] = args;
	const name = rawName?.trim();
	if (!name) {
		throw new Error("MCP marketplace install requires a server name");
	}
	let transportType = "stdio";
	const headers: Record<string, string> = {};
	const targetArgs: string[] = [];
	let parsingMarketplaceOptions = true;
	for (let index = 0; index < rest.length; index++) {
		const arg = rest[index];
		if (parsingMarketplaceOptions && arg === "--") {
			targetArgs.push(...rest.slice(index + 1));
			break;
		}
		if (parsingMarketplaceOptions && (arg === "--transport" || arg === "-t")) {
			const next = rest[index + 1]?.trim();
			if (!next) throw new Error("--transport requires a value");
			transportType = normalizeTransport(next);
			index++;
			continue;
		}
		const shouldParseHeader =
			parsingMarketplaceOptions ||
			normalizeTransport(transportType) !== "stdio";
		if (
			shouldParseHeader &&
			(arg === "--header" || arg?.startsWith("--header="))
		) {
			const rawHeader =
				arg === "--header" ? rest[++index] : arg.slice("--header=".length);
			if (!rawHeader) throw new Error("--header requires a value");
			const separatorIndex = rawHeader.indexOf(":");
			if (separatorIndex <= 0) {
				throw new Error(
					`Invalid MCP header "${rawHeader}". Expected "Header-Name: header value".`,
				);
			}
			const headerName = rawHeader.slice(0, separatorIndex).trim();
			const headerValue = rawHeader.slice(separatorIndex + 1).trim();
			if (!headerName || !headerValue) {
				throw new Error(
					`Invalid MCP header "${rawHeader}". Expected "Header-Name: header value".`,
				);
			}
			headers[headerName] = headerValue;
			continue;
		}
		parsingMarketplaceOptions = false;
		targetArgs.push(arg);
	}
	transportType = normalizeTransport(transportType);
	if (transportType === "stdio") {
		if (Object.keys(headers).length > 0) {
			throw new Error("Stdio MCP installs do not support request headers.");
		}
		const [command, ...commandArgs] = targetArgs;
		if (!command?.trim()) {
			throw new Error("Stdio MCP install requires a command");
		}
		return {
			name,
			transportType,
			command,
			args: commandArgs.length > 0 ? commandArgs : undefined,
			disabled: false,
		};
	}
	if (targetArgs.length !== 1) {
		throw new Error("Remote MCP install requires exactly one URL");
	}
	const url = targetArgs[0]?.trim() ?? "";
	assertUrl(url);
	return {
		name,
		transportType,
		url,
		headers: Object.keys(headers).length > 0 ? headers : undefined,
		disabled: false,
	};
}

function resolveClineInvocation(): { command: string; argsPrefix: string[] } {
	const wrapperPath = process.env.CLINE_WRAPPER_PATH?.trim();
	if (wrapperPath) {
		return { command: wrapperPath, argsPrefix: [] };
	}
	const entry = process.argv[1]?.trim();
	if (entry && /(?:^|[/\\])apps[/\\]cli[/\\]src[/\\]index\.ts$/.test(entry)) {
		return { command: process.execPath, argsPrefix: [entry] };
	}
	return { command: "cline", argsPrefix: [] };
}

function isInsidePath(childPath: string, parentPath: string): boolean {
	const relativePath = relative(resolve(parentPath), resolve(childPath));
	return (
		relativePath === "" ||
		(!relativePath.startsWith("..") && !isAbsolute(relativePath))
	);
}

function resolveUserInstructionRemovalTarget(input: {
	type: "skill" | "workflow";
	path: string;
	workspaceRoot?: string;
}): string {
	const filePath = resolve(input.path);
	const searchPaths =
		input.type === "skill"
			? resolveSkillsConfigSearchPaths(input.workspaceRoot)
			: resolveWorkflowsConfigSearchPaths(input.workspaceRoot);
	const containingRoot = searchPaths.find((root) =>
		isInsidePath(filePath, root),
	);
	if (!containingRoot) {
		throw new Error(
			`${input.type} uninstall requires a file inside a configured ${input.type} directory.`,
		);
	}
	const stats = statSync(filePath, { throwIfNoEntry: false });
	if (!stats?.isFile()) {
		throw new Error(`${input.type} file does not exist: ${filePath}`);
	}
	if (input.type === "workflow") {
		return filePath;
	}
	const skillDir = dirname(filePath);
	return resolve(skillDir) === resolve(containingRoot) ? filePath : skillDir;
}

export async function uninstallLocalPrimitive(
	args?: Record<string, unknown>,
	options: { workspaceRoot?: string } = {},
): Promise<MarketplaceInstallResult> {
	const input = readLocalUninstallInput(args);
	if (input.type === "mcp") {
		const name = input.name ?? input.id;
		const response = deleteMcpServer(name);
		return {
			id: input.id,
			type: input.type,
			status: "uninstalled",
			message: `Uninstalled ${name}.`,
			details: { mcp: response },
		};
	}
	if (input.type === "plugin") {
		const result = await uninstallLocalPlugin({
			name: input.path ? undefined : (input.name ?? input.id),
			path: input.path,
			workspaceRoot: options.workspaceRoot,
		});
		return {
			id: input.id,
			type: input.type,
			status: "uninstalled",
			message: `Uninstalled ${result.name}.`,
			details: result as unknown as JsonRecord,
		};
	}
	if (input.type === "skill" || input.type === "workflow") {
		if (!input.path) {
			throw new Error(`${input.type} uninstall requires a path.`);
		}
		const target = resolveUserInstructionRemovalTarget({
			type: input.type,
			path: input.path,
			workspaceRoot: options.workspaceRoot,
		});
		const stats = statSync(target, { throwIfNoEntry: false });
		if (!stats) {
			throw new Error(`${input.type} target does not exist: ${target}`);
		}
		rmSync(target, { recursive: stats.isDirectory(), force: true });
		return {
			id: input.id,
			type: input.type,
			status: "uninstalled",
			message: `Uninstalled ${input.name ?? basename(target)}.`,
			details: { path: target },
		};
	}
	throw new Error(`Unsupported local uninstall type: ${input.type}`);
}

function hashSource(source: string): string {
	return createHash("sha256").update(source).digest("hex").slice(0, 12);
}

function sanitizeSegment(value: string): string {
	const sanitized = value
		.replace(/^@/, "")
		.replace(/[^a-zA-Z0-9._-]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, 80);
	return sanitized || "plugin";
}

function sanitizeSkillSegment(value: string): string {
	const sanitized = value
		.toLowerCase()
		.replace(/[^a-z0-9._]+/g, "-")
		.replace(/^[.-]+|[.-]+$/g, "")
		.slice(0, 255);
	return sanitized || "skill";
}

function isOfficialPluginSlug(source: string): boolean {
	return /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(source.trim());
}

export function getOfficialPluginInstallPath(
	source: string,
): string | undefined {
	const slug = source.trim();
	if (!isOfficialPluginSlug(slug)) return undefined;
	const sourceKey = `official:${OFFICIAL_PLUGINS_REPO}#plugins/${slug}`;
	return join(
		resolveClineDir(),
		"plugins",
		"_installed",
		"official",
		`${sanitizeSegment(slug)}-${hashSource(sourceKey)}`,
	);
}

type OfficialPluginInstallState = "installed" | "partial" | "missing";

function getOfficialPluginInstallState(
	entry: MarketplaceInstallInput,
): OfficialPluginInstallState {
	if (entry.type !== "plugin") return "missing";
	const [source] = entry.install.args ?? [];
	if (!source) return "missing";
	const installPath = getOfficialPluginInstallPath(source);
	if (!installPath || !existsSync(installPath)) return "missing";
	// A bare directory is not an install: a failed or interrupted install can
	// leave the directory behind with no plugin inside, and treating that as
	// installed makes the next install attempt "succeed" silently ("already
	// installed") while nothing actually works. Require a loadable plugin
	// module before reporting the entry as installed; a directory without one
	// is "partial" so the installer can reclaim it with --force.
	try {
		return discoverPluginModulePaths(installPath).length > 0
			? "installed"
			: "partial";
	} catch {
		return "partial";
	}
}

function isOfficialPluginInstalled(entry: MarketplaceInstallInput): boolean {
	return getOfficialPluginInstallState(entry) === "installed";
}

function resolveHomeDir(): string {
	return (
		process.env.HOME?.trim() || process.env.USERPROFILE?.trim() || osHomedir()
	);
}

function normalizeMatchValue(value: string | undefined): string {
	return (value ?? "")
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "");
}

function getSkillInstallCandidates(entry: MarketplaceInstallInput): string[] {
	const candidates = new Set<string>();
	const addCandidate = (value: string | undefined) => {
		const normalized = sanitizeSkillSegment(value ?? "");
		if (normalized && normalized !== "skill") {
			candidates.add(normalized);
		}
	};
	addCandidate(entry.id);
	addCandidate(entry.name);
	const installArgs = entry.install.args ?? [];
	for (let index = 0; index < installArgs.length; index++) {
		const arg = installArgs[index];
		if ((arg === "--skill" || arg === "-s") && installArgs[index + 1]) {
			addCandidate(installArgs[index + 1]);
			index++;
			continue;
		}
		const skillFilter = arg.split("@").at(1);
		if (skillFilter) {
			addCandidate(skillFilter);
		}
	}
	return [...candidates];
}

function getGlobalSkillPaths(skillName: string): string[] {
	return [
		join(resolveClineDir(), "skills", skillName, "SKILL.md"),
		join(resolveHomeDir(), ".agents", "skills", skillName, "SKILL.md"),
	].filter((path, index, paths) => paths.indexOf(path) === index);
}

function ensureGlobalSkillsDirWritable(): void {
	const skillsDir = join(resolveHomeDir(), ".agents", "skills");
	try {
		mkdirSync(skillsDir, { recursive: true });
		const probePath = join(
			skillsDir,
			`.cline-marketplace-write-test-${process.pid}-${Date.now()}`,
		);
		writeFileSync(probePath, "", { flag: "wx" });
		unlinkSync(probePath);
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		throw new Error(
			`Cannot install skill globally because ~/.agents/skills is not writable: ${message}`,
		);
	}
}

function isGlobalSkillInstalled(entry: MarketplaceInstallInput): boolean {
	return findInstalledGlobalSkillName(entry) !== undefined;
}

function findInstalledGlobalSkillName(
	entry: MarketplaceInstallInput,
): string | undefined {
	if (entry.type !== "skill") return undefined;
	const candidates = getSkillInstallCandidates(entry);
	return candidates.find((candidate) =>
		getGlobalSkillPaths(candidate).some((path) => existsSync(path)),
	);
}

function hasMatchingInventoryItem(
	items: unknown,
	entry: MarketplaceInstallInput,
): boolean {
	if (!Array.isArray(items)) return false;
	const candidates = new Set([
		normalizeMatchValue(entry.id),
		normalizeMatchValue(entry.name),
		...(entry.install.args ?? []).map(normalizeMatchValue),
	]);
	candidates.delete("");
	return items.some((item) => {
		if (!item || typeof item !== "object") return false;
		const record = item as JsonRecord;
		const values = [
			typeof record.name === "string" ? record.name : undefined,
			typeof record.id === "string" ? record.id : undefined,
			typeof record.path === "string" ? record.path : undefined,
		]
			.map(normalizeMatchValue)
			.filter(Boolean);
		return values.some((value) => candidates.has(value));
	});
}

function isMcpEntryInstalled(entry: MarketplaceInstallInput): boolean {
	if (entry.type !== "mcp") return false;
	const input = buildMarketplaceMcpInput(entry.install.args ?? []);
	const response = readMcpServersResponse();
	const servers = Array.isArray(response.servers) ? response.servers : [];
	return servers.some((server) => {
		if (!server || typeof server !== "object") return false;
		const record = server as JsonRecord;
		return record.name === input.name;
	});
}

function isMarketplaceEntryInstalled(
	entry: MarketplaceInstallInput,
	inventory?: JsonRecord,
): boolean {
	try {
		if (entry.type === "mcp") return isMcpEntryInstalled(entry);
		if (entry.type === "plugin") {
			return (
				isOfficialPluginInstalled(entry) ||
				hasMatchingInventoryItem(inventory?.plugins, entry)
			);
		}
		if (entry.type === "skill") {
			return isGlobalSkillInstalled(entry);
		}
		return false;
	} catch {
		return false;
	}
}

function commandOutput(result: SpawnResult): string | undefined {
	const output = redactOutput(
		[result.stdout, result.stderr].filter(Boolean).join("\n"),
	);
	return output.trim().length > 0 ? output.trim() : undefined;
}

async function installSkill(
	entry: MarketplaceInstallInput,
	spawnCommand: SpawnCommand,
): Promise<MarketplaceInstallResult> {
	if (isGlobalSkillInstalled(entry)) {
		return {
			id: entry.id,
			type: entry.type,
			status: "installed",
			message: `${entry.name ?? entry.id} is already installed.`,
		};
	}
	ensureGlobalSkillsDirWritable();
	const result = await spawnCommand("npx", [
		"-y",
		"skills@latest",
		"add",
		...(entry.install.args ?? []),
		"-g",
		"-a",
		"cline",
		"-y",
	]);
	if (result.exitCode !== 0) {
		const output = commandOutput(result);
		throw new Error(
			`Skill install failed with exit code ${result.exitCode}${output ? `:\n${output}` : ""}`,
		);
	}
	const output = commandOutput(result);
	if (/\bFailed to install\b/i.test(output ?? "")) {
		throw new Error(`Skill install failed${output ? `:\n${output}` : ""}`);
	}
	if (!isGlobalSkillInstalled(entry)) {
		throw new Error(
			`Skill install completed, but ${entry.name ?? entry.id} was not found in Cline's global skills directories.`,
		);
	}
	return {
		id: entry.id,
		type: entry.type,
		status: "installed",
		message: `Installed ${entry.name ?? entry.id} globally for Cline.`,
		output,
	};
}

async function installPlugin(
	entry: MarketplaceInstallInput,
	spawnCommand: SpawnCommand,
): Promise<MarketplaceInstallResult> {
	const installArgs = entry.install.args ?? [];
	if (installArgs.length !== 1) {
		throw new Error(
			"Plugin marketplace installs currently support exactly one source argument.",
		);
	}
	const installState = getOfficialPluginInstallState(entry);
	if (installState === "installed") {
		return {
			id: entry.id,
			type: entry.type,
			status: "installed",
			message: `${entry.name ?? entry.id} is already installed.`,
		};
	}
	const { command, argsPrefix } = resolveClineInvocation();
	const result = await spawnCommand(command, [
		...argsPrefix,
		"plugin",
		"install",
		installArgs[0] ?? "",
		// Reclaim a leftover directory from a failed or interrupted install:
		// without --force the CLI refuses to replace the existing path and
		// every retry from the UI would fail the same way. This is safe
		// because the state check just confirmed the directory contains no
		// loadable plugin module.
		...(installState === "partial" ? ["--force"] : []),
		"--json",
	]);
	if (result.exitCode !== 0) {
		const output = commandOutput(result);
		throw new Error(
			`Plugin install failed with exit code ${result.exitCode}${output ? `:\n${output}` : ""}`,
		);
	}
	let details: JsonRecord | undefined;
	try {
		details = result.stdout.trim()
			? (JSON.parse(result.stdout.trim()) as JsonRecord)
			: undefined;
	} catch {
		details = undefined;
	}
	return {
		id: entry.id,
		type: entry.type,
		status: "installed",
		message: `Installed ${entry.name ?? entry.id}.`,
		details,
		output: commandOutput(result),
	};
}

export async function installMarketplaceEntry(
	args?: Record<string, unknown>,
	options: { spawnCommand?: SpawnCommand } = {},
): Promise<MarketplaceInstallResult> {
	const entry = readInstallInput(args);
	const spawnCommand = options.spawnCommand ?? defaultSpawnCommand;
	if (entry.type === "mcp") {
		// Validate marketplace args before handing them to the CLI-backed installer.
		buildMarketplaceMcpInput(entry.install.args ?? []);
		const { command, argsPrefix } = resolveClineInvocation();
		const result = await spawnCommand(command, [
			...argsPrefix,
			"mcp",
			"install",
			"--yes",
			"--json",
			...(entry.install.args ?? []),
		]);
		if (result.exitCode !== 0) {
			const output = commandOutput(result);
			throw new Error(
				`MCP install failed with exit code ${result.exitCode}${output ? `:\n${output}` : ""}`,
			);
		}
		let details: JsonRecord | undefined;
		try {
			details = result.stdout.trim()
				? (JSON.parse(result.stdout.trim()) as JsonRecord)
				: undefined;
		} catch {
			details = undefined;
		}
		return {
			id: entry.id,
			type: entry.type,
			status: "installed",
			message: `Installed ${entry.name ?? entry.id}.`,
			details,
			output: commandOutput(result),
		};
	}
	if (entry.type === "skill") {
		return installSkill(entry, spawnCommand);
	}
	if (entry.type === "plugin") {
		return installPlugin(entry, spawnCommand);
	}
	throw new Error(`Unsupported marketplace entry type: ${entry.type}`);
}

export async function uninstallMarketplaceEntry(
	args?: Record<string, unknown>,
	options: { spawnCommand?: SpawnCommand } = {},
): Promise<MarketplaceInstallResult> {
	const entry = readInstallInput(args);
	const spawnCommand = options.spawnCommand ?? defaultSpawnCommand;
	let mcpDetails: JsonRecord | undefined;
	const result = await uninstallCoreMarketplaceEntry(
		entry satisfies MarketplaceEntryInput,
		{
			deleteMcpServer: (name) => {
				mcpDetails = deleteMcpServer(name);
			},
			spawnCommand: (command, commandArgs) =>
				spawnCommand(command, commandArgs),
		},
	);
	return {
		...(result satisfies MarketplaceActionResult),
		details: mcpDetails ? { mcp: mcpDetails } : undefined,
	};
}

export async function installMarketplaceEntryFromCatalog(
	args?: Record<string, unknown>,
	options: {
		spawnCommand?: SpawnCommand;
		loadCatalog?: CatalogLoader;
	} = {},
): Promise<MarketplaceInstallResult> {
	const requested = readInstallRequest(args);
	const catalog = await (options.loadCatalog ?? fetchMarketplaceCatalog)();
	const entry = readCatalogEntries(catalog).find(
		(candidate) =>
			candidate.id === requested.id && candidate.type === requested.type,
	);
	if (!entry) {
		throw new Error(
			`Marketplace entry ${requested.type}:${requested.id} was not found in the catalog.`,
		);
	}
	return installMarketplaceEntry(
		{ entry },
		{ spawnCommand: options.spawnCommand },
	);
}

export async function uninstallMarketplaceEntryFromCatalog(
	args?: Record<string, unknown>,
	options: {
		spawnCommand?: SpawnCommand;
		loadCatalog?: CatalogLoader;
	} = {},
): Promise<MarketplaceInstallResult> {
	const requested = readInstallRequest(args);
	const catalog = await (options.loadCatalog ?? fetchMarketplaceCatalog)();
	const entry = readCatalogEntries(catalog).find(
		(candidate) =>
			candidate.id === requested.id && candidate.type === requested.type,
	);
	if (!entry) {
		throw new Error(
			`Marketplace entry ${requested.type}:${requested.id} was not found in the catalog.`,
		);
	}
	return uninstallMarketplaceEntry(
		{ entry },
		{ spawnCommand: options.spawnCommand },
	);
}

export function listMarketplaceInstalledEntries(
	args?: Record<string, unknown>,
	inventory?: JsonRecord,
): MarketplaceInstallStatusResult {
	const entries = readInstallInputList(args);
	const installedKeys = entries
		.filter((entry) => isMarketplaceEntryInstalled(entry, inventory))
		.map(marketplaceEntryKey);
	return { installedKeys };
}

export async function installMarketplaceEntryForDesktopCommand(
	args?: Record<string, unknown>,
	options: {
		spawnCommand?: SpawnCommand;
		loadCatalog?: CatalogLoader;
	} = {},
): Promise<MarketplaceInstallResult> {
	return installMarketplaceEntryFromCatalog(args, options);
}

export async function uninstallMarketplaceEntryForDesktopCommand(
	args?: Record<string, unknown>,
	options: {
		spawnCommand?: SpawnCommand;
		loadCatalog?: CatalogLoader;
	} = {},
): Promise<MarketplaceInstallResult> {
	return uninstallMarketplaceEntryFromCatalog(args, options);
}

import type {
	AuthorizeMcpServerOAuthOptions,
	AuthorizeMcpServerOAuthResult,
} from "@cline/core";
import { describe, expect, it, vi } from "vitest";
import {
	cancelMcpOAuthAuthorization,
	cancelMcpOAuthAuthorizationForReason,
	cancelMcpOAuthAuthorizationsForOwner,
	McpOAuthAuthorizationCancelledError,
	runCancellableMcpOAuthAuthorization,
	shouldRestoreEnabledStateAfterOAuthCancellation,
} from "./mcp-oauth";

function waitForAbort(
	options: AuthorizeMcpServerOAuthOptions,
): Promise<AuthorizeMcpServerOAuthResult> {
	return new Promise((_, reject) => {
		if (options.signal?.aborted) {
			reject(new Error("aborted"));
			return;
		}
		options.signal?.addEventListener(
			"abort",
			() => reject(new Error("aborted")),
			{ once: true },
		);
	});
}

describe("desktop MCP OAuth authorization", () => {
	it("starts browser authorization only through the explicit runner", async () => {
		const authorize = vi.fn(
			async (
				options: AuthorizeMcpServerOAuthOptions,
			): Promise<AuthorizeMcpServerOAuthResult> => ({
				serverName: options.serverName,
				authorized: true,
				message: "authorized",
			}),
		);

		await expect(
			runCancellableMcpOAuthAuthorization({ serverName: "github" }, undefined, {
				authorize,
			}),
		).resolves.toMatchObject({ authorized: true });
		expect(authorize).toHaveBeenCalledOnce();
		expect(authorize.mock.calls[0]?.[0].signal).toBeInstanceOf(AbortSignal);
	});

	it("cancels a pending callback when the server is turned off", async () => {
		const pending = runCancellableMcpOAuthAuthorization(
			{ serverName: "github" },
			undefined,
			{ authorize: waitForAbort },
		);

		expect(
			cancelMcpOAuthAuthorizationForReason("github", "server-disabled"),
		).toBe(true);
		await expect(pending).rejects.toMatchObject({
			name: "McpOAuthAuthorizationCancelledError",
			reason: "server-disabled",
		});
		expect(cancelMcpOAuthAuthorization("github")).toBe(false);
	});

	it("restores a previously enabled server only for an explicit user cancel", () => {
		expect(shouldRestoreEnabledStateAfterOAuthCancellation(false, "user")).toBe(
			true,
		);
		expect(
			shouldRestoreEnabledStateAfterOAuthCancellation(false, "server-disabled"),
		).toBe(false);
		expect(shouldRestoreEnabledStateAfterOAuthCancellation(true, "user")).toBe(
			false,
		);
	});

	it("cancels an abandoned flow when its webview connection closes", async () => {
		const owner = {};
		const pending = runCancellableMcpOAuthAuthorization(
			{ serverName: "linear" },
			owner,
			{ authorize: waitForAbort },
		);

		expect(cancelMcpOAuthAuthorizationsForOwner({})).toBe(0);
		expect(cancelMcpOAuthAuthorizationsForOwner(owner)).toBe(1);
		await expect(pending).rejects.toBeInstanceOf(
			McpOAuthAuthorizationCancelledError,
		);
	});
});

import {
	type AuthorizeMcpServerOAuthOptions,
	type AuthorizeMcpServerOAuthResult,
	authorizeMcpServerOAuth,
} from "@cline/core";

export type McpOAuthCancellationReason =
	| "user"
	| "server-disabled"
	| "superseded"
	| "owner-closed";

export function shouldRestoreEnabledStateAfterOAuthCancellation(
	wasDisabled: boolean,
	reason: McpOAuthCancellationReason,
): boolean {
	return !wasDisabled && reason === "user";
}

type PendingMcpOAuthAuthorization = {
	controller: AbortController;
	owner?: object;
	cancellationReason?: McpOAuthCancellationReason;
};

const pendingAuthorizations = new Map<string, PendingMcpOAuthAuthorization>();

export class McpOAuthAuthorizationCancelledError extends Error {
	constructor(
		serverName: string,
		readonly reason: McpOAuthCancellationReason,
	) {
		super(`MCP OAuth authorization was cancelled for "${serverName}".`);
		this.name = "McpOAuthAuthorizationCancelledError";
	}
}

export type McpOAuthAuthorizationDependencies = {
	authorize: (
		options: AuthorizeMcpServerOAuthOptions,
	) => Promise<AuthorizeMcpServerOAuthResult>;
};

const defaultDependencies: McpOAuthAuthorizationDependencies = {
	authorize: authorizeMcpServerOAuth,
};

/**
 * Owns the lifetime of a desktop MCP browser authorization. Only an explicit
 * call to this function can open the browser; ordinary server enable/connect
 * attempts only persist the SDK's `authorizationRequired` status.
 */
export async function runCancellableMcpOAuthAuthorization(
	options: Omit<AuthorizeMcpServerOAuthOptions, "signal">,
	owner?: object,
	dependencies: McpOAuthAuthorizationDependencies = defaultDependencies,
): Promise<AuthorizeMcpServerOAuthResult> {
	const serverName = options.serverName.trim();
	if (!serverName) {
		throw new Error("MCP server name cannot be empty.");
	}

	cancelMcpOAuthAuthorizationForReason(serverName, "superseded");
	const entry: PendingMcpOAuthAuthorization = {
		controller: new AbortController(),
		owner,
	};
	pendingAuthorizations.set(serverName, entry);

	try {
		try {
			return await dependencies.authorize({
				...options,
				serverName,
				signal: entry.controller.signal,
			});
		} catch (error) {
			if (entry.controller.signal.aborted) {
				throw new McpOAuthAuthorizationCancelledError(
					serverName,
					entry.cancellationReason ?? "superseded",
				);
			}
			throw error;
		}
	} finally {
		if (pendingAuthorizations.get(serverName) === entry) {
			pendingAuthorizations.delete(serverName);
		}
	}
}

/** Cancels the pending browser callback flow for one MCP server, if present. */
export function cancelMcpOAuthAuthorization(serverName: string): boolean {
	return cancelMcpOAuthAuthorizationForReason(serverName, "user");
}

export function cancelMcpOAuthAuthorizationForReason(
	serverName: string,
	reason: McpOAuthCancellationReason,
): boolean {
	const entry = pendingAuthorizations.get(serverName);
	if (!entry) {
		return false;
	}
	entry.cancellationReason = reason;
	entry.controller.abort();
	pendingAuthorizations.delete(serverName);
	return true;
}

/** Cancels MCP OAuth flows started by a webview connection that went away. */
export function cancelMcpOAuthAuthorizationsForOwner(owner: object): number {
	let cancelled = 0;
	for (const [serverName, entry] of pendingAuthorizations) {
		if (entry.owner === owner) {
			entry.cancellationReason = "owner-closed";
			entry.controller.abort();
			pendingAuthorizations.delete(serverName);
			cancelled += 1;
		}
	}
	return cancelled;
}

import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
