		expect(
			shouldProbeMcpServerAfterUpsert({
				isRemote: true,
				requestedDisabled: false,
				existingWasEnabled: true,
				transportIdentityUnchanged: false,
			}),
		).toBe(true);
	});

	it("keeps an unchanged enabled remote server enabled when saving metadata", async () => {
		const tempRoot = await mkdtemp(join(tmpdir(), "desktop-mcp-settings-"));
		const settingsPath = join(tempRoot, "cline_mcp_settings.json");
		const previousSettingsPath = process.env.CLINE_MCP_SETTINGS_PATH;
		process.env.CLINE_MCP_SETTINGS_PATH = settingsPath;
		try {
			await writeFile(
				settingsPath,
				JSON.stringify({
					mcpServers: {
						linear: {
							transport: {
								type: "streamableHttp",
								url: "http://127.0.0.1:1/mcp",
							},
						},
						broken: {},
					},
				}),
				"utf8",
			);

			const response = (await handleCommand(
				createContext(tempRoot),
				"upsert_mcp_server",
				{
					input: {
						name: "linear",
						previousName: "linear",
						transportType: "streamableHttp",
						url: "http://127.0.0.1:1/mcp",
						disabled: false,
						metadata: { source: "edited" },
					},
				},
			)) as JsonRecord;
			const servers = response.servers as JsonRecord[];
			expect(servers.find((server) => server.name === "linear")).toMatchObject({
				disabled: false,
				metadata: { source: "edited" },
			});
			expect(servers.find((server) => server.name === "broken")).toHaveProperty(
				"configurationError",
			);

			const written = JSON.parse(await readFile(settingsPath, "utf8"));
			expect(written.mcpServers.linear.disabled).toBe(false);
		} finally {
			if (previousSettingsPath === undefined) {
				delete process.env.CLINE_MCP_SETTINGS_PATH;
			} else {
				process.env.CLINE_MCP_SETTINGS_PATH = previousSettingsPath;
			}
			await rm(tempRoot, { recursive: true, force: true });
		}
	});
});

import { existsSync, readFileSync } from "node:fs";
import {
	getMcpServerOAuthStatus,
	parseMcpServerRegistration,
	updateMcpSettingsFileSync,
} from "@cline/core";
import { resolveMcpSettingsPath } from "@cline/shared/storage";
import type { JsonRecord } from "./types";

export function shouldProbeMcpServerAfterUpsert(options: {
	isRemote: boolean;
	requestedDisabled: boolean;
	existingWasEnabled: boolean;
	transportIdentityUnchanged: boolean;
}): boolean {
	return (
		options.isRemote &&
		!options.requestedDisabled &&
		!(options.existingWasEnabled && options.transportIdentityUnchanged)
	);
}

export function readMcpServersResponse(): JsonRecord {
	const settingsPath = resolveMcpSettingsPath();
	if (!existsSync(settingsPath)) {
		return { settingsPath, hasSettingsFile: false, servers: [] };
	}
	const parsed = JSON.parse(readFileSync(settingsPath, "utf8")) as JsonRecord;
	return buildMcpServersResponse(settingsPath, parsed);
}

export function buildMcpServersResponse(
	settingsPath: string,
	parsed: JsonRecord,
): JsonRecord {
	const serversValue = parsed.mcpServers;
	const servers =
		serversValue &&
		typeof serversValue === "object" &&
		!Array.isArray(serversValue)
			? (serversValue as JsonRecord)
			: {};
	const entries = Object.entries(servers).map(([name, body]) => {
		const record =
			body && typeof body === "object" && !Array.isArray(body)
				? (body as JsonRecord)
				: {};
		const transport =
			record.transport && typeof record.transport === "object"
				? (record.transport as JsonRecord)
				: undefined;
		let registration: ReturnType<typeof parseMcpServerRegistration> | undefined;
		let configurationError: string | undefined;
		try {
			registration = parseMcpServerRegistration(name, body);
		} catch (error) {
			configurationError =
				error instanceof Error ? error.message : String(error);
		}
		const resolvedTransport = registration?.transport;
		const rawTransportType = String(
			transport?.type ?? record.transportType ?? record.type ?? "",
		).trim();
		const hasRawUrl =
			typeof transport?.url === "string" || typeof record.url === "string";
		const fallbackTransportType =
			rawTransportType === "sse"
				? "sse"
				: rawTransportType === "streamableHttp" || rawTransportType === "http"
					? "streamableHttp"
					: hasRawUrl
						? "sse"
						: "stdio";
		const oauthStatus = registration
			? getMcpServerOAuthStatus(registration)
			: undefined;
		return {
			name,
			transportType: resolvedTransport?.type ?? fallbackTransportType,
			disabled: record.disabled === true,
			command: resolvedTransport
				? resolvedTransport.type === "stdio"
					? resolvedTransport.command
					: undefined
				: typeof transport?.command === "string"
					? transport.command
					: typeof record.command === "string"
						? record.command
						: undefined,
			args: resolvedTransport
				? resolvedTransport.type === "stdio"
					? resolvedTransport.args
					: undefined
				: Array.isArray(transport?.args)
					? transport.args
					: Array.isArray(record.args)
						? record.args
						: undefined,
			cwd: resolvedTransport
				? resolvedTransport.type === "stdio"
					? resolvedTransport.cwd
					: undefined
				: typeof transport?.cwd === "string"
					? transport.cwd
					: typeof record.cwd === "string"
						? record.cwd
						: undefined,
			env: resolvedTransport
				? resolvedTransport.type === "stdio"
					? resolvedTransport.env
					: undefined
				: transport?.env && typeof transport.env === "object"
					? transport.env
					: record.env && typeof record.env === "object"
						? record.env
						: undefined,
			url: resolvedTransport
				? resolvedTransport.type !== "stdio"
					? resolvedTransport.url
					: undefined
				: typeof transport?.url === "string"
					? transport.url
					: typeof record.url === "string"
						? record.url
						: undefined,
			headers: resolvedTransport
				? resolvedTransport.type !== "stdio"
					? resolvedTransport.headers
					: undefined
				: transport?.headers && typeof transport.headers === "object"
					? transport.headers
					: record.headers && typeof record.headers === "object"
						? record.headers
						: undefined,
			metadata: registration?.metadata ?? record.metadata,
			...(configurationError ? { configurationError } : {}),
			oauthStatus: oauthStatus
				? {
						supported: oauthStatus.oauthSupported,
						configured: oauthStatus.oauthConfigured,
						authorizationRequired: oauthStatus.authorizationRequired,
						lastError: oauthStatus.lastError,
						lastAuthenticatedAt: oauthStatus.lastAuthenticatedAt,
					}
				: undefined,
		};
	});
	return { settingsPath, hasSettingsFile: true, servers: entries };
}

export function writeMcpServersMap(servers: JsonRecord): void {
	updateMcpSettingsFileSync(resolveMcpSettingsPath(), (settings) => {
		settings.mcpServers = servers;
	});
}

export function ensureMcpSettingsFile(): string {
	const path = resolveMcpSettingsPath();
	if (!existsSync(path)) {
		writeMcpServersMap({});
	}
	return path;
}

export function setMcpServerDisabled(
	name: string,
	disabled: boolean,
): JsonRecord {
	// Hold the cross-process lock across read-modify-write so a concurrent writer
	// (the extension, the CLI) cannot clobber this change.
	updateMcpSettingsFileSync(resolveMcpSettingsPath(), (settings) => {
		const servers = ((settings.mcpServers as JsonRecord | undefined) ??
			{}) as JsonRecord;
		const current = servers[name];
		if (!current || typeof current !== "object") {
			throw new Error(`unknown MCP server: ${name}`);
		}
		servers[name] = { ...(current as JsonRecord), disabled };
		settings.mcpServers = servers;
	});
	return readMcpServersResponse();
}

export function upsertMcpServer(input: JsonRecord): JsonRecord {
	const name = String(input.name ?? "").trim();
	if (!name) throw new Error("server name is required");
	const previousName = String(
		input.previousName ?? input.previous_name ?? "",
	).trim();
	const transportType = String(
		input.transportType ?? input.transport_type ?? "",
	).trim();
	const next: JsonRecord =
		transportType === "stdio"
			? {
					transport: {
						type: "stdio",
						command: input.command,
						args: input.args,
						cwd: input.cwd,
						env: input.env,
					},
					disabled: input.disabled === true,
				}
			: {
					transport: {
						type: transportType === "sse" ? "sse" : "streamableHttp",
						url: input.url,
						headers: input.headers,
					},
					disabled: input.disabled === true,
				};
	// Hold the cross-process lock across read-modify-write so a concurrent writer
	// cannot clobber this upsert.
	updateMcpSettingsFileSync(resolveMcpSettingsPath(), (settings) => {
		const servers = ((settings.mcpServers as JsonRecord | undefined) ??
			{}) as JsonRecord;
		if (previousName && previousName !== name) {
			delete servers[previousName];
		}
		servers[name] = next;
		settings.mcpServers = servers;
	});
	return readMcpServersResponse();
}

export function deleteMcpServer(name: string): JsonRecord {
	if (!name) throw new Error("server name is required");
	// Hold the cross-process lock across read-modify-write so a concurrent writer
	// cannot resurrect the deleted server from a stale snapshot.
	updateMcpSettingsFileSync(resolveMcpSettingsPath(), (settings) => {
		const servers = ((settings.mcpServers as JsonRecord | undefined) ??
			{}) as JsonRecord;
		delete servers[name];
		settings.mcpServers = servers;
	});
	return readMcpServersResponse();
}

import type { ProviderSettingsManager } from "@cline/core";
import { describe, expect, it, vi } from "vitest";
import {
	cancelProviderOAuthLogin,
	cancelProviderOAuthLoginsForOwner,
	OAuthLoginCancelledError,
	runCancellableProviderOAuthLogin,
} from "./oauth-login";

type Credentials = { accessToken: string };

function makeManager(): ProviderSettingsManager {
	return {
		getProviderSettings: () => undefined,
	} as unknown as ProviderSettingsManager;
}

function makeDependencies(overrides: {
	login: () => Promise<Credentials>;
	save?: ReturnType<typeof vi.fn>;
}) {
	const save =
		overrides.save ??
		vi.fn(() => ({
			provider: "cline",
			auth: { accessToken: "saved-token" },
		}));
	return {
		dependencies: {
			login: overrides.login as never,
			save: save as never,
			markEnabled: vi.fn() as never,
		},
		save,
	};
}

describe("runCancellableProviderOAuthLogin", () => {
	it("saves credentials and returns the access token on success", async () => {
		const { dependencies, save } = makeDependencies({
			login: async () => ({ accessToken: "fresh-token" }),
		});

		const result = await runCancellableProviderOAuthLogin(
			makeManager(),
			"cline",
			() => undefined,
			{},
			dependencies,
		);

		expect(save).toHaveBeenCalledTimes(1);
		expect(result).toEqual({ provider: "cline", accessToken: "saved-token" });
	});

	it("rejects promptly on cancel and never persists a late completion", async () => {
		let resolveLogin: (credentials: Credentials) => void = () => undefined;
		const { dependencies, save } = makeDependencies({
			login: () =>
				new Promise<Credentials>((resolve) => {
					resolveLogin = resolve;
				}),
		});

		const pending = runCancellableProviderOAuthLogin(
			makeManager(),
			"cline",
			() => undefined,
			{},
			dependencies,
		);
		// Cancellation must reject the pending login right away, without
		// waiting for the browser round-trip to finish.
		expect(cancelProviderOAuthLogin("cline")).toBe(true);
		await expect(pending).rejects.toBeInstanceOf(OAuthLoginCancelledError);

		// The user completes the abandoned browser flow afterwards: the
		// credentials must be discarded, not saved.
		resolveLogin({ accessToken: "late-token" });
		await new Promise((resolve) => setTimeout(resolve, 0));
		expect(save).not.toHaveBeenCalled();
	});

	it("reports when there is no pending login to cancel", () => {
		expect(cancelProviderOAuthLogin("cline")).toBe(false);
	});

	it("cancels a dangling attempt when a new login starts for the provider", async () => {
		let resolveFirstLogin: (credentials: Credentials) => void = () => undefined;
		const firstSave = vi.fn(() => ({
			provider: "cline",
			auth: { accessToken: "first-token" },
		}));
		const first = runCancellableProviderOAuthLogin(
			makeManager(),
			"cline",
			() => undefined,
			{},
			makeDependencies({
				login: () =>
					new Promise<Credentials>((resolve) => {
						resolveFirstLogin = resolve;
					}),
				save: firstSave,
			}).dependencies,
		);

		const { dependencies: secondDependencies, save: secondSave } =
			makeDependencies({
				login: async () => ({ accessToken: "second-token" }),
			});
		const second = runCancellableProviderOAuthLogin(
			makeManager(),
			"cline",
			() => undefined,
			{},
			secondDependencies,
		);

		await expect(first).rejects.toBeInstanceOf(OAuthLoginCancelledError);
		await expect(second).resolves.toEqual({
			provider: "cline",
			accessToken: "saved-token",
		});

		// The first attempt's late completion is discarded.
		resolveFirstLogin({ accessToken: "first-token" });
		await new Promise((resolve) => setTimeout(resolve, 0));
		expect(firstSave).not.toHaveBeenCalled();
		expect(secondSave).toHaveBeenCalledTimes(1);
	});

	it("cancels pending logins when their transport connection closes", async () => {
		let resolveLogin: (credentials: Credentials) => void = () => undefined;
		const { dependencies, save } = makeDependencies({
			login: () =>
				new Promise<Credentials>((resolve) => {
					resolveLogin = resolve;
				}),
		});
		const connection = {};

		const pending = runCancellableProviderOAuthLogin(
			makeManager(),
			"cline",
			() => undefined,
			{ owner: connection },
			dependencies,
		);

		// A different connection closing must not cancel this login.
		expect(cancelProviderOAuthLoginsForOwner({})).toBe(0);

		// The initiating connection closing cancels it, so a lost cancel
		// command (transport drop, webview reload) cannot leave an abandoned
		// flow that persists credentials later.
		expect(cancelProviderOAuthLoginsForOwner(connection)).toBe(1);
		await expect(pending).rejects.toBeInstanceOf(OAuthLoginCancelledError);

		resolveLogin({ accessToken: "late-token" });
		await new Promise((resolve) => setTimeout(resolve, 0));
		expect(save).not.toHaveBeenCalled();
	});
});

import type { ProviderSettingsManager } from "@cline/core";
import {
	getProviderAuthStorageId,
	loginLocalProvider,
	markLocalProviderEnabled,
	saveLocalProviderOAuthCredentials,
} from "@cline/core";

export class OAuthLoginCancelledError extends Error {
	constructor(providerId: string) {
		super(`Sign-in was cancelled for provider "${providerId}"`);
		this.name = "OAuthLoginCancelledError";
	}
}

type PendingOAuthLogin = {
	cancelled: boolean;
	cancel: () => void;
	/** Transport connection that initiated the login, when known. */
	owner?: object;
};

// One pending browser round-trip per provider. Starting a new login for the
// same provider cancels the previous dangling attempt so an abandoned browser
// tab can never race a fresh sign-in.
const pendingOAuthLoginsByProvider = new Map<string, PendingOAuthLogin>();

export type OAuthLoginDependencies = {
	login: typeof loginLocalProvider;
	save: typeof saveLocalProviderOAuthCredentials;
	markEnabled: typeof markLocalProviderEnabled;
};

const defaultDependencies: OAuthLoginDependencies = {
	login: loginLocalProvider,
	save: saveLocalProviderOAuthCredentials,
	markEnabled: markLocalProviderEnabled,
};

/**
 * Runs a provider OAuth login that can be cancelled while the browser
 * round-trip is pending. Cancellation rejects the returned promise right away
 * AND guarantees the credentials of a late-completing browser flow are never
 * persisted, so the UI's signed-out state cannot diverge from disk.
 */
export async function runCancellableProviderOAuthLogin(
	manager: ProviderSettingsManager,
	providerId: string,
	openUrl: (url: string) => void,
	options: { owner?: object } = {},
	dependencies: OAuthLoginDependencies = defaultDependencies,
): Promise<{ provider: string; accessToken: string }> {
	const storageProviderId = getProviderAuthStorageId(providerId) ?? providerId;
	const existing = manager.getProviderSettings(storageProviderId);

	pendingOAuthLoginsByProvider.get(providerId)?.cancel();

	let rejectOnCancel: (error: Error) => void = () => undefined;
	const cancellation = new Promise<never>((_, reject) => {
		rejectOnCancel = reject;
	});
	const entry: PendingOAuthLogin = {
		cancelled: false,
		cancel: () => {
			entry.cancelled = true;
			rejectOnCancel(new OAuthLoginCancelledError(providerId));
		},
		owner: options.owner,
	};
	pendingOAuthLoginsByProvider.set(providerId, entry);

	try {
		// Promise.race subscribes to the login promise, so a late rejection
		// after cancellation is observed and cannot become an unhandled
		// rejection that kills the sidecar.
		const credentials = await Promise.race([
			dependencies.login(providerId, existing, openUrl),
			cancellation,
		]);
		if (entry.cancelled) {
			throw new OAuthLoginCancelledError(providerId);
		}
		const saved = dependencies.save(manager, providerId, existing, credentials);
		if (saved.provider !== providerId) {
			dependencies.markEnabled(manager, providerId, { tokenSource: "oauth" });
		}
		return {
			provider: providerId,
			accessToken: saved.auth?.accessToken ?? saved.apiKey ?? "",
		};
	} finally {
		if (pendingOAuthLoginsByProvider.get(providerId) === entry) {
			pendingOAuthLoginsByProvider.delete(providerId);
		}
	}
}

/**
 * Cancels the pending OAuth login for a provider, if any. Returns whether a
 * pending login existed. The cancelled attempt's credentials are discarded
 * even if the user later completes the already-open browser flow.
 */
export function cancelProviderOAuthLogin(providerId: string): boolean {
	const entry = pendingOAuthLoginsByProvider.get(providerId);
	if (!entry) {
		return false;
	}
	entry.cancel();
	pendingOAuthLoginsByProvider.delete(providerId);
	return true;
}

/**
 * Cancels every pending OAuth login initiated by a transport connection.
 * Called when that connection closes so a lost or undeliverable cancel
 * command (e.g. the webview reloaded or the transport dropped) can never
 * leave an abandoned browser flow that persists credentials later.
 */
export function cancelProviderOAuthLoginsForOwner(owner: object): number {
	let cancelled = 0;
	for (const [providerId, entry] of pendingOAuthLoginsByProvider) {
		if (entry.owner === owner) {
			entry.cancel();
			pendingOAuthLoginsByProvider.delete(providerId);
			cancelled += 1;
		}
	}
	return cancelled;
}

