import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

type StoreRecord = {
	sessionId: string;
	agentId?: string;
	parentAgentId?: string;
	parentSessionId?: string;
	status: string;
	prompt?: string;
	teamName?: string;
	provider: string;
	model: string;
	startedAt: string;
	endedAt?: string | null;
	messagesPath?: string;
