function writeMessages(name: string, messages: unknown[]): string {
	const path = join(dir, name);
	writeFileSync(path, JSON.stringify({ messages }), "utf8");
	return path;
}

const ROOT = "root1";

function record(overrides: Partial<StoreRecord> & { sessionId: string }) {
