		expect(listSessionAgents(ROOT)[0]?.lastAction).toBeUndefined();
	});
});

import { existsSync, readFileSync } from "node:fs";
import { SqliteSessionStore } from "@cline/core";
import type { MessageWithMetadata } from "@cline/shared";

/**
 * Child agents of a chat session: `spawn_agent` subagent runs and team-task
 * teammate runs. Both are persisted as sessions parented to the root session
 * (see the SDK's team-child-session-manager), which is the only place their
 * real status lives — the tool events forwarded to the webview carry no agent
 * attribution at all.
 */
export type SessionAgentRecord = {
	sessionId: string;
	agentId: string;
	parentAgentId?: string;
	/** "subagent" for spawn_agent runs, "teamtask" for team-task runs. */
	kind: "subagent" | "teamtask";
	status: string;
	/** The task the agent was given — its first prompt. */
	prompt?: string;
	/** Most recent thing the agent did, for an at-a-glance progress line. */
	lastAction?: string;
	teamName?: string;
	provider?: string;
	model?: string;
	startedAt: string;
	endedAt?: string;
	/** Whether a transcript exists to open yet. */
	hasMessages: boolean;
};

const TEAM_TASK_MARKER = "__teamtask__";
const LAST_ACTION_LIMIT = 160;

function readMessagesFile(path: string): MessageWithMetadata[] | null {
	if (!path || !existsSync(path)) {
		return null;
	}
	try {
		const parsed = JSON.parse(readFileSync(path, "utf8")) as
			| { messages?: MessageWithMetadata[] }
			| MessageWithMetadata[];
		if (Array.isArray(parsed)) {
			return parsed;
		}
		return Array.isArray(parsed.messages) ? parsed.messages : [];
	} catch {
		return null;
	}
}

/**
 * A child row records where its transcript was written. Deriving the path here
 * instead would mean duplicating the SDK's artifact layout, which nests child
 * transcripts under the root session directory keyed by agent id.
 */
function resolveChildMessagesPath(record: {
	messagesPath?: string;
}): string | undefined {
	return record.messagesPath?.trim() || undefined;
}

/**
 * Transcript of a child agent session, or null when the id is not a child or
 * nothing has been written yet. Lets the ordinary session-reading path open a
 * subagent session without knowing where child artifacts live.
 */
export function readChildSessionMessages(
	sessionId: string,
): MessageWithMetadata[] | null {
	const trimmed = sessionId.trim();
	if (!trimmed) {
		return null;
	}
	let record: { parentSessionId?: string; messagesPath?: string } | undefined;
	try {
		record = new SqliteSessionStore().get(trimmed);
	} catch {
		// No session database on this host; nothing to resolve.
		return null;
	}
	if (!record?.parentSessionId) {
		return null;
	}
	const messagesPath = resolveChildMessagesPath(record);
	return messagesPath ? readMessagesFile(messagesPath) : null;
}

function truncate(value: string, limit = LAST_ACTION_LIMIT): string {
	const collapsed = value.replace(/\s+/g, " ").trim();
	return collapsed.length > limit
		? `${collapsed.slice(0, limit)}...`
		: collapsed;
}

function asRecord(value: unknown): Record<string, unknown> | null {
	if (!value || typeof value !== "object" || Array.isArray(value)) {
		return null;
	}
	return value as Record<string, unknown>;
}

/**
 * Summarize the agent's most recent step from the tail of its transcript.
 *
 * A tool call names itself usefully ("Running read_files"), so it wins over
 * prose; assistant text is the fallback. Reasoning blocks are skipped — they
 * describe intent rather than an action taken.
 */
function deriveLastAction(messages: unknown[]): string | undefined {
	for (let index = messages.length - 1; index >= 0; index -= 1) {
		const message = asRecord(messages[index]);
		if (!message || message.role !== "assistant") {
			continue;
		}
		const content = message.content;
		if (typeof content === "string") {
			const text = truncate(content);
			if (text) {
				return text;
			}
			continue;
		}
		if (!Array.isArray(content)) {
			continue;
		}
		for (
			let blockIndex = content.length - 1;
			blockIndex >= 0;
			blockIndex -= 1
		) {
			const block = asRecord(content[blockIndex]);
			if (!block) {
				continue;
			}
			if (block.type === "tool_use" && typeof block.name === "string") {
				return `Running ${block.name}`;
			}
			if (block.type === "text" && typeof block.text === "string") {
				const text = truncate(block.text);
				if (text) {
					return text;
				}
			}
		}
	}
	return undefined;
}

export function listSessionAgents(
	rootSessionId: string,
	limit = 200,
): SessionAgentRecord[] {
	const trimmedRootId = rootSessionId.trim();
	if (!trimmedRootId) {
		return [];
	}
	const store = new SqliteSessionStore();
	const out: SessionAgentRecord[] = [];
	for (const record of store.listChildren(trimmedRootId, limit)) {
		const agentId = record.agentId?.trim();
		if (!agentId) {
			continue;
		}
		const messagesPath = resolveChildMessagesPath(record);
		const messages = messagesPath ? readMessagesFile(messagesPath) : null;
		out.push({
			sessionId: record.sessionId,
			agentId,
			parentAgentId: record.parentAgentId,
			kind: record.sessionId.includes(TEAM_TASK_MARKER)
				? "teamtask"
				: "subagent",
			status: record.status,
			prompt: record.prompt,
			lastAction: messages?.length ? deriveLastAction(messages) : undefined,
			teamName: record.teamName,
			provider: record.provider || undefined,
			model: record.model || undefined,
			startedAt: record.startedAt,
			endedAt: record.endedAt ?? undefined,
			hasMessages: Boolean(messages && messages.length > 0),
		});
	}
	return out;
}

import { existsSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import type { JsonRecord } from "../types";
import { parseF64Value, parseU64Value } from "./common";

function resolveGlobalHookLogPath(): string {
	const envPath = process.env.CLINE_HOOKS_LOG_PATH?.trim();
	if (envPath) return envPath;
	const dataDir =
		process.env.CLINE_DATA_DIR?.trim() ||
		join(process.env.HOME ?? process.env.USERPROFILE ?? "", ".cline", "data");
	return join(dataDir, "logs", "hooks.jsonl");
}

export async function readSessionHooks(
	sessionId: string,
	limit = 300,
): Promise<unknown[]> {
	const path = resolveGlobalHookLogPath();
	if (!existsSync(path)) {
		return [];
	}
	const raw = await readFile(path, "utf8");
	const max = Math.max(1, limit);
	const out: JsonRecord[] = [];
	let lineEnd = raw.length;
	for (let index = raw.length - 1; index >= -1; index -= 1) {
		if (index >= 0 && raw.charCodeAt(index) !== 10) {
			continue;
		}
		const line = raw.slice(index + 1, lineEnd).replace(/\r$/, "");
		lineEnd = index;
		if (!line.trim()) {
			continue;
		}
		try {
			const value = JSON.parse(line) as JsonRecord;

			// Filter to events belonging to this session.
			const rootSessionId =
				value.sessionContext &&
				typeof value.sessionContext === "object" &&
				typeof (value.sessionContext as JsonRecord).rootSessionId === "string"
					? ((value.sessionContext as JsonRecord).rootSessionId as string)
					: undefined;
			const eventSessionId =
				typeof value.sessionId === "string" ? value.sessionId : undefined;
			if (
				rootSessionId !== sessionId &&
				eventSessionId !== sessionId &&
				value.taskId !== sessionId
			) {
				continue;
			}

			const hookName =
				(typeof value.hookName === "string" && value.hookName) ||
				(typeof value.hook_event_name === "string" && value.hook_event_name) ||
				(typeof value.event === "string" && value.event) ||
				"";
			if (!hookName) {
				continue;
			}
			const usage =
				(value.turn &&
				typeof value.turn === "object" &&
				(value.turn as JsonRecord).usage &&
				typeof (value.turn as JsonRecord).usage === "object"
					? ((value.turn as JsonRecord).usage as JsonRecord)
					: undefined) ||
				(value.usage && typeof value.usage === "object"
					? (value.usage as JsonRecord)
					: undefined) ||
				(value.turn_usage && typeof value.turn_usage === "object"
					? (value.turn_usage as JsonRecord)
					: undefined);
			out.push({
				ts: typeof value.ts === "string" ? value.ts : "",
				hookName,
				agentId: value.agent_id,
				taskId: value.taskId ?? value.conversation_id,
				parentAgentId: value.parent_agent_id,
				iteration: parseU64Value(value.iteration),
				toolName:
					(value.tool_call &&
						typeof value.tool_call === "object" &&
						(value.tool_call as JsonRecord).name) ||
					(value.tool_result &&
						typeof value.tool_result === "object" &&
						(value.tool_result as JsonRecord).name),
				toolInput:
					(value.tool_call &&
						typeof value.tool_call === "object" &&
						(value.tool_call as JsonRecord).input) ||
					(value.tool_result &&
						typeof value.tool_result === "object" &&
						(value.tool_result as JsonRecord).input),
				toolOutput:
					value.tool_result && typeof value.tool_result === "object"
						? (value.tool_result as JsonRecord).output
						: undefined,
				toolError:
					value.tool_result && typeof value.tool_result === "object"
						? (value.tool_result as JsonRecord).error
						: undefined,
				inputTokens:
					parseU64Value(usage?.inputTokens) ??
					parseU64Value(usage?.input_tokens) ??
					parseU64Value(usage?.prompt_tokens),
				outputTokens:
					parseU64Value(usage?.outputTokens) ??
					parseU64Value(usage?.output_tokens) ??
					parseU64Value(usage?.completion_tokens),
				totalCost:
					parseF64Value(usage?.totalCost) ??
					parseF64Value(usage?.total_cost) ??
					parseF64Value(usage?.cost),
			});
			if (out.length >= max) {
				break;
			}
		} catch {
			// Ignore malformed lines.
		}
	}
	return out.reverse();
}

import { formatDisplayUserInput } from "@cline/shared";
import { readSessionManifest } from "../paths";
import type { JsonRecord } from "../types";

export function normalizeSessionTitle(
	title?: string | null,
): string | undefined {
	const trimmed = title?.trim();
	return trimmed ? formatDisplayUserInput(trimmed).slice(0, 120) : undefined;
}

export function parseTimestamp(value?: string | number | null): number {
	if (typeof value === "number" && Number.isFinite(value)) {
		return value;
	}
	const trimmed = typeof value === "string" ? value.trim() : "";
	if (!trimmed) {
		return Number.NEGATIVE_INFINITY;
	}
	const maybeEpoch = Number(trimmed);
	if (Number.isFinite(maybeEpoch)) {
		if (/^\d{10}$/.test(trimmed)) {
			return maybeEpoch * 1000;
		}
		return maybeEpoch;
	}
	const parsed = new Date(trimmed).getTime();
	return Number.isNaN(parsed) ? Number.NEGATIVE_INFINITY : parsed;
}

export function compareSessionRecordsByStartedAtDesc(
	left: JsonRecord,
	right: JsonRecord,
): number {
	const timeDelta =
		parseTimestamp(right.startedAt as string | number | undefined) -
		parseTimestamp(left.startedAt as string | number | undefined);
	if (timeDelta !== 0) {
		return timeDelta;
	}
	const leftId = String(left.sessionId ?? "");
	const rightId = String(right.sessionId ?? "");
	return rightId.localeCompare(leftId);
}

export function stringifyMessageContent(value: unknown): string {
	if (typeof value === "string") {
		return value;
	}
	if (Array.isArray(value)) {
		const parts: string[] = [];
		for (const block of value) {
			if (typeof block === "string") {
				if (block.trim()) {
					parts.push(block);
				}
				continue;
			}
			if (!block || typeof block !== "object") {
				continue;
			}
			const record = block as JsonRecord;
			const blockType = typeof record.type === "string" ? record.type : "";
			const piece =
				blockType === "text"
					? String(record.text ?? "")
					: blockType === "thinking"
						? String(record.thinking ?? "")
						: blockType === "tool_use"
							? `[tool] ${String(record.name ?? "tool_call")}`
							: blockType === "tool_result"
								? `[tool_result]\n${stringifyMessageContent(record.content)}`
								: blockType === "image"
									? "[image]"
									: blockType === "redacted_thinking"
										? "[redacted_thinking]"
										: typeof record.text === "string"
											? record.text
											: "";
			if (piece.trim()) {
				parts.push(piece);
			}
		}
		return parts.join("\n");
	}
	if (value && typeof value === "object") {
		const record = value as JsonRecord;
		if (typeof record.text === "string") {
			return record.text;
		}
	}
	return "";
}

function titleFromPrompt(prompt?: string | null): string | undefined {
	const normalized = normalizeSessionTitle(prompt ?? undefined);
	if (!normalized) {
		return undefined;
	}
	return normalized.split("\n")[0]?.trim().slice(0, 70) || undefined;
}

function titleFromMessages(messages: unknown[]): string | undefined {
	for (const role of ["user", "assistant"] as const) {
		for (const rawMessage of messages) {
			if (!rawMessage || typeof rawMessage !== "object") {
				continue;
			}
			const message = rawMessage as JsonRecord;
			if (message.role !== role) {
				continue;
			}
			const text = normalizeSessionTitle(
				stringifyMessageContent(message.content),
			);
			if (!text) {
				continue;
			}
			return text.split("\n")[0]?.trim().slice(0, 70) || undefined;
		}
	}
	return undefined;
}

export function derivePromptFromMessages(
	messages: unknown[],
): string | undefined {
	for (const message of messages) {
		if (!message || typeof message !== "object") {
			continue;
		}
		const record = message as JsonRecord;
		if (record.role !== "user") {
			continue;
		}
		const metadata =
			record.metadata && typeof record.metadata === "object"
				? (record.metadata as JsonRecord)
				: undefined;
		if (
			typeof metadata?.kind === "string" &&
			metadata.kind === "recovery_notice"
		) {
			continue;
		}
		const content = stringifyMessageContent(record.content);
		if (content.trim()) {
			return content.trim();
		}
	}
	return undefined;
}

export function resolveSessionListTitle(options: {
	sessionId: string;
	metadata?: unknown;
	prompt?: string | null;
	messages?: unknown[];
}): string {
	const metadataTitle =
		options.metadata && typeof options.metadata === "object"
			? normalizeSessionTitle(
					(options.metadata as JsonRecord).title as string | undefined,
				)
			: undefined;
	if (metadataTitle) {
		return metadataTitle.slice(0, 70);
	}
	const promptTitle = titleFromPrompt(options.prompt);
	if (promptTitle) {
		return promptTitle;
	}
	const messageTitle = options.messages
		? titleFromMessages(options.messages)
		: undefined;
	if (messageTitle) {
		return messageTitle;
	}
	return `Session ${options.sessionId.slice(-6)}`;
}

export function readSessionMetadataTitle(
	sessionId: string,
): string | undefined {
	const metadata = readSessionManifest(sessionId)?.metadata;
	if (!metadata || typeof metadata !== "object") {
		return undefined;
	}
	return normalizeSessionTitle(
		(metadata as JsonRecord).title as string | undefined,
	);
}

export function parseU64Value(value: unknown): number | undefined {
	if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
		return Math.trunc(value);
	}
	if (typeof value === "string") {
		const parsed = Number.parseInt(value, 10);
		if (Number.isFinite(parsed) && parsed >= 0) {
			return parsed;
		}
	}
	return undefined;
}

export function parseF64Value(value: unknown): number | undefined {
	if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
		return value;
	}
	if (typeof value === "string") {
		const parsed = Number.parseFloat(value);
		if (Number.isFinite(parsed) && parsed >= 0) {
			return parsed;
		}
	}
	return undefined;
}

export function normalizeChatFinishStatus(status?: string): string {
	const normalized = status?.trim().toLowerCase() || "";
	if (!normalized) {
		return "completed";
	}
	if (
		normalized.includes("cancel") ||
		normalized.includes("abort") ||
		normalized.includes("interrupt")
	) {
		return "cancelled";
	}
	if (normalized.includes("fail") || normalized.includes("error")) {
		return "failed";
	}
	if (normalized.includes("run") || normalized.includes("start")) {
		return "running";
	}
	if (
		normalized.includes("complete") ||
		normalized.includes("done") ||
		normalized.includes("stop") ||
		normalized.includes("mistake_limit") ||
		normalized.includes("mistake-limit") ||
		normalized.includes("max_iteration") ||
		normalized.includes("max-iteration")
	) {
		return "completed";
	}
	return "idle";
}

import { existsSync, readdirSync, rmSync } from "node:fs";
import { join } from "node:path";
import { SqliteSessionStore } from "@cline/core";
import { readSessionManifest, sharedSessionDataDir } from "../paths";
import type { JsonRecord } from "../types";
import {
	compareSessionRecordsByStartedAtDesc,
	derivePromptFromMessages,
	resolveSessionListTitle,
} from "./common";
import { readPersistedChatMessages } from "./messages";

/**
 * Minimal context shape required by discoverChatSessions so both the host
 * backend and the sidecar can call it without pulling in CLI-specific code.
 */
export type DiscoveryChatContext = {
	liveSessions: Map<
		string,
		{
			busy: boolean;
			prompt?: string;
			title?: string;
			messages: unknown[];
			status: string;
			config: JsonRecord;
			startedAt: number;
			endedAt?: number;
		}
	>;
};

function trimKnownString(value: unknown): string | undefined {
	if (typeof value !== "string") {
		return undefined;
	}
	const trimmed = value.trim();
	if (!trimmed) {
		return undefined;
	}
	return trimmed.toLowerCase() === "unknown" ? undefined : trimmed;
}

export function discoverChatSessions(
	ctx: DiscoveryChatContext,
	limit = 300,
): unknown[] {
	const out: JsonRecord[] = [];
	const store = new SqliteSessionStore();
	for (const [sessionId, session] of ctx.liveSessions.entries()) {
		if (!session.busy && !session.prompt && session.messages.length === 0) {
			continue;
		}
		const prompt = session.prompt ?? derivePromptFromMessages(session.messages);
		const resolvedTitle = resolveSessionListTitle({
			sessionId,
			metadata: session.title ? { title: session.title } : undefined,
			prompt,
			messages: session.messages,
		});
		const persistedMetadata = store.get(sessionId)?.metadata;
		out.push({
			sessionId,
			status: session.status,
			provider: session.config.provider ?? "",
			model: session.config.model ?? "",
			cwd: session.config.cwd ?? session.config.workspaceRoot ?? "",
			workspaceRoot: session.config.workspaceRoot ?? "",
			prompt,
			startedAt: String(session.startedAt),
			endedAt: session.endedAt ? String(session.endedAt) : undefined,
			metadata: {
				...(persistedMetadata ?? {}),
				title: resolvedTitle,
			},
		});
	}

	const base = sharedSessionDataDir();
	if (existsSync(base)) {
		for (const entry of readdirSync(base, { withFileTypes: true })) {
			if (!entry.isDirectory()) {
				continue;
			}
			const sessionId = entry.name.trim();
			if (!sessionId || out.some((item) => item.sessionId === sessionId)) {
				continue;
			}
			// Skip subagent / team-task child sessions — they are shown
			// under their parent, not as top-level sidebar entries.
			if (sessionId.includes("__teamtask__") || sessionId.includes("__sub__")) {
				continue;
			}
			if (!store.get(sessionId)) {
				try {
					rmSync(join(base, sessionId), { recursive: true, force: true });
				} catch {
					// Ignore cleanup failures and keep orphaned artifacts hidden.
				}
				continue;
			}
			const manifest = readSessionManifest(sessionId) ?? {};
			// Skip sessions explicitly marked as subagent.
			if (manifest.source === "subagent") {
				continue;
			}
			const provider = trimKnownString(manifest.provider);
			const model = trimKnownString(manifest.model);
			if (!provider || !model) {
				continue;
			}
			const messages = readPersistedChatMessages(sessionId) ?? [];
			if (messages.length === 0) {
				continue;
			}
			const metadata =
				manifest.metadata && typeof manifest.metadata === "object"
					? { ...(manifest.metadata as JsonRecord) }
					: undefined;
			const prompt = derivePromptFromMessages(messages);
			const resolvedTitle = resolveSessionListTitle({
				sessionId,
				metadata,
				prompt,
				messages,
			});
			out.push({
				sessionId,
				status: "completed",
				provider,
				model,
				cwd: manifest.cwd ?? "",
				workspaceRoot:
					manifest.workspace_root ??
					manifest.workspaceRoot ??
					manifest.cwd ??
					"",
				prompt,
				startedAt: String(
					manifest.started_at ?? manifest.startedAt ?? Date.now(),
				),
				endedAt:
					(manifest.ended_at ?? manifest.endedAt)
						? String(manifest.ended_at ?? manifest.endedAt)
						: undefined,
				metadata: {
					...(metadata ?? {}),
					title: resolvedTitle,
				},
			});
		}
	}

	out.sort(compareSessionRecordsByStartedAtDesc);
	return out.slice(0, Math.max(1, limit));
}

export function mergeDiscoveredSessionLists(
	chat: unknown[],
	cli: unknown[],
	limit: number,
): unknown[] {
	const merged = new Map<string, unknown>();
	for (const item of [...chat, ...cli]) {
		if (!item || typeof item !== "object") {
			continue;
		}
		const sessionId = String(
			(item as JsonRecord).sessionId ?? (item as JsonRecord).session_id ?? "",
		).trim();
		if (!sessionId || merged.has(sessionId)) {
			continue;
		}
		const normalized = item as JsonRecord;
		merged.set(sessionId, {
			...normalized,
			sessionId,
			startedAt:
				normalized.startedAt ?? normalized.started_at ?? String(Date.now()),
			endedAt: normalized.endedAt ?? normalized.ended_at,
			workspaceRoot:
				normalized.workspaceRoot ??
				normalized.workspace_root ??
				normalized.cwd ??
				"",
		});
	}
	return Array.from(merged.values())
		.sort((left, right) =>
			compareSessionRecordsByStartedAtDesc(
				left as JsonRecord,
				right as JsonRecord,
			),
		)
		.slice(0, limit);
}

