const MARKETPLACE_CATALOG_URL =
	process.env.CLINE_MARKETPLACE_CATALOG_URL?.trim() ||
	"https://cline.github.io/marketplace/catalog.json";

export const dynamic = "force-static";

const EMPTY_MARKETPLACE_CATALOG = {
	version: 1,
	counts: {
		total: 0,
		plugins: 0,
		skills: 0,
		mcps: 0,
	},
	tags: [],
	entries: [],
};

export async function GET() {
	try {
		const response = await fetch(MARKETPLACE_CATALOG_URL, {
			headers: { Accept: "application/json" },
		});
		if (!response.ok) {
			return Response.json({
				...EMPTY_MARKETPLACE_CATALOG,
				error:
					`Failed to fetch marketplace catalog: ${response.status} ${response.statusText}`.trim(),
			});
		}
		return Response.json(await response.json());
	} catch (error) {
		return Response.json({
			...EMPTY_MARKETPLACE_CATALOG,
			error:
				error instanceof Error
					? error.message
					: "Failed to fetch marketplace catalog",
		});
	}
}

@import "@fontsource-variable/inter";
@import "@fontsource-variable/geist-mono";
@import "tailwindcss";
@import "tw-animate-css";
@import "@cline/ui/theme/index.css";
@import "@cline/ui/components.css";
@import "@cline/ui/components/agent-chat.css";
/* Unlayered on purpose: its chat-polish rules must beat Streamdown's layered
 * Tailwind utilities (from the @source below) without !important. */
@import "@cline/ui/components/markdown.css";

@source "../../node_modules/streamdown/dist";

@layer base {
	html,
	body {
		height: 100%;
		min-height: 100vh;
		overflow: hidden;
		/* Keep scroll momentum inside the app: without this, hitting the end
		 * of an inner scroller rubber-bands the whole window like a web page. */
		overscroll-behavior: none;
	}

	#__next {
		height: 100%;
	}

	/*
	 * Native-app chrome: labels, buttons, and panel text must not highlight
	 * when the user drags across them. Content the user genuinely reads and
	 * copies — chat messages, code, diffs, form fields — opts back in below.
	 */
	body {
		-webkit-user-select: none;
		user-select: none;
	}

	input,
	textarea,
	[contenteditable="true"] {
		-webkit-user-select: text;
		user-select: text;
	}

	/* Selectable content surfaces: chat message bodies (incl. markdown and
	 * code blocks), reasoning/tool panels, and diff text. */
	.cline-chat-message-content,
	.cline-markdown,
	.cline-chat-selectable,
	pre,
	code {
		-webkit-user-select: text;
		user-select: text;
	}
}

/* Chat Markdown polish and the streaming-title shimmer live in
 * @cline/ui (components/markdown.css and agent-chat.css), shared with the
 * cloud dashboard so both products render assistant output identically. */

/* Softens the welcome <-> conversation swap: the hero and the message grid
 * replace each other in a single commit, which otherwise reads as a hard
 * white flash. Plays whenever the element (re)becomes visible — display:none
 * resets animations, so toggling Tailwind's `hidden` re-triggers it. */
@keyframes cline-view-enter {
	from {
		opacity: 0;
		transform: translateY(4px);
	}
	to {
		opacity: 1;
		transform: none;
	}
}

.cline-view-enter {
	animation: cline-view-enter 180ms ease-out;
}

@media (prefers-reduced-motion: reduce) {
	.cline-view-enter {
		animation: none;
	}
}

