function hubPort(url: string | null): string | null {
	if (!url) {
		return null;
	}
	try {
		return new URL(url).port || null;
	} catch {
		return null;
	}
}

const SETTINGS_SECTION_ICONS = {
	General: SlidersHorizontal,
	Models: Bot,
	Channels: Radio,
	Schedules: Clock3,
	Account: CircleUserRound,
	Plugins: Plug,
	Skills: Activity,
	MCP: Server,
	Hooks: Code,
	Rules: FileText,
	Agents: Bot,
	Tools: Wrench,
} satisfies Record<SettingsSection, typeof Settings>;

function SettingsSectionNavigation({
	activeSection,
	collapsed,
	onSelect,
}: {
	activeSection: SettingsSection;
	collapsed: boolean;
	onSelect: (section: SettingsSection) => void;
}) {
	const renderSectionButton = (section: SettingsSection) => {
		const Icon = SETTINGS_SECTION_ICONS[section];
		return (
			<Button
				aria-current={activeSection === section ? "page" : undefined}
				aria-label={section}
				className={cn(
					"min-w-0 justify-start",
					activeSection === section &&
						"bg-surface-hover text-sidebar-foreground",
					collapsed && "size-9 justify-center px-0",
				)}
				key={section}
				onClick={() => onSelect(section)}
				title={section}
				type="button"
				variant="sidebarItem"
			>
				<Icon className="size-4 shrink-0" />
				{!collapsed ? <span className="truncate">{section}</span> : null}
			</Button>
		);
	};

	return (
		<nav
			aria-label="Settings sections"
			className={cn(
				"flex h-full min-h-0 flex-col overflow-y-auto overflow-x-hidden",
				collapsed ? "w-full items-start" : "w-full",
			)}
		>
			{!collapsed ? (
				<p className="px-2 pb-2 text-sm font-medium text-muted-foreground">
					Settings
				</p>
			) : null}
			{SETTINGS_SECTIONS.map(renderSectionButton)}
			{!collapsed ? (
				<p className="px-2 pb-2 pt-4 text-sm font-medium text-muted-foreground">
					Customizations
				</p>
			) : (
				<div className="my-2 h-px w-6 shrink-0 bg-sidebar-border" />
			)}
			{CUSTOMIZATION_SECTIONS.map(renderSectionButton)}
		</nav>
	);
}

export function AgentSidebar({
	canNavigateBack = false,
	canNavigateForward = false,
	onHome,
	onNavigateBack,
	onNavigateForward,
	onNewThread,
	onSettingsSectionChange,
	setView,
	settingsSection,
	view,
	activeSessionId,
	sessionHistory,
}: {
	canNavigateBack?: boolean;
	canNavigateForward?: boolean;
	onHome: () => void;
	onNavigateBack?: () => void;
	onNavigateForward?: () => void;
	onNewThread?: () => void;
	onSettingsSectionChange: (section: SettingsSection) => void;
	setView: (view: AppView) => void;
	settingsSection: SettingsSection;
	view: AppView;
	activeSessionId?: string | null;
	sessionHistory: UseSessionHistoryResult;
}) {
	const { isMobile, setOpen, setOpenMobile, state } = useSidebar();
	const isCollapsed = !isMobile && state === "collapsed";
	const { user, activeOrganization } = useAccount();
	const { displayName, email } = user || {};
	const username = displayName?.split(" ")?.[0] || email?.split("@")?.[0];
	const accountName = username?.trim() || "Cline Desktop";
	const accountScope = user
		? (activeOrganization?.name ?? "Personal")
		: undefined;
	const accountInitial = accountName.charAt(0).toUpperCase();
	const {
		deleteThread: deleteHistoryThread,
		forkThread: forkHistoryThread,
		isLoadingHistory,
		isLoadingMore,
		loadOlderSessions,
		loadMoreSessions,
		mayHaveMoreSessions,
		openThread: openHistoryThread,
		pendingAction,
		renameThread,
		setThreadPinned,
		threads,
		unreadSessionIds,
	} = sessionHistory;
	const activeThread = activeSessionId ?? "";
	const [filter, setFilter] = useState<FilterOption>("All");
	const [sourceFilter, setSourceFilter] = useState(ALL_SESSION_SOURCES);
	const [sortMode, setSortMode] = useState<SidebarSortMode>("time");
	const [searchOpen, setSearchOpen] = useState(false);
	const [searchQuery, setSearchQuery] = useState("");
	const [showMoreCount, setShowMoreCount] = useState(
		INITIAL_VISIBLE_THREAD_COUNT,
	);
	const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
	const [editingTitle, setEditingTitle] = useState("");
	const [deleteConfirmThread, setDeleteConfirmThread] = useState<Thread | null>(
		null,
	);
	const [collapsedProjects, setCollapsedProjects] = useState<Set<string>>(
		() => new Set(),
	);
	const [projectVisibleCounts, setProjectVisibleCounts] = useState<
		Record<string, number>
	>({});
	const [appVersion, setAppVersion] = useState<string | null>(null);
	const [hubStatus, setHubStatus] = useState<HubStatus | null>(null);

	const loadProcessContext = useCallback(async () => {
		try {
			const context = await desktopClient.invoke<DesktopProcessContext>(
				"get_process_context",
			);
			const version =
				typeof context?.appVersion === "string"
					? context.appVersion.trim()
					: "";
			setAppVersion(version || null);
			const hubUrl =
				typeof context?.hub?.url === "string"
					? context.hub.url.trim() || null
					: null;
			setHubStatus({
				connected: context?.hub?.status === "connected",
				error:
					typeof context?.hub?.error === "string"
						? context.hub.error.trim() || null
						: null,
				url: hubUrl,
			});
		} catch (error) {
			setHubStatus({
				connected: false,
				error:
					error instanceof Error
						? error.message
						: "Unable to read Cline Hub status.",
				url: null,
			});
		}
	}, []);

	useEffect(() => {
		void loadProcessContext();
	}, [loadProcessContext]);

	useEffect(() => {
		if (isCollapsed && searchOpen) {
			setSearchOpen(false);
		}
	}, [isCollapsed, searchOpen]);

	const sourceOptions = useMemo(() => getSessionSources(threads), [threads]);
	const filteredThreads = useMemo(() => {
		let filtered = filterSessionsBySource(threads, sourceFilter);
		if (searchQuery) {
			const q = searchQuery.toLowerCase();
			filtered = filtered.filter(
				(t) =>
					t.title.toLowerCase().includes(q) ||
					t.codebase.toLowerCase().includes(q) ||
					t.workspacePath.toLowerCase().includes(q),
			);
		}
		switch (filter) {
			case "Running":
				return filtered.filter((t) => t.status === "running");
			case "Schedules":
				return filtered.filter((t) => t.isScheduled);
			case "Favorites":
				return filtered.filter((t) => t.pinned);
			default:
				return filtered;
		}
	}, [filter, searchQuery, sourceFilter, threads]);
	const closeMobileSidebar = useCallback(() => {
		if (isMobile) setOpenMobile(false);
	}, [isMobile, setOpenMobile]);

	const openThread = useCallback(
		(threadId: string) => {
			openHistoryThread(threadId);
			closeMobileSidebar();
		},
		[closeMobileSidebar, openHistoryThread],
	);

	const openNewThread = useCallback(() => {
		onNewThread?.();
		closeMobileSidebar();
	}, [closeMobileSidebar, onNewThread]);
	const openHome = useCallback(() => {
		onHome();
		closeMobileSidebar();
	}, [closeMobileSidebar, onHome]);
	const openSessions = useCallback(() => {
		setView("sessions");
		closeMobileSidebar();
	}, [closeMobileSidebar, setView]);
	const openSettings = useCallback(() => {
		setView("settings");
		closeMobileSidebar();
	}, [closeMobileSidebar, setView]);
	const openSettingsSection = useCallback(
		(section: SettingsSection) => {
			onSettingsSectionChange(section);
			closeMobileSidebar();
		},
		[closeMobileSidebar, onSettingsSectionChange],
	);
	const navigateBack = useCallback(() => {
		onNavigateBack?.();
	}, [onNavigateBack]);
	const navigateForward = useCallback(() => {
		onNavigateForward?.();
	}, [onNavigateForward]);

	const startRenameThread = useCallback((thread: Thread) => {
		setEditingSessionId(thread.id);
		setEditingTitle(normalizeTitle(thread.title));
	}, []);

	const cancelRenameThread = useCallback(() => {
		setEditingSessionId(null);
		setEditingTitle("");
	}, []);

	const commitRenameThread = useCallback(
		async (thread: Thread) => {
			const renamed = await renameThread(thread.id, editingTitle);
			if (renamed) {
				cancelRenameThread();
			}
		},
		[cancelRenameThread, editingTitle, renameThread],
	);

	const forkThread = useCallback(
		async (thread: Thread) => {
			await forkHistoryThread(thread.id);
		},
		[forkHistoryThread],
	);

	const toggleFavorite = useCallback(
		async (thread: Thread) => {
			await setThreadPinned(thread.id, !thread.pinned);
		},
		[setThreadPinned],
	);

	const requestDeleteThread = useCallback((thread: Thread) => {
		setDeleteConfirmThread(thread);
	}, []);

	const deleteThread = useCallback(
		async (thread: Thread) => {
			await deleteHistoryThread(thread.id);
			setDeleteConfirmThread(null);
		},
		[deleteHistoryThread],
	);

	const pinnedThreads = useMemo(
		() => filteredThreads.filter((t) => t.pinned),
		[filteredThreads],
	);
	const sessionThreads = useMemo(
		() => filteredThreads.filter((t) => !t.pinned),
		[filteredThreads],
	);
	const displayedThreads = useMemo(
		() =>
			filter === "All"
				? [...pinnedThreads, ...sessionThreads.slice(0, showMoreCount)]
				: [...pinnedThreads, ...sessionThreads].slice(0, showMoreCount),
		[filter, pinnedThreads, sessionThreads, showMoreCount],
	);
	const showTimeShowMore =
		sessionThreads.length > showMoreCount ||
		(filter === "All" && !searchQuery && mayHaveMoreSessions);
	const projectGroups = useMemo(
		() => groupThreadsByProject([...pinnedThreads, ...sessionThreads]),
		[pinnedThreads, sessionThreads],
	);

	const toggleProject = useCallback((project: string) => {
		setCollapsedProjects((current) => {
			const next = new Set(current);
			if (next.has(project)) next.delete(project);
			else next.add(project);
			return next;
		});
	}, []);
	const showMoreForProject = useCallback((project: string) => {
		setProjectVisibleCounts((current) => ({
			...current,
			[project]:
				(current[project] ?? INITIAL_VISIBLE_THREAD_COUNT) +
				INITIAL_VISIBLE_THREAD_COUNT,
		}));
	}, []);

	const filterMenu = (
		<DropdownMenu>
			<DropdownMenuTrigger asChild>
				<Button
					aria-label="Filter sessions"
					className="m-0! inline-flex size-8 items-center justify-center rounded-md p-0! text-muted-foreground hover:bg-surface-hover hover:text-sidebar-foreground"
					variant="ghost"
					size="icon"
				>
					<Filter className="size-3 stroke-2" />
				</Button>
			</DropdownMenuTrigger>
			<DropdownMenuContent align="end" className="w-36">
				<DropdownMenuLabel>Session type</DropdownMenuLabel>
				<DropdownMenuRadioGroup
					onValueChange={(value) => {
						setFilter(value as FilterOption);
						setShowMoreCount(INITIAL_VISIBLE_THREAD_COUNT);
						setProjectVisibleCounts({});
					}}
					value={filter}
				>
					{filterOptions.map((opt) => (
						<DropdownMenuRadioItem key={opt} value={opt}>
							{opt}
						</DropdownMenuRadioItem>
					))}
				</DropdownMenuRadioGroup>
				{sourceOptions.length > 0 ? (
					<>
						<DropdownMenuSeparator />
						<DropdownMenuLabel>Source</DropdownMenuLabel>
						<DropdownMenuRadioGroup
							onValueChange={(value) => {
								setSourceFilter(value);
								setShowMoreCount(INITIAL_VISIBLE_THREAD_COUNT);
								setProjectVisibleCounts({});
							}}
							value={sourceFilter}
						>
							<DropdownMenuRadioItem value={ALL_SESSION_SOURCES}>
								All sources
							</DropdownMenuRadioItem>
							{sourceOptions.map((source) => (
								<DropdownMenuRadioItem key={source} value={source}>
									{getSessionSourceLabel(source)}
								</DropdownMenuRadioItem>
							))}
						</DropdownMenuRadioGroup>
					</>
				) : null}
			</DropdownMenuContent>
		</DropdownMenu>
	);
	const sortMenu = (
		<DropdownMenu>
			<DropdownMenuTrigger asChild>
				<Button
					aria-label={`Sort sessions: ${sortMode === "time" ? "Time" : "Project"}`}
					className="m-0! inline-flex size-8 items-center justify-center rounded-md p-0! text-muted-foreground hover:bg-surface-hover hover:text-sidebar-foreground"
					size="icon"
					title={sortMode === "time" ? "Sort by time" : "Sort by project"}
					variant="ghost"
				>
					<ArrowDownUp className="size-3.5" />
				</Button>
			</DropdownMenuTrigger>
			<DropdownMenuContent align="end" className="w-44">
				<DropdownMenuRadioGroup
					onValueChange={(value) => {
						if (value === "time" || value === "project") {
							setSortMode(value);
						}
					}}
					value={sortMode}
				>
					<DropdownMenuRadioItem value="time">
						<Clock3 className="size-4" />
						Sort by time
					</DropdownMenuRadioItem>
					<DropdownMenuRadioItem value="project">
						<FolderTree className="size-4" />
						Sort by project
					</DropdownMenuRadioItem>
				</DropdownMenuRadioGroup>
			</DropdownMenuContent>
		</DropdownMenu>
	);
	const threadItem = (thread: Thread) => (
		<ThreadItem
			editTitle={editingTitle}
			editing={editingSessionId === thread.id}
			isActive={activeThread === thread.id}
			key={thread.id}
			onCancelRename={cancelRenameThread}
			onClick={() => openThread(thread.id)}
			onCommitRename={() => void commitRenameThread(thread)}
			onDelete={() => requestDeleteThread(thread)}
			onEditTitleChange={setEditingTitle}
			onFork={() => void forkThread(thread)}
			onRename={() => startRenameThread(thread)}
			onToggleFavorite={() => void toggleFavorite(thread)}
			pendingAction={
				pendingAction?.sessionId === thread.id ? pendingAction.action : null
			}
			thread={thread}
			unread={unreadSessionIds.has(thread.id)}
		/>
	);

	return (
		<>
			<div className="flex h-full min-h-0 w-full min-w-0 shrink-0 flex-col overflow-hidden bg-sidebar text-sidebar-foreground">
				<div
					className={cn(
						"flex h-12 shrink-0 items-center justify-end gap-0.5 pr-2 pl-19",
						isCollapsed && "px-0",
					)}
					data-tauri-drag-region
				>
					{!isCollapsed ? (
						<>
							<Button
								aria-label="Previous page"
								className="size-7 text-muted-foreground hover:bg-surface-hover"
								disabled={!canNavigateBack}
								onClick={navigateBack}
								size="icon"
								title="Previous page"
								type="button"
								variant="ghost"
							>
								<ChevronLeft className="size-4" />
							</Button>
							<Button
								aria-label="Next page"
								className="size-7 text-muted-foreground hover:text-sidebar-foreground"
								disabled={!canNavigateForward}
								onClick={navigateForward}
								size="icon"
								title="Next page"
								type="button"
								variant="ghost"
							>
								<ChevronRight className="size-4" />
							</Button>
						</>
					) : null}
				</div>

				<div
					className={cn(
						"flex h-10 shrink-0 items-center justify-between px-2",
						isCollapsed && "px-1.5",
					)}
				>
					<div className="flex min-w-0 items-center gap-0.5">
						<HoverCard
							closeDelay={100}
							openDelay={0}
							onOpenChange={(open) => {
								if (open) {
									void loadProcessContext();
								}
							}}
						>
							<HoverCardTrigger asChild>
								<button
									aria-label="Cline home"
									className={cn(
										"flex size-8 shrink-0 items-center justify-center rounded-md text-sidebar-foreground hover:bg-surface-hover focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sidebar-ring",
										isCollapsed && "size-9",
									)}
									onClick={openHome}
									title="Home"
									type="button"
								>
									<ClineLogo className="size-5" />
								</button>
							</HoverCardTrigger>
							<HoverCardContent
								align="start"
								className="w-64 p-3"
								side="bottom"
							>
								<p className="text-sm font-medium">
									{productNameForVersion(appVersion)}
								</p>
								<p className="mt-0.5 text-xs text-muted-foreground">
									{appVersion ? `Version ${appVersion}` : "Version unavailable"}
								</p>
								<div className="mt-3 border-border border-t pt-3">
									<div className="flex items-center gap-2 text-xs">
										<span
											aria-hidden="true"
											className={cn(
												"h-2 w-2 shrink-0 rounded-full",
												hubStatus?.connected
													? "bg-emerald-500"
													: "bg-muted-foreground",
											)}
										/>
										<span className="font-medium">
											Cline Hub @{hubPort(hubStatus?.url ?? null) ?? "unknown"}
										</span>
									</div>
									{hubStatus && !hubStatus.connected && (
										<p className="mt-1 text-[11px] text-destructive">
											{hubStatus.error ?? "Cline Hub is not connected."}
										</p>
									)}
								</div>
							</HoverCardContent>
						</HoverCard>
						{!isCollapsed && isBetaVersion(appVersion) ? (
							<Badge
								className="ml-0.5 px-1.5 py-0 text-[10px] uppercase tracking-wide"
								title={`${BETA_PRODUCT_NAME} — beta builds install side by side with the stable app and update from the beta channel`}
								variant="secondary"
							>
								Beta
							</Badge>
						) : null}
						{!isCollapsed ? <AppUpdateIndicator /> : null}
					</div>
					{!isCollapsed ? (
						<Button
							aria-label="New Session"
							className="size-8 shrink-0 justify-center px-0"
							onClick={openNewThread}
							title="New Session"
							type="button"
							variant="sidebarItem"
						>
							<Plus className="size-4" />
						</Button>
					) : null}
				</div>

				{isCollapsed ? (
					<div className="mt-2 flex min-h-0 flex-1 flex-col items-start gap-1 px-1.5">
						<AppUpdateIndicator className="mx-auto size-9" />
						{view === "settings" ? (
							<SettingsSectionNavigation
								activeSection={settingsSection}
								collapsed
								onSelect={openSettingsSection}
							/>
						) : null}
						<Button
							aria-label="Expand sidebar"
							className="mt-auto size-9 justify-center px-0"
							onClick={() => setOpen(true)}
							title="Expand sidebar"
							type="button"
							variant="sidebar"
						>
							<PanelLeftOpen className="size-4" />
						</Button>
					</div>
				) : view === "settings" ? (
					<div className="mt-5 min-h-0 flex-1 px-3">
						<SettingsSectionNavigation
							activeSection={settingsSection}
							collapsed={false}
							onSelect={openSettingsSection}
						/>
					</div>
				) : (
					<>
						<div className="mt-5 shrink-0 pl-4 pr-2">
							<div className="flex h-8 items-center justify-between gap-2">
								<button
									className={cn(
										"min-w-0 truncate text-sm font-medium text-muted-foreground",
										view === "sessions" && "text-sidebar-foreground",
									)}
									onClick={openSessions}
									type="button"
								>
									{sortMode === "time" ? "Sessions" : "Projects"}
								</button>
								<div className="flex shrink-0 items-center gap-0.5">
									<Button
										aria-label="Search sessions"
										className="m-0! size-8 p-0! text-muted-foreground hover:bg-surface-hover"
										onClick={() => setSearchOpen((current) => !current)}
										size="icon"
										title="Search sessions"
										type="button"
										variant="ghost"
									>
										<Search className="size-3.5" />
									</Button>
									{sortMenu}
									{filterMenu}
								</div>
							</div>
							{searchOpen ? (
								<div className="mt-1 flex min-w-0 items-center gap-2 overflow-hidden rounded-md border border-sidebar-border bg-background/70 px-2 py-1">
									<Search className="size-4 shrink-0" />
									<Input
										className="h-7 min-w-0 flex-1 border-0 bg-transparent px-0 text-sm text-sidebar-foreground shadow-none outline-none placeholder:text-muted-foreground focus-visible:ring-0"
										autoFocus={true}
										onChange={(e) => setSearchQuery(e.target.value)}
										placeholder="Search sessions..."
										value={searchQuery}
									/>
								</div>
							) : null}
						</div>

						<div className="mt-1 min-h-0 w-full flex-1">
							<ScrollArea className="h-full min-h-0 w-full min-w-0">
								<div className="flex min-w-0 flex-col gap-0.5 pb-3 px-2">
									{isLoadingHistory && threads.length === 0 ? (
										<div className="p-4 text-xs text-muted-foreground">
											Loading session history...
										</div>
									) : (
										<>
											{sortMode === "time"
												? displayedThreads.map(threadItem)
												: projectGroups.map((project) => {
														const visibleCount =
															projectVisibleCounts[project.id] ??
															INITIAL_VISIBLE_THREAD_COUNT;
														return (
															<ProjectSection
																collapsed={collapsedProjects.has(project.id)}
																key={project.id}
																label={project.label}
																onToggle={() => toggleProject(project.id)}
															>
																{project.threads
																	.slice(0, visibleCount)
																	.map(threadItem)}
																{project.threads.length > visibleCount ? (
																	<Button
																		className="pl-2!"
																		onClick={() =>
																			showMoreForProject(project.id)
																		}
																		type="button"
																		variant="sidebarText"
																	>
																		Show more in {project.label}
																		<ChevronDown className="size-3" />
																	</Button>
																) : null}
															</ProjectSection>
														);
													})}

											{(sortMode === "time"
												? displayedThreads.length === 0
												: projectGroups.length === 0) && (
												<div className="px-2 py-4 text-xs text-muted-foreground">
													{searchQuery
														? "No sessions match your search."
														: "No sessions found in history."}
												</div>
											)}
										</>
									)}
									{sortMode === "time" && showTimeShowMore && (
										<Button
											// `pl-0!`: the default button size adds
											// `has-[>svg]:px-3`, and that modifier beats a plain
											// `pl-0` on specificity, so the icon child was
											// re-indenting the row.
											className="pl-0!"
											disabled={isLoadingMore}
											onClick={() => {
												const nextCount =
													showMoreCount + INITIAL_VISIBLE_THREAD_COUNT;
												setShowMoreCount(nextCount);
												void loadMoreSessions(nextCount);
											}}
											type="button"
											variant="sidebarText"
										>
											{isLoadingMore ? (
												<>
													<Loader2 className="size-3 animate-spin" />
													Loading...
												</>
											) : (
												<div className="ml-2 flex items-center gap-1">
													Show more
													<ChevronDown className="size-3" />
												</div>
											)}
										</Button>
									)}
									{sortMode === "project" &&
										filter === "All" &&
										!searchQuery &&
										mayHaveMoreSessions && (
											<Button
												className="pl-0!"
												disabled={isLoadingMore}
												onClick={() => void loadOlderSessions()}
												type="button"
												variant="sidebarText"
											>
												{isLoadingMore ? (
													<>
														<Loader2 className="size-3 animate-spin" />
														Loading older projects...
													</>
												) : (
													<>
														Load older projects
														<ChevronDown className="size-3" />
													</>
												)}
											</Button>
										)}
								</div>
							</ScrollArea>
						</div>
					</>
				)}

				<div
					className={cn(
						"shrink-0 border-t border-sidebar-border/70 py-3",
						isCollapsed ? "px-1.5" : "px-2",
					)}
				>
					{user && !isCollapsed ? (
						<div className="flex min-w-0 items-center gap-2">
							<button
								aria-label="Account settings"
								className={cn(
									"flex min-w-0 flex-1 items-center gap-2.5 rounded-md p-2 text-left text-sidebar-foreground hover:bg-surface-hover focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sidebar-ring",
									view === "settings" &&
										settingsSection === "Account" &&
										"bg-surface-hover text-sidebar-foreground",
								)}
								onClick={() => openSettingsSection("Account")}
								title={user.email || undefined}
								type="button"
							>
								<span className="flex size-8 shrink-0 items-center justify-center rounded-full bg-primary text-sm font-semibold text-primary-foreground">
									{accountInitial}
								</span>
								<span className="flex min-w-0 flex-col leading-tight">
									<span className="truncate text-sm font-medium">
										{accountName}
									</span>
									{accountScope ? (
										<span className="truncate text-[11px] text-muted-foreground">
											{accountScope}
										</span>
									) : null}
								</span>
							</button>
							<Button
								aria-label="Settings"
								className={cn(
									"size-9 shrink-0 justify-center px-0",
									view === "settings" &&
										settingsSection !== "Account" &&
										"bg-surface-hover text-sidebar-foreground",
								)}
								onClick={openSettings}
								title="Settings"
								type="button"
								variant="sidebarItem"
							>
								<Settings className="size-4" />
							</Button>
						</div>
					) : (
						<Button
							aria-label="Settings"
							className={cn(
								"min-w-0 justify-start",
								isCollapsed && "size-9 justify-center px-0",
								view === "settings" &&
									"bg-surface-hover text-sidebar-foreground",
							)}
							onClick={openSettings}
							title="Settings"
							type="button"
							variant="sidebarItem"
						>
							<Settings className="size-4" />
							{!isCollapsed ? "Settings" : null}
						</Button>
					)}
				</div>
			</div>
			<AlertDialog
				open={deleteConfirmThread !== null}
				onOpenChange={(open) => {
					if (!open && pendingAction?.action !== "delete") {
						setDeleteConfirmThread(null);
					}
				}}
			>
				<AlertDialogContent>
					<AlertDialogHeader>
						<AlertDialogTitle>Delete session?</AlertDialogTitle>
						<AlertDialogDescription>
							This removes "
							{normalizeTitle(deleteConfirmThread?.title ?? "this session")}"
							from local history.
						</AlertDialogDescription>
					</AlertDialogHeader>
					<AlertDialogFooter>
						<AlertDialogCancel disabled={pendingAction?.action === "delete"}>
							Cancel
						</AlertDialogCancel>
						<AlertDialogAction
							className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
							disabled={
								!deleteConfirmThread || pendingAction?.action === "delete"
							}
							onClick={(event) => {
								event.preventDefault();
								if (deleteConfirmThread) {
									void deleteThread(deleteConfirmThread);
								}
							}}
						>
							{pendingAction?.action === "delete" ? (
								<>
									<Loader2 className="size-4 animate-spin" />
									Deleting...
								</>
							) : (
								"Delete"
							)}
						</AlertDialogAction>
					</AlertDialogFooter>
				</AlertDialogContent>
			</AlertDialog>
		</>
	);
}

function ProjectSection({
	label,
	collapsed,
	onToggle,
	children,
}: {
	label: string;
	collapsed: boolean;
	onToggle: () => void;
	children: ReactNode;
}) {
	return (
		<div className="mb-1 min-w-0">
			<button
				aria-expanded={!collapsed}
				className="flex h-8 w-full min-w-0 items-center gap-1.5 rounded-md px-1 text-left text-sm font-medium text-sidebar-foreground hover:bg-surface-hover-lighter focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sidebar-ring"
				onClick={onToggle}
				title={label}
				type="button"
			>
				<ChevronDown
					className={cn(
						"size-3.5 shrink-0 transition-transform",
						collapsed && "-rotate-90",
					)}
				/>
				<span className="block min-w-0 truncate">{label}</span>
			</button>
			{!collapsed ? <div className="pl-3">{children}</div> : null}
		</div>
	);
}

function ThreadItem({
	thread,
	editTitle,
	editing,
	isActive,
	onClick,
	onCancelRename,
	onCommitRename,
	onEditTitleChange,
	onRename,
	onToggleFavorite,
	onFork,
	onDelete,
	pendingAction,
	unread,
}: {
	thread: Thread;
	editTitle: string;
	editing: boolean;
	isActive: boolean;
	onClick: () => void;
	onCancelRename: () => void;
	onCommitRename: () => void;
	onEditTitleChange: (title: string) => void;
	onRename: () => void;
	onToggleFavorite: () => void;
	onFork: () => void;
	onDelete: () => void;
	pendingAction: "rename" | "fork" | "delete" | null;
	unread: boolean;
}) {
	const title = normalizeTitle(thread.title);
	const overviewTitle = getSessionOverviewTitle(title);
	const pending = pendingAction !== null;
	const statusDotClass = pending
		? "bg-yellow-400"
		: thread.status === "running"
			? "bg-green-500"
			: unread
				? "bg-blue-500"
				: "";
	const infoItems = getSessionOverviewItems(thread);

	if (editing) {
		return (
			<div
				className={cn(
					"grid h-8 w-full max-w-full min-w-0 grid-cols-[minmax(0,1fr)_auto] items-center gap-1 overflow-hidden rounded-md px-2",
					isActive
						? "bg-surface-hover text-sidebar-foreground"
						: "text-sidebar-foreground/80",
				)}
			>
				<EditableSessionTitle
					disabled={pendingAction === "rename"}
					onCancel={onCancelRename}
					onChange={onEditTitleChange}
					onCommit={onCommitRename}
					value={editTitle}
				/>
				{pendingAction === "rename" ? (
					<Loader2 className="size-3 shrink-0 animate-spin text-muted-foreground" />
				) : null}
			</div>
		);
	}

	return (
		<ContextMenu>
			<HoverCard openDelay={0} closeDelay={100}>
				<ContextMenuTrigger asChild>
					<HoverCardTrigger asChild>
						<button
							className={cn(
								"group grid h-8 w-full max-w-full min-w-0 grid-cols-[minmax(0,1fr)_auto] items-center gap-1 overflow-hidden rounded-md px-2 text-left text-sm font-normal",
								isActive
									? "bg-surface-hover text-sidebar-foreground"
									: "text-sidebar-foreground/80 hover:bg-surface-hover",
							)}
							disabled={pending}
							onClick={onClick}
							type="button"
						>
							<span className="block max-w-full min-w-0 overflow-hidden text-ellipsis whitespace-nowrap text-sm font-normal leading-tight">
								{title}
							</span>
							<span className="flex shrink-0 items-center gap-1.5 text-[11px] text-muted-foreground">
								{thread.pinned ? (
									<Star
										aria-label="Favorited"
										className="size-3 fill-current"
									/>
								) : statusDotClass ? (
									<span
										aria-hidden="true"
										className={cn("size-1.5 rounded-full", statusDotClass)}
									/>
								) : null}
								<span>{thread.time}</span>
							</span>
						</button>
					</HoverCardTrigger>
				</ContextMenuTrigger>
				<HoverCardContent
					align="start"
					avoidCollisions={false}
					className="w-72 p-3"
					side="right"
					sideOffset={8}
				>
					<div className="min-w-0 space-y-2">
						<div className="wrap-break-word text-sm font-medium">
							{overviewTitle}
						</div>
						<div className="grid grid-cols-[72px_minmax(0,1fr)] gap-x-2 gap-y-1.5 text-xs">
							{infoItems.map(([label, value, fullValue]) => (
								<div className="contents" key={label}>
									<span className="text-muted-foreground">{label}</span>
									<span
										className="min-w-0 truncate font-mono text-foreground"
										title={fullValue}
									>
										{value}
									</span>
								</div>
							))}
						</div>
					</div>
				</HoverCardContent>
			</HoverCard>
			<SessionContextMenuContent
				favorited={Boolean(thread.pinned)}
				onDelete={onDelete}
				onFork={onFork}
				onRename={onRename}
				onToggleFavorite={onToggleFavorite}
				pendingAction={pendingAction}
			/>
		</ContextMenu>
	);
}

export function getSessionOverviewTitle(title: string): string {
	const firstLine = title.split(/\r?\n/, 1)[0] ?? "";
	return normalizeTitle(firstLine);
}

export function getSessionOverviewItems(
	thread: SessionThread,
): Array<[string, string, string?]> {
	// Updated time is already visible in the sidebar item.
	const workspacePath = thread.workspacePath || thread.codebase;
	const items: Array<[string, string | null | undefined, string?]> = [
		[
			"Workspace",
			workspaceDisplayName(workspacePath),
			workspacePath || undefined,
		],
		["Branch", thread.gitBranch],
		["Provider", thread.provider],
		["Model", thread.model],
		["Tokens", formatTokenCount(thread.inputTokens, thread.outputTokens)],
		["Cost", formatCostUsd(thread.totalCostUsd)],
		["Source", thread.source],
	];
	return items.filter((item): item is [string, string, string?] =>
		Boolean(item[1]),
	);
}

function EditableSessionTitle({
	value,
	disabled,
	onChange,
	onCommit,
	onCancel,
}: {
	value: string;
	disabled: boolean;
	onChange: (value: string) => void;
	onCommit: () => void;
	onCancel: () => void;
}) {
	const inputRef = useRef<HTMLInputElement>(null);

	useEffect(() => {
		const input = inputRef.current;
		if (!input) {
			return;
		}
		input.focus();
		input.setSelectionRange(0, 0);
		input.scrollLeft = 0;
	}, []);

	return (
		<Input
			ref={inputRef}
			className="h-6 max-w-full min-w-0 bg-background px-1.5 py-0 text-sm"
			disabled={disabled}
			onBlur={() => {
				if (!disabled) {
					onCommit();
				}
			}}
			onChange={(event) => onChange(event.target.value)}
			onClick={(event) => event.stopPropagation()}
			onKeyDown={(event) => {
				if (event.key === "Enter") {
					event.preventDefault();
					onCommit();
				}
				if (event.key === "Escape") {
					event.preventDefault();
					onCancel();
				}
			}}
			value={value}
		/>
	);
}

function SessionContextMenuContent({
	favorited,
	onRename,
	onToggleFavorite,
	onFork,
	onDelete,
	pendingAction,
}: {
	favorited: boolean;
	onRename: () => void;
	onToggleFavorite: () => void;
	onFork: () => void;
	onDelete: () => void;
	pendingAction: "rename" | "fork" | "delete" | null;
}) {
	const pending = pendingAction !== null;
	return (
		<ContextMenuContent className="w-40">
			<ContextMenuItem disabled={pending} onSelect={onToggleFavorite}>
				<Star className={cn("size-4", favorited && "fill-current")} />
				{favorited ? "Unfavorite" : "Favorite"}
			</ContextMenuItem>
			<ContextMenuItem disabled={pending} onSelect={onRename}>
				{pendingAction === "rename" ? (
					<Loader2 className="size-4 animate-spin" />
				) : (
					<Pencil className="size-4" />
				)}
				{pendingAction === "rename" ? "Renaming..." : "Rename"}
			</ContextMenuItem>
			<ContextMenuItem disabled={pending} onSelect={onFork}>
				{pendingAction === "fork" ? (
					<Loader2 className="size-4 animate-spin" />
				) : (
					<GitFork className="size-4" />
				)}
				{pendingAction === "fork" ? "Forking..." : "Fork"}
			</ContextMenuItem>
			<ContextMenuItem
				disabled={pending}
				onSelect={onDelete}
				variant="destructive"
			>
				{pendingAction === "delete" ? (
					<Loader2 className="size-4 animate-spin" />
				) : (
					<Trash2 className="size-4" />
				)}
				{pendingAction === "delete" ? "Deleting..." : "Delete"}
			</ContextMenuItem>
		</ContextMenuContent>
	);
}

// @vitest-environment jsdom

import { act } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { SpeechInput } from "./speech-input";

class FakeMediaRecorder extends EventTarget {
	static instances: FakeMediaRecorder[] = [];
	static deferStopEvents = false;
	static stopError: unknown;
	static recordedAudio: Blob | null = new Blob(["recorded audio"], {
		type: "audio/webm",
	});

	readonly mimeType = "audio/webm";
	state: RecordingState = "inactive";
	private stopPending = false;

	constructor(readonly stream: MediaStream) {
		super();
		FakeMediaRecorder.instances.push(this);
	}

	start(): void {
		this.state = "recording";
	}

	stop(): void {
		if (FakeMediaRecorder.stopError) throw FakeMediaRecorder.stopError;
		this.state = "inactive";
		if (FakeMediaRecorder.deferStopEvents) {
			this.stopPending = true;
			return;
		}
		this.dispatchStopEvents();
	}

	flushStopEvents(): void {
		if (!this.stopPending) return;
		this.stopPending = false;
		this.dispatchStopEvents();
	}

	private dispatchStopEvents(): void {
		if (FakeMediaRecorder.recordedAudio) {
			const dataEvent = new Event("dataavailable");
			Object.defineProperty(dataEvent, "data", {
				value: FakeMediaRecorder.recordedAudio,
			});
			this.dispatchEvent(dataEvent);
		}
		this.dispatchEvent(new Event("stop"));
	}
}

class FakeSpeechRecognition extends EventTarget {
	static instances: FakeSpeechRecognition[] = [];

	continuous = false;
	interimResults = false;
	lang = "";

	constructor() {
		super();
		FakeSpeechRecognition.instances.push(this);
	}

	start(): void {
		this.dispatchEvent(new Event("start"));
	}

	stop(): void {
		this.dispatchEvent(new Event("end"));
	}

	emitFinal(transcript: string): void {
		const event = new Event("result");
		Object.defineProperties(event, {
			resultIndex: { value: 0 },
			results: {
				value: [
					{
						0: { confidence: 1, transcript },
						isFinal: true,
						length: 1,
					},
				],
			},
		});
		this.dispatchEvent(event);
	}
}

let container: HTMLDivElement;
let root: Root;
let stopTrack: ReturnType<typeof vi.fn>;

beforeEach(() => {
	Object.assign(globalThis, { IS_REACT_ACT_ENVIRONMENT: true });
	FakeMediaRecorder.instances = [];
	FakeMediaRecorder.deferStopEvents = false;
	FakeMediaRecorder.stopError = undefined;
	FakeMediaRecorder.recordedAudio = new Blob(["recorded audio"], {
		type: "audio/webm",
	});
	FakeSpeechRecognition.instances = [];
	stopTrack = vi.fn();
	Object.defineProperty(window, "MediaRecorder", {
		configurable: true,
		value: FakeMediaRecorder,
	});
	Object.defineProperty(window, "SpeechRecognition", {
		configurable: true,
		value: FakeSpeechRecognition,
	});
	Object.defineProperty(window, "AudioContext", {
		configurable: true,
		value: class {},
	});
	Object.defineProperty(navigator, "mediaDevices", {
		configurable: true,
		value: {
			getUserMedia: vi.fn(async () => ({
				getTracks: () => [{ stop: stopTrack }],
			})),
		},
	});
	container = document.createElement("div");
	document.body.appendChild(container);
	root = createRoot(container);
});

afterEach(async () => {
	await act(async () => root.unmount());
	container.remove();
	delete (
		window as typeof window & { MediaRecorder?: typeof FakeMediaRecorder }
	).MediaRecorder;
	delete (
		window as typeof window & {
			SpeechRecognition?: typeof FakeSpeechRecognition;
		}
	).SpeechRecognition;
	delete (window as typeof window & { AudioContext?: typeof AudioContext })
		.AudioContext;
	vi.restoreAllMocks();
});

describe("SpeechInput", () => {
	it("emits browser speech-recognition text before recording stops", async () => {
		const onAudioRecorded = vi.fn(async () => "batch transcript");
		const onTranscriptionChange = vi.fn();

		await act(async () => {
			root.render(
				<SpeechInput
					onAudioRecorded={onAudioRecorded}
					onTranscriptionChange={onTranscriptionChange}
					recordingMode="auto"
				/>,
			);
		});

		const button = container.querySelector<HTMLButtonElement>(
			'[aria-label="Record speech"]',
		);
		await act(async () => button?.click());
		expect(button?.getAttribute("aria-label")).toBe("Stop recording");

		await act(async () => {
			FakeSpeechRecognition.instances[0]?.emitFinal("live transcript");
		});

		expect(onTranscriptionChange).toHaveBeenCalledWith(
			"live transcript",
			"speech-recognition",
		);
		expect(onAudioRecorded).not.toHaveBeenCalled();
		expect(button?.getAttribute("aria-label")).toBe("Stop recording");
	});

	it("records audio and forwards the provider transcript", async () => {
		FakeMediaRecorder.deferStopEvents = true;
		let resolveTranscript: (transcript: string) => void = () => {};
		const transcript = new Promise<string>((resolve) => {
			resolveTranscript = resolve;
		});
		const onAudioRecorded = vi.fn(() => transcript);
		const onActiveChange = vi.fn();
		const onProcessingChange = vi.fn();
		const onTranscriptionChange = vi.fn();

		await act(async () => {
			root.render(
				<SpeechInput
					onActiveChange={onActiveChange}
					onAudioRecorded={onAudioRecorded}
					onProcessingChange={onProcessingChange}
					onTranscriptionChange={onTranscriptionChange}
					recordingMode="media-recorder"
				/>,
			);
		});

		const button = container.querySelector<HTMLButtonElement>(
			'[aria-label="Record speech"]',
		);
		expect(button?.disabled).toBe(false);
		expect(onActiveChange).toHaveBeenLastCalledWith(false);
		expect(button?.querySelector(".lucide-mic")).not.toBeNull();
		expect(button?.querySelector(".lucide-square")).toBeNull();

		await act(async () => {
			button?.click();
			await Promise.resolve();
		});
		expect(FakeMediaRecorder.instances).toHaveLength(1);
		expect(onActiveChange).toHaveBeenLastCalledWith(true);
		expect(button?.getAttribute("aria-label")).toBe("Stop recording");
		expect(button?.title).toBe("Stop recording");
		expect(
			button?.querySelector(".lucide-mic")?.getAttribute("class"),
		).toContain("animate-pulse");
		expect(
			button?.querySelector(".lucide-mic")?.getAttribute("class"),
		).toContain("group-hover:opacity-0");
		expect(
			button?.querySelector(".lucide-square")?.getAttribute("class"),
		).toContain("group-hover:opacity-100");

		await act(async () => {
			button?.click();
			await Promise.resolve();
		});

		// Stopping is asynchronous in browsers. The component must stay active
		// during the gap before MediaRecorder dispatches its stop event.
		expect(onAudioRecorded).not.toHaveBeenCalled();
		expect(onProcessingChange).toHaveBeenLastCalledWith(true);
		expect(onActiveChange).toHaveBeenLastCalledWith(true);
		expect(button?.disabled).toBe(true);

		await act(async () => {
			FakeMediaRecorder.instances[0]?.flushStopEvents();
			await Promise.resolve();
		});

		expect(onAudioRecorded).toHaveBeenCalledWith(
			expect.objectContaining({ type: "audio/webm" }),
		);
		expect(onProcessingChange).toHaveBeenCalledWith(true);
		expect(onActiveChange).toHaveBeenLastCalledWith(true);
		expect(button?.disabled).toBe(true);

		await act(async () => {
			resolveTranscript("transcribed prompt");
			await transcript;
		});

		expect(onTranscriptionChange).toHaveBeenCalledWith(
			"transcribed prompt",
			"media-recorder",
		);
		expect(onProcessingChange).toHaveBeenLastCalledWith(false);
		expect(onActiveChange).toHaveBeenLastCalledWith(false);
		expect(stopTrack).toHaveBeenCalledOnce();
	});

	it("starts and stops a streaming transcription session", async () => {
		let resolveDone: () => void = () => {};
		const done = new Promise<void>((resolve) => {
			resolveDone = resolve;
		});
		const stop = vi.fn(resolveDone);
		const cancel = vi.fn(resolveDone);
		const onStartStreaming = vi.fn(async () => ({ done, stop, cancel }));
		const onStreamingStart = vi.fn();
		const onStreamingEnd = vi.fn();

		await act(async () => {
			root.render(
				<SpeechInput
					onStartStreaming={onStartStreaming}
					onStreamingEnd={onStreamingEnd}
					onStreamingStart={onStreamingStart}
					recordingMode="streaming"
				/>,
			);
		});

		const button = container.querySelector<HTMLButtonElement>(
			'[aria-label="Record speech"]',
		);
		await act(async () => {
			button?.click();
			await Promise.resolve();
		});
		expect(onStreamingStart).toHaveBeenCalledOnce();
		expect(onStartStreaming).toHaveBeenCalledOnce();
		expect(button?.getAttribute("aria-label")).toBe("Stop recording");

		await act(async () => {
			button?.click();
			await done;
		});
		expect(stop).toHaveBeenCalledOnce();
		expect(onStreamingEnd).toHaveBeenCalledOnce();
		expect(button?.getAttribute("aria-label")).toBe("Record speech");
	});

	it("returns to inactive when MediaRecorder rejects stop", async () => {
		const stopError = new DOMException("Already stopped", "InvalidStateError");
		const onActiveChange = vi.fn();
		const onError = vi.fn();

		await act(async () => {
			root.render(
				<SpeechInput
					onActiveChange={onActiveChange}
					onAudioRecorded={vi.fn(async () => "unused")}
					onError={onError}
					recordingMode="media-recorder"
				/>,
			);
		});
		const button = container.querySelector<HTMLButtonElement>(
			'[aria-label="Record speech"]',
		);
		await act(async () => {
			button?.click();
			await Promise.resolve();
		});
		FakeMediaRecorder.stopError = stopError;

		await act(async () => button?.click());

		expect(onError).toHaveBeenCalledWith(stopError);
		expect(onActiveChange).toHaveBeenLastCalledWith(false);
		expect(stopTrack).toHaveBeenCalledOnce();
		expect(button?.disabled).toBe(false);
		expect(button?.getAttribute("aria-label")).toBe("Record speech");
	});

	it("ignores a pending batch transcript after unmount", async () => {
		let resolveTranscript: (transcript: string) => void = () => {};
		const pendingTranscript = new Promise<string>((resolve) => {
			resolveTranscript = resolve;
		});
		const onTranscriptionChange = vi.fn();
		const onError = vi.fn();

		await act(async () => {
			root.render(
				<SpeechInput
					onAudioRecorded={() => pendingTranscript}
					onError={onError}
					onTranscriptionChange={onTranscriptionChange}
					recordingMode="media-recorder"
				/>,
			);
		});
		const button = container.querySelector<HTMLButtonElement>(
			'[aria-label="Record speech"]',
		);
		await act(async () => {
			button?.click();
			await Promise.resolve();
		});
		await act(async () => {
			button?.click();
			await Promise.resolve();
		});
		await act(async () => root.render(<div />));
		await act(async () => {
			resolveTranscript("stale transcript");
			await pendingTranscript;
		});

		expect(onTranscriptionChange).not.toHaveBeenCalled();
		expect(onError).not.toHaveBeenCalled();
	});

	it("returns to an inactive state when the recorder produces no audio", async () => {
		FakeMediaRecorder.recordedAudio = null;
		const onActiveChange = vi.fn();
		const onAudioRecorded = vi.fn(async () => "should not run");
		const onProcessingChange = vi.fn();

		await act(async () => {
			root.render(
				<SpeechInput
					onActiveChange={onActiveChange}
					onAudioRecorded={onAudioRecorded}
					onProcessingChange={onProcessingChange}
					recordingMode="media-recorder"
				/>,
			);
		});
		const button = container.querySelector<HTMLButtonElement>(
			'[aria-label="Record speech"]',
		);
		await act(async () => {
			button?.click();
			await Promise.resolve();
		});
		await act(async () => {
			button?.click();
			await Promise.resolve();
		});

		expect(onAudioRecorded).not.toHaveBeenCalled();
		expect(onActiveChange).toHaveBeenLastCalledWith(false);
		expect(onProcessingChange).toHaveBeenLastCalledWith(false);
		expect(button?.disabled).toBe(false);
		expect(button?.getAttribute("aria-label")).toBe("Record speech");
	});

	it("cancels a streaming session that arrives after the component unmounts", async () => {
		let resolveSession: (session: {
			done: Promise<void>;
			stop: () => void;
			cancel: () => void;
		}) => void = () => {};
		const pendingSession = new Promise<{
			done: Promise<void>;
			stop: () => void;
			cancel: () => void;
		}>((resolve) => {
			resolveSession = resolve;
		});
		const cancel = vi.fn();
		const onStreamingEnd = vi.fn();
		const onError = vi.fn();

		await act(async () => {
			root.render(
				<SpeechInput
					onError={onError}
					onStartStreaming={() => pendingSession}
					onStreamingEnd={onStreamingEnd}
					recordingMode="streaming"
				/>,
			);
		});

		const button = container.querySelector<HTMLButtonElement>(
			'[aria-label="Record speech"]',
		);
		await act(async () => {
			button?.click();
			await Promise.resolve();
		});
		await act(async () => root.render(<div />));
		await act(async () => {
			resolveSession({
				done: new Promise<void>(() => {}),
				stop: vi.fn(),
				cancel,
			});
			await pendingSession;
		});

		expect(cancel).toHaveBeenCalledOnce();
		expect(onStreamingEnd).not.toHaveBeenCalled();
		expect(onError).not.toHaveBeenCalled();
	});
});

"use client";

import { MicIcon, SquareIcon } from "lucide-react";
import type { ComponentProps } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";
import { cn } from "@/lib/utils";
import type { StreamingSpeechSession } from "@/lib/vercel-streaming-transcription";

interface SpeechRecognition extends EventTarget {
	continuous: boolean;
	interimResults: boolean;
	lang: string;
	start(): void;
	stop(): void;
}

interface SpeechRecognitionEvent extends Event {
	results: SpeechRecognitionResultList;
	resultIndex: number;
}

interface SpeechRecognitionResultList {
	readonly length: number;
	[index: number]: SpeechRecognitionResult;
}

interface SpeechRecognitionResult {
	readonly length: number;
	[index: number]: SpeechRecognitionAlternative;
	isFinal: boolean;
}

interface SpeechRecognitionAlternative {
	transcript: string;
	confidence: number;
}

declare global {
	interface Window {
		SpeechRecognition: new () => SpeechRecognition;
		webkitSpeechRecognition: new () => SpeechRecognition;
	}
}

export type SpeechInputMode =
	| "speech-recognition"
	| "media-recorder"
	| "streaming"
	| "none";

export type SpeechTranscriptionSource = Extract<
	SpeechInputMode,
	"speech-recognition" | "media-recorder"
>;

export type SpeechInputProps = Omit<
	ComponentProps<typeof Button>,
	"onError"
> & {
	allowUnavailableClick?: boolean;
	onTranscriptionChange?: (
		text: string,
		source: SpeechTranscriptionSource,
	) => void;
	onAudioRecorded?: (audioBlob: Blob) => Promise<string>;
	onStartStreaming?: () => Promise<StreamingSpeechSession>;
	onStreamingStart?: () => void;
	onStreamingEnd?: () => void;
	onActiveChange?: (active: boolean) => void;
	onProcessingChange?: (processing: boolean) => void;
	onError?: (error: unknown) => void;
	lang?: string;
	recordingMode?: "auto" | "media-recorder" | "streaming";
};

function detectSpeechInputMode(
	recordingMode: NonNullable<SpeechInputProps["recordingMode"]>,
): SpeechInputMode {
	if (typeof window === "undefined") return "none";
	if (recordingMode === "streaming") {
		return typeof navigator !== "undefined" &&
			"WebSocket" in window &&
			"AudioContext" in window &&
			"mediaDevices" in navigator
			? "streaming"
			: "none";
	}
	if (recordingMode === "media-recorder") {
		return typeof navigator !== "undefined" &&
			"MediaRecorder" in window &&
			"mediaDevices" in navigator
			? "media-recorder"
			: "none";
	}
	if ("SpeechRecognition" in window || "webkitSpeechRecognition" in window) {
		return "speech-recognition";
	}
	if (
		typeof navigator !== "undefined" &&
		"MediaRecorder" in window &&
		"mediaDevices" in navigator
	) {
		return "media-recorder";
	}
	return "none";
}

export function SpeechInput({
	allowUnavailableClick = false,
	className,
	disabled,
	lang = "en-US",
	onAudioRecorded,
	onActiveChange,
	onClick,
	onError,
	onProcessingChange,
	onStartStreaming,
	onStreamingEnd,
	onStreamingStart,
	onTranscriptionChange,
	recordingMode = "auto",
	title,
	...props
}: SpeechInputProps) {
	const [mode] = useState<SpeechInputMode>(() =>
		detectSpeechInputMode(recordingMode),
	);
	const [isListening, setIsListening] = useState(false);
	const [isProcessing, setIsProcessing] = useState(false);
	const [isRecognitionReady, setIsRecognitionReady] = useState(false);
	const recognitionRef = useRef<SpeechRecognition | null>(null);
	const mediaRecorderRef = useRef<MediaRecorder | null>(null);
	const streamingSessionRef = useRef<StreamingSpeechSession | null>(null);
	const streamRef = useRef<MediaStream | null>(null);
	const audioChunksRef = useRef<Blob[]>([]);
	const mountedRef = useRef(true);
	const operationIdRef = useRef(0);
	const onAudioRecordedRef = useRef(onAudioRecorded);
	const onErrorRef = useRef(onError);
	const onStartStreamingRef = useRef(onStartStreaming);
	const onStreamingEndRef = useRef(onStreamingEnd);
	const onStreamingStartRef = useRef(onStreamingStart);
	const onTranscriptionChangeRef = useRef(onTranscriptionChange);

	onAudioRecordedRef.current = onAudioRecorded;
	onErrorRef.current = onError;
	onStartStreamingRef.current = onStartStreaming;
	onStreamingEndRef.current = onStreamingEnd;
	onStreamingStartRef.current = onStreamingStart;
	onTranscriptionChangeRef.current = onTranscriptionChange;

	useEffect(() => {
		onActiveChange?.(isListening || isProcessing);
	}, [isListening, isProcessing, onActiveChange]);

	useEffect(() => {
		onProcessingChange?.(isProcessing);
	}, [isProcessing, onProcessingChange]);

	useEffect(() => {
		if (mode !== "speech-recognition") return;

		const Recognition =
			window.SpeechRecognition || window.webkitSpeechRecognition;
		const recognition = new Recognition();
		recognition.continuous = true;
		recognition.interimResults = true;
		recognition.lang = lang;

		const handleStart = () => setIsListening(true);
		const handleEnd = () => setIsListening(false);
		const handleResult = (event: Event) => {
			const speechEvent = event as SpeechRecognitionEvent;
			let transcript = "";
			for (
				let index = speechEvent.resultIndex;
				index < speechEvent.results.length;
				index += 1
			) {
				const result = speechEvent.results[index];
				if (result?.isFinal) {
					transcript += result[0]?.transcript ?? "";
				}
			}
			if (transcript.trim()) {
				onTranscriptionChangeRef.current?.(transcript, "speech-recognition");
			}
		};
		const handleError = (event: Event) => {
			setIsListening(false);
			onErrorRef.current?.(event);
		};

		recognition.addEventListener("start", handleStart);
		recognition.addEventListener("end", handleEnd);
		recognition.addEventListener("result", handleResult);
		recognition.addEventListener("error", handleError);
		recognitionRef.current = recognition;
		setIsRecognitionReady(true);

		return () => {
			recognition.removeEventListener("start", handleStart);
			recognition.removeEventListener("end", handleEnd);
			recognition.removeEventListener("result", handleResult);
			recognition.removeEventListener("error", handleError);
			recognition.stop();
			recognitionRef.current = null;
			setIsRecognitionReady(false);
		};
	}, [lang, mode]);

	useEffect(() => {
		mountedRef.current = true;
		return () => {
			mountedRef.current = false;
			operationIdRef.current += 1;
			streamingSessionRef.current?.cancel();
			streamingSessionRef.current = null;
			if (mediaRecorderRef.current?.state === "recording") {
				mediaRecorderRef.current.stop();
			}
			for (const track of streamRef.current?.getTracks() ?? []) {
				track.stop();
			}
		};
	}, []);

	const startStreaming = useCallback(async () => {
		if (!onStartStreamingRef.current) return;
		const operationId = ++operationIdRef.current;
		setIsProcessing(true);
		try {
			onStreamingStartRef.current?.();
			const session = await onStartStreamingRef.current();
			if (!mountedRef.current || operationId !== operationIdRef.current) {
				session.cancel();
				return;
			}
			streamingSessionRef.current = session;
			setIsListening(true);
			setIsProcessing(false);
			void session.done.then(
				() => {
					if (!mountedRef.current || streamingSessionRef.current !== session) {
						return;
					}
					streamingSessionRef.current = null;
					setIsListening(false);
					setIsProcessing(false);
					onStreamingEndRef.current?.();
				},
				(error) => {
					if (!mountedRef.current || streamingSessionRef.current !== session) {
						return;
					}
					streamingSessionRef.current = null;
					setIsListening(false);
					setIsProcessing(false);
					onStreamingEndRef.current?.();
					onErrorRef.current?.(error);
				},
			);
		} catch (error) {
			if (!mountedRef.current || operationId !== operationIdRef.current) {
				return;
			}
			setIsListening(false);
			setIsProcessing(false);
			onStreamingEndRef.current?.();
			onErrorRef.current?.(error);
		}
	}, []);

	const startMediaRecorder = useCallback(async () => {
		if (!onAudioRecordedRef.current) return;
		const operationId = ++operationIdRef.current;
		setIsProcessing(true);
		try {
			const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
			if (!mountedRef.current || operationId !== operationIdRef.current) {
				for (const track of stream.getTracks()) track.stop();
				return;
			}
			const recorder = new MediaRecorder(stream);
			streamRef.current = stream;
			mediaRecorderRef.current = recorder;
			audioChunksRef.current = [];

			recorder.addEventListener("dataavailable", (event) => {
				if (event.data.size > 0) audioChunksRef.current.push(event.data);
			});
			recorder.addEventListener("error", (event) => {
				if (!mountedRef.current || operationId !== operationIdRef.current) {
					return;
				}
				setIsListening(false);
				setIsProcessing(false);
				operationIdRef.current += 1;
				for (const track of stream.getTracks()) track.stop();
				streamRef.current = null;
				mediaRecorderRef.current = null;
				onErrorRef.current?.(event);
			});
			recorder.addEventListener("stop", async () => {
				for (const track of stream.getTracks()) track.stop();
				streamRef.current = null;
				mediaRecorderRef.current = null;
				if (!mountedRef.current || operationId !== operationIdRef.current) {
					return;
				}
				setIsListening(false);
				const audioBlob = new Blob(audioChunksRef.current, {
					type: recorder.mimeType || "audio/webm",
				});
				audioChunksRef.current = [];
				if (audioBlob.size === 0 || !onAudioRecordedRef.current) {
					setIsProcessing(false);
					return;
				}

				setIsProcessing(true);
				try {
					const transcript = await onAudioRecordedRef.current(audioBlob);
					if (!mountedRef.current || operationId !== operationIdRef.current) {
						return;
					}
					if (transcript.trim()) {
						onTranscriptionChangeRef.current?.(transcript, "media-recorder");
					}
				} catch (error) {
					if (mountedRef.current && operationId === operationIdRef.current) {
						onErrorRef.current?.(error);
					}
				} finally {
					if (mountedRef.current && operationId === operationIdRef.current) {
						setIsProcessing(false);
					}
				}
			});

			recorder.start();
			setIsListening(true);
			setIsProcessing(false);
		} catch (error) {
			if (!mountedRef.current || operationId !== operationIdRef.current) {
				return;
			}
			setIsListening(false);
			setIsProcessing(false);
			onErrorRef.current?.(error);
		}
	}, []);

	const toggleListening = useCallback(() => {
		if (mode === "speech-recognition" && recognitionRef.current) {
			if (isListening) recognitionRef.current.stop();
			else recognitionRef.current.start();
			return;
		}
		if (mode === "media-recorder") {
			if (isListening) {
				const recorder = mediaRecorderRef.current;
				if (!recorder) return;
				// Keep the recording operation active while MediaRecorder schedules its
				// stop event and the completed audio is transcribed. Without this state
				// transition, consumers briefly observe an inactive session and may
				// discard the draft range needed by the asynchronous result.
				setIsProcessing(true);
				try {
					recorder.stop();
				} catch (error) {
					operationIdRef.current += 1;
					for (const track of streamRef.current?.getTracks() ?? [])
						track.stop();
					streamRef.current = null;
					mediaRecorderRef.current = null;
					setIsListening(false);
					setIsProcessing(false);
					onErrorRef.current?.(error);
				}
			} else {
				void startMediaRecorder();
			}
			return;
		}
		if (mode === "streaming") {
			if (isListening) {
				setIsListening(false);
				setIsProcessing(true);
				streamingSessionRef.current?.stop();
			} else {
				void startStreaming();
			}
		}
	}, [isListening, mode, startMediaRecorder, startStreaming]);

	const unavailable =
		mode === "none" ||
		(mode === "speech-recognition" && !isRecognitionReady) ||
		(mode === "media-recorder" && !onAudioRecorded) ||
		(mode === "streaming" && !onStartStreaming);

	return (
		<div className="relative inline-flex items-center justify-center">
			{isListening ? (
				<div className="absolute inset-0 animate-ping rounded-full border-2 border-destructive/40" />
			) : null}
			<Button
				{...props}
				aria-label={isListening ? "Stop recording" : "Record speech"}
				aria-pressed={isListening}
				className={cn(
					"group relative z-10 size-7 rounded-md p-1.5 transition-colors",
					isListening
						? "bg-destructive text-white hover:bg-destructive/80"
						: "bg-transparent text-muted-foreground hover:bg-accent hover:text-foreground",
					className,
				)}
				disabled={
					disabled || (unavailable && !allowUnavailableClick) || isProcessing
				}
				onClick={(event) => {
					onClick?.(event);
					if (!event.defaultPrevented) toggleListening();
				}}
				title={
					isListening
						? "Stop recording"
						: (title ??
							(unavailable
								? "Speech input is not supported in this browser"
								: "Record speech"))
				}
				type="button"
			>
				{isProcessing ? (
					<Spinner className="size-4" />
				) : isListening ? (
					<span className="relative size-4">
						<MicIcon className="absolute inset-0 size-4 animate-pulse transition-opacity group-hover:opacity-0 group-focus-visible:opacity-0" />
						<SquareIcon className="absolute inset-0 m-auto size-3.5 opacity-0 transition-opacity group-hover:opacity-100 group-focus-visible:opacity-100" />
					</span>
				) : (
					<MicIcon className="size-4" />
				)}
			</Button>
		</div>
	);
}

"use client";

import { CircleArrowUp, Loader2 } from "lucide-react";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import {
	restartToApplyUpdate,
	useAppUpdateStatus,
} from "@/hooks/use-app-update";
import { cn } from "@/lib/utils";

/**
 * Persistent "update ready" indicator for the sidebar. Renders nothing until
 * the auto-updater has staged an update, then shows an accented button that
 * opens a popover with the new version and a restart action — so the update
 * stays reachable after the one-time toast is dismissed.
 */
export function AppUpdateIndicator({ className }: { className?: string }) {
	const status = useAppUpdateStatus();
	const [restarting, setRestarting] = useState(false);

	if (status.state !== "ready" || !status.version) {
		return null;
	}

	return (
		<Popover>
			<PopoverTrigger asChild>
				<Button
					aria-label={`Update ready: v${status.version}`}
					className={cn(
						"relative size-8 shrink-0 justify-center px-0 text-blue-500 hover:text-blue-400",
						className,
					)}
					title={`Update ready: v${status.version}`}
					type="button"
					variant="sidebarItem"
				>
					<CircleArrowUp className="size-4" />
				</Button>
			</PopoverTrigger>
			<PopoverContent align="start" className="w-64 p-3" side="bottom">
				<p className="text-sm font-medium">Update ready: v{status.version}</p>
				<p className="mt-1 text-xs text-muted-foreground">
					The new version has been downloaded and will be used the next time the
					app starts. Restart now to switch to it right away.
				</p>
				<Button
					className="mt-3 w-full"
					disabled={restarting}
					onClick={() => {
						setRestarting(true);
						void restartToApplyUpdate().then((ok) => {
							if (!ok) {
								setRestarting(false);
							}
						});
					}}
					size="sm"
					type="button"
				>
					{restarting ? (
						<>
							<Loader2 className="size-4 animate-spin" />
							Restarting...
						</>
					) : (
						"Restart now"
					)}
				</Button>
			</PopoverContent>
		</Popover>
	);
}

