// @vitest-environment jsdom

import { act } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";
import { MarkdownLinkSafetyModal, MemoizedMarkdown } from "./markdown";

const originalClipboard = Object.getOwnPropertyDescriptor(
	navigator,
	"clipboard",
);

let writeText: ReturnType<typeof vi.fn>;
let openWindow: ReturnType<typeof vi.fn<typeof window.open>>;
let container: HTMLDivElement;
let root: Root;

beforeEach(() => {
	Object.assign(globalThis, { IS_REACT_ACT_ENVIRONMENT: true });
	container = document.createElement("div");
	document.body.appendChild(container);
	root = createRoot(container);
	writeText = vi.fn().mockResolvedValue(undefined);
	Object.defineProperty(navigator, "clipboard", {
		configurable: true,
		value: { writeText },
	});
	openWindow = vi.fn<typeof window.open>(() => null);
	vi.spyOn(window, "open").mockImplementation(openWindow);
});

afterEach(async () => {
	await act(async () => root.unmount());
	container.remove();
	vi.restoreAllMocks();
	if (originalClipboard) {
		Object.defineProperty(navigator, "clipboard", originalClipboard);
	} else {
		Reflect.deleteProperty(navigator, "clipboard");
	}
});

async function renderMarkdown(
	props: Parameters<typeof MemoizedMarkdown>[0],
): Promise<void> {
	await act(async () => root.render(<MemoizedMarkdown {...props} />));
}

async function click(element: Element): Promise<void> {
	await act(async () => {
		element.dispatchEvent(
			new MouseEvent("click", { bubbles: true, cancelable: true }),
		);
		await new Promise((resolve) => setTimeout(resolve, 0));
	});
}

async function dispatchMouseEvent(
	element: Element,
	type: "auxclick" | "contextmenu",
	button: number,
): Promise<void> {
	await act(async () => {
		element.dispatchEvent(
			new MouseEvent(type, { bubbles: true, button, cancelable: true }),
		);
		await new Promise((resolve) => setTimeout(resolve, 0));
	});
}

function getButton(label: string): HTMLButtonElement {
	const button = [
		...document.querySelectorAll<HTMLButtonElement>("button"),
	].find((candidate) => candidate.textContent?.trim() === label);
	expect(button).toBeDefined();
	return button as HTMLButtonElement;
}

describe("MemoizedMarkdown interactions", () => {
	test("confirms and closes an external link dialog exactly once", async () => {
		const onClose = vi.fn();
		const onConfirm = vi.fn();
		await act(async () => {
			root.render(
				<MarkdownLinkSafetyModal
					isOpen
					onClose={onClose}
					onConfirm={onConfirm}
					url="https://example.com/review"
				/>,
			);
		});

		await click(getButton("Open link"));
		await vi.waitFor(() => {
			expect(onConfirm).toHaveBeenCalledOnce();
			expect(onClose).toHaveBeenCalledOnce();
		});
	});

	test("opens honest external links directly in the default browser", async () => {
		const url = "https://example.com/review?source=cline";
		await renderMarkdown({ content: `[Review docs](${url})` });
		const link = await vi.waitFor(() => {
			const renderedLink = container.querySelector<HTMLAnchorElement>(
				'[data-streamdown="link"]',
			);
			expect(renderedLink).not.toBeNull();
			return renderedLink as HTMLAnchorElement;
		});
		expect(link.getAttribute("href")).toBe(url);
		expect(link.getAttribute("title")).toBe(url);

		await click(link);
		expect(document.querySelector('[role="alertdialog"]')).toBeNull();
		expect(openWindow).toHaveBeenCalledTimes(1);
		expect(openWindow).toHaveBeenCalledWith(
			url,
			"_blank",
			"noopener,noreferrer",
		);
	});

	test("requires confirmation before opening a deceptive external link", async () => {
		const url = "https://example.com/review?source=cline";
		await renderMarkdown({ content: `[github.com/cline](${url})` });
		const link = await vi.waitFor(() => {
			const renderedLink = container.querySelector<HTMLElement>(
				'[data-streamdown="link"]',
			);
			expect(renderedLink).not.toBeNull();
			return renderedLink as HTMLElement;
		});
		expect(link.tagName).toBe("A");
		expect(link.getAttribute("href")).toBe("#confirm-external-link");

		await dispatchMouseEvent(link, "contextmenu", 2);
		expect(openWindow).not.toHaveBeenCalled();
		expect(document.querySelector('[role="alertdialog"]')).toBeNull();

		await dispatchMouseEvent(link, "auxclick", 1);
		await vi.waitFor(() => {
			expect(document.querySelector('[role="alertdialog"]')).not.toBeNull();
		});
		await click(getButton("Cancel"));

		await click(link);
		await vi.waitFor(() => {
			expect(document.querySelector('[role="alertdialog"]')).not.toBeNull();
			expect(document.body.textContent).toContain(url);
		});

		await click(getButton("Cancel"));
		await vi.waitFor(() => {
			expect(document.querySelector('[role="alertdialog"]')).toBeNull();
		});
		expect(openWindow).not.toHaveBeenCalled();

		await click(link);
		await vi.waitFor(() => {
			expect(document.querySelector('[role="alertdialog"]')).not.toBeNull();
		});
		await click(getButton("Open link"));

		expect(openWindow).toHaveBeenCalledTimes(1);
		expect(openWindow).toHaveBeenCalledWith(
			url,
			"_blank",
			"noopener,noreferrer",
		);
		await vi.waitFor(() => {
			expect(document.querySelector('[role="alertdialog"]')).toBeNull();
		});
	});

	// The open_external_url sidecar command only opens http(s)/mailto/tel, and
	// relies on Streamdown's harden step blocking every other scheme before it
	// reaches SafeMarkdownLink. If a Streamdown upgrade starts letting other
	// schemes through, confirming those links would silently open nothing.
	test("blocks link schemes the sidecar cannot open before they render", async () => {
		for (const url of ["vscode://settings/editor", "ftp://example.com/f"]) {
			await renderMarkdown({ content: `[Open app](${url})` });
			await vi.waitFor(() => {
				expect(container.textContent).toContain("Open app");
			});
			expect(container.querySelector('[data-streamdown="link"]')).toBeNull();
		}
	});

	test("opens mailto links directly through the external opener", async () => {
		await renderMarkdown({ content: "[Email us](mailto:hi@cline.bot)" });
		const link = await vi.waitFor(() => {
			const renderedLink = container.querySelector<HTMLElement>(
				'[data-streamdown="link"]',
			);
			expect(renderedLink).not.toBeNull();
			return renderedLink as HTMLElement;
		});

		expect(link.tagName).toBe("A");
		await click(link);
		expect(document.querySelector('[role="alertdialog"]')).toBeNull();
		expect(openWindow).toHaveBeenCalledWith(
			"mailto:hi@cline.bot",
			"_blank",
			"noopener,noreferrer",
		);
	});

	test("keeps same-document links navigable without a confirmation", async () => {
		await renderMarkdown({ content: "[Details](#details)" });
		const link = container.querySelector<HTMLAnchorElement>(
			'[data-streamdown="link"]',
		);

		expect(link?.getAttribute("href")).toBe("#details");
		await click(link as HTMLAnchorElement);
		expect(document.querySelector('[role="alertdialog"]')).toBeNull();
		expect(openWindow).not.toHaveBeenCalled();
	});

	test("copies fenced code through the Clipboard API", async () => {
		const source = "const answer = 42;";
		await renderMarkdown({
			content: `\`\`\`text\n${source}\n\`\`\``,
		});
		const copyButton = await vi.waitFor(() => {
			const button = container.querySelector<HTMLButtonElement>(
				'[data-streamdown="code-block-copy-button"]',
			);
			expect(button).not.toBeNull();
			return button as HTMLButtonElement;
		});

		await click(copyButton);
		await vi.waitFor(() => {
			expect(writeText).toHaveBeenCalledWith(`${source}\n`);
		});
	});

	test("rerenders incomplete streaming Markdown as completed static Markdown", async () => {
		await renderMarkdown({
			content: "```text\nconst answer =",
			streaming: true,
		});

		await vi.waitFor(() => {
			const codeBlock = container.querySelector(
				'[data-streamdown="code-block"]',
			);
			expect(codeBlock?.getAttribute("data-incomplete")).toBe("true");
		});

		await renderMarkdown({
			content: "```text\nconst answer = 42;\n```\n\nCompleted.",
			streaming: false,
		});

		await vi.waitFor(() => {
			const codeBlock = container.querySelector(
				'[data-streamdown="code-block"]',
			);
			expect(codeBlock).not.toBeNull();
			expect(codeBlock?.getAttribute("data-incomplete")).toBeNull();
			expect(container.textContent).toContain("const answer = 42;");
			expect(container.textContent).toContain("Completed.");
		});
	});
});

import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, test } from "vitest";
import { MemoizedMarkdown } from "./markdown";

describe("MemoizedMarkdown", () => {
	test("renders structured GFM content and blocks remote images", () => {
		const html = renderToStaticMarkup(
			<MemoizedMarkdown
				content={`# Review

| Surface | Status |
| --- | --- |
| Code | Ready |

\`\`\`typescript
const ready = true;
\`\`\`

![remote image](https://example.com/tracker.png)`}
			/>,
		);

		expect(html).toContain('data-streamdown="heading-1"');
		expect(html).toContain('data-streamdown="table-wrapper"');
		expect(html).toContain('data-streamdown="code-block"');
		expect(html).toContain('data-streamdown="blocked-image"');
		expect(html).toContain("External image blocked for privacy");
		expect(html).not.toContain("<img");
	});

	test("renders app-local images", () => {
		const html = renderToStaticMarkup(
			<MemoizedMarkdown
				content={`![local](/images/local.png)

![second local](/images/second-local.png)`}
			/>,
		);

		expect(html.match(/<img/g)).toHaveLength(2);
		expect(html).toContain('src="/images/local.png"');
		expect(html).toContain('src="/images/second-local.png"');
		expect(html).not.toContain('data-streamdown="blocked-image"');
	});

	test("repairs an unfinished code fence while streaming", () => {
		const html = renderToStaticMarkup(
			<MemoizedMarkdown
				content={"```typescript\nconst stillStreaming = true;"}
				streaming
			/>,
		);

		expect(html).toContain('data-streamdown="code-block"');
		expect(html).toContain("stillStreaming");
	});

	test("renders honest external links with their real destination", () => {
		const html = renderToStaticMarkup(
			<MemoizedMarkdown content="[Review](https://example.com/review)" />,
		);

		expect(html).toContain('data-streamdown="link"');
		expect(html).toContain("Review");
		expect(html).toContain('href="https://example.com/review"');
		expect(html).not.toContain('aria-haspopup="dialog"');
	});

	test("keeps external links whose URL text matches the destination direct", () => {
		const html = renderToStaticMarkup(
			<MemoizedMarkdown content="[example.com/review](https://www.example.com/review)" />,
		);

		expect(html).toContain('href="https://www.example.com/review"');
		expect(html).not.toContain('aria-haspopup="dialog"');
	});

	test("routes deceptive URL-text links through confirmation controls", () => {
		const html = renderToStaticMarkup(
			<MemoizedMarkdown content="[github.com/cline](https://evil.example/payload)" />,
		);

		expect(html).toContain('data-streamdown="link"');
		expect(html).toContain('href="#confirm-external-link"');
		expect(html).toContain('aria-haspopup="dialog"');
		expect(html).not.toContain('href="https://evil.example/payload"');
	});

	test("treats fully qualified trailing-dot hostnames like their plain form", () => {
		const deceptiveHtml = renderToStaticMarkup(
			<MemoizedMarkdown content="[github.com.](https://evil.example/payload)" />,
		);
		expect(deceptiveHtml).toContain('href="#confirm-external-link"');
		expect(deceptiveHtml).not.toContain('href="https://evil.example/payload"');

		const honestHtml = renderToStaticMarkup(
			<MemoizedMarkdown content="[github.com.](https://github.com/cline)" />,
		);
		expect(honestHtml).toContain('href="https://github.com/cline"');
		expect(honestHtml).not.toContain('aria-haspopup="dialog"');
	});

	test("treats protocol-relative labels like their https form", () => {
		const deceptiveHtml = renderToStaticMarkup(
			<MemoizedMarkdown content="[//github.com](https://evil.example/payload)" />,
		);
		expect(deceptiveHtml).toContain('href="#confirm-external-link"');
		expect(deceptiveHtml).not.toContain('href="https://evil.example/payload"');

		const honestHtml = renderToStaticMarkup(
			<MemoizedMarkdown content="[//github.com](https://github.com/cline)" />,
		);
		expect(honestHtml).toContain('href="https://github.com/cline"');
		expect(honestHtml).not.toContain('aria-haspopup="dialog"');
	});

	test("sees through inline formatting inside deceptive URL text", () => {
		const html = renderToStaticMarkup(
			<MemoizedMarkdown content="[**github.com**/cline](https://evil.example/payload)" />,
		);

		expect(html).toContain('href="#confirm-external-link"');
		expect(html).not.toContain('href="https://evil.example/payload"');
	});

	test("treats scheme and port mismatches as deceptive", () => {
		const schemeHtml = renderToStaticMarkup(
			<MemoizedMarkdown content="[https://example.com](http://example.com/login)" />,
		);
		expect(schemeHtml).toContain('href="#confirm-external-link"');
		expect(schemeHtml).not.toContain('href="http://example.com/login"');

		const portHtml = renderToStaticMarkup(
			<MemoizedMarkdown content="[example.com](https://example.com:8080/admin)" />,
		);
		expect(portHtml).toContain('href="#confirm-external-link"');
		expect(portHtml).not.toContain('href="https://example.com:8080/admin"');
	});

	test("leaves app-local and fragment links navigable", () => {
		const html = renderToStaticMarkup(
			<MemoizedMarkdown content="[Details](#details) [Home](/)" />,
		);

		expect(html).toContain('href="#details"');
		expect(html).toContain('href="/"');
		expect(html).not.toContain('aria-haspopup="dialog"');
	});

	test("blocks scheme-less hostnames before they reach link rendering", () => {
		const html = renderToStaticMarkup(
			<MemoizedMarkdown content="[Review](example.com/path)" />,
		);

		expect(html).toContain("Review");
		expect(html).toContain("blocked");
		expect(html).not.toContain("<a");
		expect(html).not.toContain('data-streamdown="link"');
	});

	test("does not expose unsafe script URLs or raw scripts", () => {
		const html = renderToStaticMarkup(
			<MemoizedMarkdown
				content={
					'[unsafe](javascript:alert("no"))\n\n![embedded](data:image/png;base64,iVBORw0KGgo=)\n\n![file](file:///etc/passwd)\n\n<script>window.pwned = true</script>'
				}
			/>,
		);

		expect(html).not.toContain("javascript:");
		expect(html).not.toContain("data:image");
		expect(html).not.toContain("file:///etc/passwd");
		expect(html).not.toContain("<script");
	});
});

import {
	agentMarkdownControls,
	markdownCodeHighlighter,
} from "@cline/ui/components/markdown";
import { cjk } from "@streamdown/cjk";
import type { ComponentProps, MouseEvent, ReactNode } from "react";
import { isValidElement, memo, useState } from "react";
import {
	type Components,
	type ExtraProps,
	type LinkSafetyModalProps,
	Streamdown,
} from "streamdown";
import { openExternalUrl } from "@/lib/desktop-client";
import { cn } from "@/lib/utils";
import {
	AlertDialog,
	AlertDialogAction,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogTitle,
} from "./alert-dialog";

const streamdownPlugins = { cjk, code: markdownCodeHighlighter };

export function MarkdownLinkSafetyModal({
	isOpen,
	onClose,
	onConfirm,
	url,
}: LinkSafetyModalProps) {
	return (
		<AlertDialog
			onOpenChange={(open) => {
				if (!open) onClose();
			}}
			open={isOpen}
		>
			<AlertDialogContent>
				<AlertDialogHeader>
					<AlertDialogTitle>Open external link?</AlertDialogTitle>
					<AlertDialogDescription>
						You are about to leave Cline and visit this address.
					</AlertDialogDescription>
				</AlertDialogHeader>
				<div className="max-h-32 overflow-y-auto wrap-break-word rounded-md bg-muted p-3 font-mono text-sm">
					{url}
				</div>
				<AlertDialogFooter>
					<AlertDialogCancel>Cancel</AlertDialogCancel>
					<AlertDialogAction onClick={onConfirm}>Open link</AlertDialogAction>
				</AlertDialogFooter>
			</AlertDialogContent>
		</AlertDialog>
	);
}

type MarkdownLinkProps = ComponentProps<"a"> & ExtraProps;

function extractLinkText(children: ReactNode): string {
	if (typeof children === "string" || typeof children === "number") {
		return String(children);
	}
	if (Array.isArray(children)) {
		return children.map(extractLinkText).join("");
	}
	// Inline formatting (**bold**, `code`, …) nests the label text inside
	// elements; recurse so styled hostnames can't dodge the deception check.
	if (isValidElement(children)) {
		return extractLinkText(
			(children.props as { children?: ReactNode }).children,
		);
	}
	return "";
}

// Tolerates one trailing dot after the TLD ("github.com." resolves the same
// as "github.com" in browsers) and a protocol-relative "//" prefix, so those
// label spellings can't slip past the deception check.
const urlLikeTextPattern =
	/^(?:https?:\/\/|\/\/)?(?:[\w-]+\.)+[a-z]{2,}\.?(?:[/:?#]\S*)?$/i;

type LinkParts = {
	protocol: string;
	hostname: string;
	port: string;
	explicitScheme: boolean;
};

function parseLinkParts(value: string): LinkParts | null {
	const explicitScheme = /^[a-z][a-z\d+.-]*:/i.test(value);
	const withScheme = explicitScheme
		? value
		: value.startsWith("//")
			? `https:${value}`
			: `https://${value}`;
	try {
		const parsed = new URL(withScheme);
		const hostname = parsed.hostname
			.toLowerCase()
			.replace(/\.+$/, "")
			.replace(/^www\./, "");
		if (!hostname) return null;
		return {
			explicitScheme,
			hostname,
			port: parsed.port,
			protocol: parsed.protocol,
		};
	} catch {
		return null;
	}
}

/**
 * A link is deceptive when its visible text reads as a URL that does not
 * match the real destination — the one shape where a click genuinely
 * surprises the user. Only those links get the confirmation dialog;
 * ordinary external links open directly. The label and destination must
 * agree on hostname and port, and on scheme when the label states one.
 */
function isDeceptiveLink(children: ReactNode, url: string): boolean {
	const text = extractLinkText(children).trim();
	if (!text || !urlLikeTextPattern.test(text)) return false;
	const textParts = parseLinkParts(text);
	if (!textParts) return false;
	const urlParts = parseLinkParts(url);
	if (!urlParts) return true;
	return (
		textParts.hostname !== urlParts.hostname ||
		textParts.port !== urlParts.port ||
		(textParts.explicitScheme && textParts.protocol !== urlParts.protocol)
	);
}

function SafeMarkdownLink({
	children,
	className,
	href,
	node: _node,
	rel: _rel,
	target: _target,
	title,
	...props
}: MarkdownLinkProps) {
	const [isOpen, setIsOpen] = useState(false);
	const isIncomplete = href === "streamdown:incomplete-link";
	const url = isIncomplete ? undefined : href;

	if (!url) {
		return (
			<span
				className={className}
				data-incomplete={isIncomplete}
				data-streamdown="link"
			>
				{children}
			</span>
		);
	}

	const isAppLink =
		url.startsWith("#") ||
		(url.startsWith("/") && !url.startsWith("//")) ||
		url.startsWith("./") ||
		url.startsWith("../") ||
		(!/^[a-z][a-z\d+.-]*:/i.test(url) && !url.startsWith("//"));

	if (isAppLink) {
		return (
			<a
				{...props}
				className={`wrap-anywhere font-medium text-primary underline ${className ?? ""}`}
				data-streamdown="link"
				href={url}
				title={title}
			>
				{children}
			</a>
		);
	}

	// Streamdown's harden step only lets http(s), mailto, tel, and
	// protocol-relative URLs reach this component, matching the sidecar's
	// open_external_url allowlist. Protocol-relative URLs fail the sidecar's
	// `new URL()` parse, so pin them to https before handing them off.
	const externalUrl = url.startsWith("//") ? `https:${url}` : url;
	const openExternally = () => void openExternalUrl(externalUrl);

	if (!isDeceptiveLink(children, externalUrl)) {
		const openDirectly = (event: MouseEvent<HTMLAnchorElement>) => {
			event.preventDefault();
			openExternally();
		};
		return (
			<a
				{...props}
				className={`wrap-anywhere font-medium text-primary underline ${className ?? ""}`}
				data-streamdown="link"
				href={externalUrl}
				onAuxClick={(event) => {
					if (event.button === 1) openDirectly(event);
				}}
				onClick={openDirectly}
				rel="noreferrer"
				title={title ?? externalUrl}
			>
				{children}
			</a>
		);
	}

	const openConfirmation = (event: MouseEvent<HTMLAnchorElement>) => {
		event.preventDefault();
		setIsOpen(true);
	};
	const confirmMiddleClick = (event: MouseEvent<HTMLAnchorElement>) => {
		if (event.button === 1) openConfirmation(event);
	};

	return (
		<>
			{/* biome-ignore lint/a11y/useValidAnchor: External Markdown retains native link semantics while confirmation withholds the live destination. */}
			<a
				{...props}
				aria-haspopup="dialog"
				className={`wrap-anywhere font-medium text-primary underline ${className ?? ""}`}
				data-streamdown="link"
				href="#confirm-external-link"
				onAuxClick={confirmMiddleClick}
				onClick={openConfirmation}
				title={title ?? externalUrl}
			>
				{children}
			</a>
			<MarkdownLinkSafetyModal
				isOpen={isOpen}
				onClose={() => setIsOpen(false)}
				onConfirm={openExternally}
				url={externalUrl}
			/>
		</>
	);
}

type MarkdownImageProps =
	| (ComponentProps<"img"> & ExtraProps)
	| (Record<string, unknown> & ExtraProps);

const remoteImagePattern = /^(?:https?:)?[\\/]{2}/i;

function isSafeMarkdownImageSource(source: string): boolean {
	const normalized = source.trim();
	if (!normalized || remoteImagePattern.test(normalized)) return false;

	// Streamdown's hardened URL policy accepts app-root paths. Keeping the rule
	// this narrow prevents model-authored Markdown from making hidden requests.
	return normalized.startsWith("/");
}

function MarkdownImage({ alt, height, src, title, width }: MarkdownImageProps) {
	const label = typeof alt === "string" ? alt.trim() : "";
	const source = typeof src === "string" ? src.trim() : "";

	if (source && isSafeMarkdownImageSource(source)) {
		return (
			// biome-ignore lint/performance/noImgElement: Markdown can reference runtime app assets that Next Image cannot statically optimize.
			<img
				alt={label}
				className="my-4 max-w-full rounded-lg"
				data-streamdown="image"
				height={typeof height === "number" ? height : undefined}
				loading="lazy"
				src={source}
				title={typeof title === "string" ? title : undefined}
				width={typeof width === "number" ? width : undefined}
			/>
		);
	}

	return (
		<span data-streamdown="blocked-image" role="note">
			External image blocked for privacy{label ? `: ${label}` : ""}
		</span>
	);
}

const markdownComponents = {
	a: SafeMarkdownLink,
	img: MarkdownImage,
} satisfies Components;

export const MemoizedMarkdown = memo(
	({
		content,
		classNames,
		streaming = false,
	}: {
		content: string;
		streaming?: boolean;
		classNames?: string;
	}) => (
		<Streamdown
			className={cn("cline-markdown", classNames)}
			components={markdownComponents}
			controls={agentMarkdownControls}
			dir="auto"
			isAnimating={streaming}
			lineNumbers={false}
			mode={streaming ? "streaming" : "static"}
			normalizeHtmlIndentation
			parseIncompleteMarkdown={streaming}
			plugins={streamdownPlugins}
		>
			{content}
		</Streamdown>
	),
);

MemoizedMarkdown.displayName = "MemoizedMarkdown";

