const SIDEBAR_COOKIE_NAME = "sidebar_state";
const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7;
const SIDEBAR_WIDTH = 240;
const SIDEBAR_WIDTH_MOBILE = "18rem";
// macOS title-bar controls overlay the webview, so the collapsed rail only
// needs to reserve enough width for its own controls.
const SIDEBAR_WIDTH_ICON = "3rem";
const SIDEBAR_KEYBOARD_SHORTCUT = "b";
const SIDEBAR_WIDTH_COOKIE_NAME = "sidebar_width";
const SIDEBAR_MIN_WIDTH = 224;
const SIDEBAR_MAX_WIDTH = 560;

function clampSidebarWidth(value: number): number {
	return Math.min(SIDEBAR_MAX_WIDTH, Math.max(SIDEBAR_MIN_WIDTH, value));
}

function setCookieValue(name: string, value: string | number | boolean): void {
	const cookie = `${encodeURIComponent(name)}=${encodeURIComponent(
		String(value),
	)}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`;
	const cookieStore = (
		globalThis as {
			cookieStore?: {
				set(options: {
					name: string;
					value: string;
					path: string;
					expires: number;
				}): Promise<void>;
			};
		}
	).cookieStore;
	if (cookieStore) {
		void cookieStore.set({
			name,
			value: String(value),
			path: "/",
			expires: Date.now() + SIDEBAR_COOKIE_MAX_AGE * 1000,
		});
		return;
	}
	const cookieSetter = Object.getOwnPropertyDescriptor(
		Document.prototype,
		"cookie",
	)?.set;
	cookieSetter?.call(document, cookie);
}

function getCookieValue(name: string): string | null {
	if (typeof document === "undefined") {
		return null;
	}
	const encoded = `${encodeURIComponent(name)}=`;
	const found = document.cookie
		.split(";")
		.map((part) => part.trim())
		.find((part) => part.startsWith(encoded));
	if (!found) {
		return null;
	}
	return decodeURIComponent(found.slice(encoded.length));
}

type SidebarContextProps = {
	state: "expanded" | "collapsed";
	open: boolean;
	setOpen: (open: boolean | ((open: boolean) => boolean)) => void;
	desktopWidth: number;
	setDesktopWidth: (width: number) => void;
	openMobile: boolean;
	setOpenMobile: (open: boolean | ((open: boolean) => boolean)) => void;
	isMobile: boolean;
	toggleSidebar: () => void;
};

const SidebarContext = React.createContext<SidebarContextProps | null>(null);

function useSidebar() {
	const context = React.useContext(SidebarContext);
	if (!context) {
		throw new Error("useSidebar must be used within a SidebarProvider.");
	}

	return context;
}

function SidebarProvider({
	defaultOpen = true,
	open: openProp,
	onOpenChange: setOpenProp,
	className,
	style,
	children,
	...props
}: React.ComponentProps<"div"> & {
	defaultOpen?: boolean;
	open?: boolean;
	onOpenChange?: (open: boolean) => void;
}) {
	const isMobile = useIsMobile();
	const [openMobile, setOpenMobile] = React.useState(false);
	const [desktopWidth, setDesktopWidthState] =
		React.useState<number>(SIDEBAR_WIDTH);

	// Read persisted width from cookie after hydration to avoid mismatch
	React.useEffect(() => {
		const cookieValue = getCookieValue(SIDEBAR_WIDTH_COOKIE_NAME);
		const parsedWidth = Number(cookieValue);
		if (Number.isFinite(parsedWidth)) {
			setDesktopWidthState(clampSidebarWidth(parsedWidth));
		}
	}, []);

	// This is the internal state of the sidebar.
	// We use openProp and setOpenProp for control from outside the component.
	const [_open, _setOpen] = React.useState(defaultOpen);
	const open = openProp ?? _open;
	const setOpen = React.useCallback(
		(value: boolean | ((value: boolean) => boolean)) => {
			const openState = typeof value === "function" ? value(open) : value;
			if (setOpenProp) {
				setOpenProp(openState);
			} else {
				_setOpen(openState);
			}

			setCookieValue(SIDEBAR_COOKIE_NAME, openState);
		},
		[setOpenProp, open],
	);

	// Helper to toggle the sidebar.
	const toggleSidebar = React.useCallback(() => {
		return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open);
	}, [isMobile, setOpen]);

	const setDesktopWidth = React.useCallback((width: number) => {
		const next = clampSidebarWidth(width);
		setDesktopWidthState(next);
		setCookieValue(SIDEBAR_WIDTH_COOKIE_NAME, next);
	}, []);

	// Adds a keyboard shortcut to toggle the sidebar.
	React.useEffect(() => {
		const handleKeyDown = (event: KeyboardEvent) => {
			if (
				event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
				(event.metaKey || event.ctrlKey)
			) {
				event.preventDefault();
				toggleSidebar();
			}
		};

		window.addEventListener("keydown", handleKeyDown);
		return () => window.removeEventListener("keydown", handleKeyDown);
	}, [toggleSidebar]);

	// We add a state so that we can do data-state="expanded" or "collapsed".
	// This makes it easier to style the sidebar with Tailwind classes.
	const state = open ? "expanded" : "collapsed";

	const contextValue = React.useMemo<SidebarContextProps>(
		() => ({
			state,
			open,
			setOpen,
			desktopWidth,
			setDesktopWidth,
			isMobile,
			openMobile,
			setOpenMobile,
			toggleSidebar,
		}),
		[
			state,
			open,
			setOpen,
			desktopWidth,
			setDesktopWidth,
			isMobile,
			openMobile,
			toggleSidebar,
		],
	);

	return (
		<SidebarContext.Provider value={contextValue}>
			<TooltipProvider delayDuration={0}>
				<div
					data-slot="sidebar-wrapper"
					data-state={state}
					style={
						{
							"--sidebar-width": `${desktopWidth}px`,
							"--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
							...style,
						} as React.CSSProperties
					}
					className={cn(
						"group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full",
						className,
					)}
					{...props}
				>
					{children}
				</div>
			</TooltipProvider>
		</SidebarContext.Provider>
	);
}

function Sidebar({
	side = "left",
	variant = "sidebar",
	collapsible = "offcanvas",
