function makeToolMessage(
	payload: unknown,
	overrides: Partial<ChatMessage> = {},
): ChatMessage {
	return {
		id: "tool-1",
		sessionId: "session-1",
		role: "tool",
		content: typeof payload === "string" ? payload : JSON.stringify(payload),
		createdAt: 1,
		...overrides,
	} as ChatMessage;
}

