describe("buildGroupedToolLabel over presentations", () => {
	function presentationFor(payload: {
		toolName: string;
		input?: unknown;
		result?: unknown;
	}) {
		return buildToolPresentation(
			makeToolMessage({ result: {}, ...payload }, { id: payload.toolName }),
		);
	}

	function toGroupInput(presentation: {
		summary: { label: string; aggregate?: unknown };
		inProgress: boolean;
	}) {
		return {
			label: presentation.summary.label,
			aggregate: presentation.summary.aggregate as never,
			inProgress: presentation.inProgress,
		};
	}

	it("returns the single summary label untouched", () => {
		const only = presentationFor({
			toolName: "read_files",
			input: { paths: ["a.ts"] },
		});
		expect(buildGroupedToolLabel([toGroupInput(only)])).toBe("Read file a.ts");
	});

	it("merges consecutive aggregates that share a key", () => {
		const first = presentationFor({
			toolName: "read_files",
			input: { paths: ["a.ts", "b.ts"] },
		});
		const second = presentationFor({
			toolName: "read_files",
			input: { paths: ["c.ts"] },
		});
		expect(
			buildGroupedToolLabel([toGroupInput(first), toGroupInput(second)]),
		).toBe("Read 3 files");
	});

	it("joins non-mergeable segments with separators and keeps progress verbs", () => {
		const reads = presentationFor({
			toolName: "read_files",
			input: { paths: ["a.ts", "b.ts"] },
		});
		const running = buildToolPresentation(
			makeToolMessage(
				{
					toolName: "run_commands",
					input: { commands: ["bun test"] },
					result: null,
				},
				{ id: "cmd" },
			),
		);
		expect(
			buildGroupedToolLabel([toGroupInput(reads), toGroupInput(running)]),
		).toBe("Read 2 files · Running 1 command");
	});
});

import {
	buildToolSummary,
	type ToolSummary,
} from "@cline/ui/components/agent-chat/tool-summary";
import type { ChatMessage } from "@/lib/chat-schema";

/**
 * Thin presentation layer between the desktop chat transcript and the shared
 * `@cline/ui` tool-summary module: it owns the app's tool-message payload
 * schema and hook-event conventions, then delegates label/detail/diff
 * construction to `buildToolSummary`.
 */
export type ToolPayload = {
	toolName?: string;
	input?: unknown;
	result?: unknown;
	isError?: boolean;
};

export function parseJsonString(value: string): unknown {
	try {
		return JSON.parse(value) as unknown;
	} catch {
		return value;
	}
}

export function normalizeDisplayValue(value: unknown): unknown {
	if (typeof value !== "string") {
		return value;
	}
	const trimmed = value.trim();
	if (
		(trimmed.startsWith("{") && trimmed.endsWith("}")) ||
		(trimmed.startsWith("[") && trimmed.endsWith("]"))
	) {
		return parseJsonString(trimmed);
	}
	return value;
}

export function formatToolValue(value: unknown): string {
	const normalized = normalizeDisplayValue(value);
	if (normalized == null) {
		return "";
	}
	if (typeof normalized === "string") {
		return normalized;
	}
	if (
		typeof normalized === "object" &&
		"error" in normalized &&
		typeof normalized.error === "string"
	) {
		return normalized.error;
	}
	try {
		return JSON.stringify(normalized, null, 2);
	} catch {
		return String(normalized);
	}
}

function asRecord(value: unknown): Record<string, unknown> | null {
	if (!value || typeof value !== "object" || Array.isArray(value)) return null;
	return value as Record<string, unknown>;
}

function recordString(
	record: Record<string, unknown> | null | undefined,
	key: string,
	fallback = "",
): string {
	const value = record?.[key];
	return typeof value === "string" && value.length > 0 ? value : fallback;
}

export function extractRunCommandOutput(value: unknown): string {
	const normalized = normalizeDisplayValue(value);
	if (typeof normalized === "string") return normalized;
	const records = Array.isArray(normalized)
		? normalized.map(asRecord).filter((record) => record !== null)
		: [asRecord(normalized)].filter((record) => record !== null);
	const includeCommand = records.length > 1;
	return records
		.map((record) => {
			const result = recordString(record, "result");
			const error = recordString(record, "error");
			const output = result || error;
			if (!output) return "";
			const query = recordString(record, "query");
			return includeCommand && query ? `$ ${query}\n${output}` : output;
		})
		.filter(Boolean)
		.join("\n\n");
}

export function parseToolPayload(raw: string): ToolPayload | null {
	try {
		return JSON.parse(raw) as ToolPayload;
	} catch {
		return null;
	}
}

export type ToolPresentation = {
	message: ChatMessage;
	payload: ToolPayload | null;
	toolName: string;
	inProgress: boolean;
	summary: ToolSummary;
};

export function buildToolPresentation(message: ChatMessage): ToolPresentation {
	const payload = parseToolPayload(message.content);
	const toolName = message.meta?.toolName || payload?.toolName || "tool";
	const hookEventName = message.meta?.hookEventName;
	const inProgress =
		hookEventName === "tool_call_start" ||
		hookEventName === "history_tool_use" ||
		(Boolean(payload) && payload?.result == null && !payload?.isError);
	const summary = buildToolSummary({
		toolName,
		input: payload?.input,
		result: payload?.result,
		isError: Boolean(payload?.isError),
		inProgress,
	});
	return { message, payload, toolName, inProgress, summary };
}

