	| { status: "installing" }
	| { status: "uninstalling" }
	| {
			status: "installed";
			message: string;
	  }
	| {
			status: "uninstalled";
			message: string;
	  }
	| { status: "failed"; message: string };

type MarketplaceInstallResult = {
	status: "installed" | "uninstalled";
	message: string;
	output?: string;
};

type MarketplaceInstallStatusResult = {
	installedKeys: string[];
};

type InstalledStatusState = "loading" | "ready";

