		// interruption (websocket events are not replayed); only its
		// detail-less failure arrives. It must not resurrect turn A's error.
		await act(async () => {
			chatEventHandler?.({
				sessionId: current.sessionId,
				stream: "chat_done",
				chunk: JSON.stringify({ reason: "error" }),
				ts: Date.now(),
				index: 3,
