import type { ProcessContext } from "@/hooks/chat-session/types";
import { productNameForVersion, STABLE_PRODUCT_NAME } from "@/lib/app-channel";
import { desktopClient, isTauriAvailable } from "@/lib/desktop-client";

export const DEFAULT_DESKTOP_WINDOW_TITLE = STABLE_PRODUCT_NAME;

export function buildDesktopWindowTitle(version: string | undefined): string {
	const trimmed = version?.trim();
	return trimmed
		? `${productNameForVersion(trimmed)} v${trimmed}`
		: DEFAULT_DESKTOP_WINDOW_TITLE;
}

/**
 * Tauri's window title is static in tauri.conf.json; append the running app
 * version once the sidecar reports it. No-op outside the Tauri shell (e.g.
 * sidecar/web dev mode), where there is no native window to retitle.
 */
export async function syncDesktopWindowTitle(): Promise<void> {
	if (!isTauriAvailable()) {
		return;
	}
	try {
		const ctx = await desktopClient.invoke<ProcessContext>(
			"get_process_context",
		);
		if (!ctx.appVersion?.trim()) {
			return;
		}
		const { getCurrentWindow } = await import("@tauri-apps/api/window");
		await getCurrentWindow().setTitle(buildDesktopWindowTitle(ctx.appVersion));
	} catch {
		// Keep the default static title if the sidecar or window API is unavailable.
	}
}

import { describe, expect, it } from "vitest";
import { createLatestSuccessfulRequestGate } from "./latest-successful-request";

describe("createLatestSuccessfulRequestGate", () => {
	it("allows an earlier successful request to commit when a newer request fails", () => {
		const gate = createLatestSuccessfulRequestGate();
		const successfulRequest = gate.begin();
		gate.begin();

		expect(gate.commit(successfulRequest)).toBe(true);
	});

	it("rejects a successful result older than the latest committed result", () => {
		const gate = createLatestSuccessfulRequestGate();
		const olderRequest = gate.begin();
		const newerRequest = gate.begin();

		expect(gate.commit(newerRequest)).toBe(true);
		expect(gate.commit(olderRequest)).toBe(false);
	});

	it("rejects in-flight results after an explicit invalidation", () => {
		const gate = createLatestSuccessfulRequestGate();
		const staleRequest = gate.begin();

		gate.invalidate();

		expect(gate.commit(staleRequest)).toBe(false);
		expect(gate.commit(gate.begin())).toBe(true);
	});
});

export type LatestSuccessfulRequestGate = {
	begin: () => number;
	commit: (requestId: number) => boolean;
	invalidate: () => void;
};

/**
 * Coordinates overlapping reads so failures do not invalidate a known-good
 * result. A successful read may commit unless a newer successful read or an
 * explicit invalidation has already advanced the commit watermark.
 */
export function createLatestSuccessfulRequestGate(): LatestSuccessfulRequestGate {
	let issuedRequestId = 0;
	let committedRequestId = 0;

	return {
		begin: () => {
			issuedRequestId += 1;
			return issuedRequestId;
		},
		commit: (requestId) => {
			if (requestId <= committedRequestId) {
				return false;
			}
			committedRequestId = requestId;
			return true;
		},
		invalidate: () => {
			issuedRequestId += 1;
			committedRequestId = issuedRequestId;
		},
	};
}

"use client";

import { resolveDesktopBackendHttpEndpoint } from "@/lib/desktop-client";

export type MarketplacePrimitiveType = "mcp" | "skill" | "plugin";

export type MarketplaceTag = {
	id: string;
	label: string;
	count: number;
};

export type MarketplaceEnvVar = {
	name: string;
	required?: boolean;
	description?: string;
	url?: string;
};

export type MarketplaceEntry = {
	id: string;
	type: MarketplacePrimitiveType;
	name: string;
	featured?: boolean;
	tagline: string;
	description: string;
	tags: string[];
	install: {
		args: string[];
		env?: MarketplaceEnvVar[];
		notes?: string;
		command: string;
	};
};

export type MarketplaceCatalog = {
	version: number;
	generatedAt?: string;
	baseUrl?: string;
	counts: {
		total: number;
		plugins: number;
		skills: number;
		mcps: number;
	};
	tags: MarketplaceTag[];
	entries: MarketplaceEntry[];
};

const MARKETPLACE_CATALOG_URL = "/api/marketplace/catalog";

const EMPTY_CATALOG: MarketplaceCatalog = {
	version: 1,
	counts: {
		total: 0,
		plugins: 0,
		skills: 0,
		mcps: 0,
	},
	tags: [],
	entries: [],
};

function isPrimitiveType(value: unknown): value is MarketplacePrimitiveType {
	return value === "mcp" || value === "skill" || value === "plugin";
}

function toStringArray(value: unknown): string[] {
	return Array.isArray(value)
		? value.filter((item): item is string => typeof item === "string")
		: [];
}

function parseCount(value: unknown): number {
	return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function parseEnv(value: unknown): MarketplaceEnvVar[] | undefined {
	if (!Array.isArray(value)) return undefined;
	const env = value
		.map((item): MarketplaceEnvVar | null => {
			if (!item || typeof item !== "object") return null;
			const candidate = item as Record<string, unknown>;
			if (typeof candidate.name !== "string") return null;
			const parsed: MarketplaceEnvVar = {
				name: candidate.name,
			};
			if (typeof candidate.required === "boolean") {
				parsed.required = candidate.required;
			}
			if (typeof candidate.description === "string") {
				parsed.description = candidate.description;
			}
			if (typeof candidate.url === "string") {
				parsed.url = candidate.url;
			}
			return parsed;
		})
		.filter((item): item is MarketplaceEnvVar => item !== null);
	return env.length > 0 ? env : undefined;
}

export async function fetchMarketplaceCatalog(): Promise<MarketplaceCatalog> {
	const urls = [MARKETPLACE_CATALOG_URL];
	try {
		const backendEndpoint = await resolveDesktopBackendHttpEndpoint();
		urls.unshift(new URL(MARKETPLACE_CATALOG_URL, `${backendEndpoint}/`).href);
	} catch {
		// Fall back to the statically exported route when the sidecar is unavailable.
	}

	let data: unknown;
	let lastError: unknown;
	for (const url of urls) {
		try {
			const response = await fetch(url, {
				headers: { Accept: "application/json" },
			});
			if (!response.ok) {
				throw new Error(`Failed to fetch marketplace: ${response.status}`);
			}
			data = await response.json();
			break;
		} catch (error) {
			lastError = error;
		}
	}

	if (data === undefined) {
		throw lastError instanceof Error
			? lastError
			: new Error("Failed to fetch marketplace");
	}

	const baseUrl = typeof data?.baseUrl === "string" ? data.baseUrl : undefined;
	const rawCounts =
		typeof data?.counts === "object" && data.counts !== null ? data.counts : {};

	const tags: MarketplaceTag[] = Array.isArray(data?.tags)
		? data.tags
				.map((tag: unknown) => {
					if (!tag || typeof tag !== "object") return null;
					const candidate = tag as Record<string, unknown>;
					if (
						typeof candidate.id !== "string" ||
						typeof candidate.label !== "string"
					) {
						return null;
					}
					return {
						id: candidate.id,
						label: candidate.label,
						count: parseCount(candidate.count),
					};
				})
				.filter(
					(tag: MarketplaceTag | null): tag is MarketplaceTag => tag !== null,
				)
		: [];

	const entries: MarketplaceEntry[] = Array.isArray(data?.entries)
		? data.entries
				.map((entry: unknown) => {
					if (!entry || typeof entry !== "object") return null;
					const candidate = entry as Record<string, unknown>;
					const install =
						typeof candidate.install === "object" && candidate.install !== null
							? (candidate.install as Record<string, unknown>)
							: {};
					if (
						typeof candidate.id !== "string" ||
						!isPrimitiveType(candidate.type) ||
						typeof candidate.name !== "string" ||
						typeof candidate.tagline !== "string" ||
						typeof candidate.description !== "string" ||
						typeof install.command !== "string"
					) {
						return null;
					}
					return {
						id: candidate.id,
						type: candidate.type,
						name: candidate.name,
						featured:
							typeof candidate.featured === "boolean"
								? candidate.featured
								: undefined,
						tagline: candidate.tagline,
						description: candidate.description,
						tags: toStringArray(candidate.tags),
						install: {
							args: toStringArray(install.args),
							command: install.command,
							env: parseEnv(install.env),
							notes:
								typeof install.notes === "string" ? install.notes : undefined,
						},
					};
				})
				.filter(
					(entry: MarketplaceEntry | null): entry is MarketplaceEntry =>
						entry !== null && entry.install.args.length > 0,
				)
		: [];

	return {
		version: parseCount(data?.version) || EMPTY_CATALOG.version,
		generatedAt:
			typeof data?.generatedAt === "string" ? data.generatedAt : undefined,
		baseUrl,
		counts: {
			total: parseCount(rawCounts.total) || entries.length,
			plugins: parseCount(rawCounts.plugins),
			skills: parseCount(rawCounts.skills),
			mcps: parseCount(rawCounts.mcps),
		},
		tags,
		entries,
	};
}

