export const MODEL_SELECTION_STORAGE_KEY = "cline.code.model-selection.v1";

export type ModelSelectionStorage = {
	lastProvider: string;
	lastModelByProvider: Record<string, string>;
};

function sanitizeStringRecord(value: unknown): Record<string, string> {
	if (!value || typeof value !== "object" || Array.isArray(value)) {
		return {};
	}
	return Object.fromEntries(
		Object.entries(value).filter(
			([key, entry]) =>
				typeof key === "string" &&
				typeof entry === "string" &&
				entry.trim().length > 0,
		),
	);
}

export function parseModelSelectionStorage(
	raw: string | null,
): ModelSelectionStorage {
	const empty: ModelSelectionStorage = {
		lastProvider: "",
		lastModelByProvider: {},
	};
	if (!raw) {
		return empty;
	}

	try {
		const parsed = JSON.parse(raw) as unknown;
		if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
			return empty;
		}

		const shaped = parsed as {
			lastProvider?: unknown;
			lastModelByProvider?: unknown;
		};

		if ("lastProvider" in shaped || "lastModelByProvider" in shaped) {
			return {
				lastProvider:
					typeof shaped.lastProvider === "string"
						? shaped.lastProvider.trim()
						: "",
				lastModelByProvider: sanitizeStringRecord(shaped.lastModelByProvider),
			};
		}

		return {
			lastProvider: "",
			lastModelByProvider: sanitizeStringRecord(parsed),
		};
	} catch {
		return empty;
	}
}

export function readModelSelectionStorageFromWindow(): ModelSelectionStorage {
	if (typeof window === "undefined") {
		return {
			lastProvider: "",
			lastModelByProvider: {},
		};
	}
	return parseModelSelectionStorage(
		window.localStorage.getItem(MODEL_SELECTION_STORAGE_KEY),
	);
}

export function writeModelSelectionStorageToWindow(
	value: ModelSelectionStorage,
): void {
	if (typeof window === "undefined") {
		return;
	}
	window.localStorage.setItem(
		MODEL_SELECTION_STORAGE_KEY,
		JSON.stringify(value),
	);
}

import { describe, expect, it } from "vitest";
import {
	createNavigationHistory,
	navigationHistoryReducer,
} from "./navigation-history";

type Location = {
	view: "chat" | "settings";
	thread: string;
	settingsSection: "General" | "Account";
};

const welcome: Location = {
	view: "chat",
	thread: "welcome",
	settingsSection: "General",
};
const account: Location = {
	view: "settings",
	thread: "welcome",
	settingsSection: "Account",
};
const oldSession: Location = {
	view: "chat",
	thread: "old-session",
	settingsSection: "Account",
};

describe("navigationHistoryReducer", () => {
	it("returns from an old session to the welcome chat and can go forward again", () => {
		let history = createNavigationHistory(welcome);
		history = navigationHistoryReducer(history, {
			type: "navigate",
			destination: oldSession,
		});
		history = navigationHistoryReducer(history, { type: "back" });
		expect(history.current).toEqual(welcome);
		history = navigationHistoryReducer(history, { type: "forward" });
		expect(history.current).toEqual(oldSession);
	});

	it("restores the account view after opening a session from settings", () => {
		let history = createNavigationHistory(account);
		history = navigationHistoryReducer(history, {
			type: "navigate",
			destination: oldSession,
		});
		history = navigationHistoryReducer(history, { type: "back" });
		expect(history.current).toEqual(account);
		history = navigationHistoryReducer(history, { type: "forward" });
		expect(history.current).toEqual(oldSession);
	});

	it("clears forward history after navigating somewhere new", () => {
		let history = createNavigationHistory(welcome);
		history = navigationHistoryReducer(history, {
			type: "navigate",
			destination: oldSession,
		});
		history = navigationHistoryReducer(history, { type: "back" });
		history = navigationHistoryReducer(history, {
			type: "navigate",
			destination: account,
		});
		expect(history.forward).toEqual([]);
	});

	it("removes invalidated destinations from both history stacks", () => {
		let history = createNavigationHistory(welcome);
		history = navigationHistoryReducer(history, {
			type: "navigate",
			destination: oldSession,
		});
		history = navigationHistoryReducer(history, {
			type: "navigate",
			destination: account,
		});
		history = navigationHistoryReducer(history, { type: "back" });

		history = navigationHistoryReducer(history, {
			type: "reconcile",
			fallback: welcome,
			reconcile: (location) =>
				location.thread === oldSession.thread ? null : location,
		});

		expect(history.current).toEqual(welcome);
		expect(history.back).toEqual([welcome]);
		expect(history.forward).toEqual([account]);
	});

	it("can preserve non-chat destinations while replacing an invalid thread", () => {
		const settingsOnDeletedThread = {
			...account,
			thread: oldSession.thread,
		};
		let history = createNavigationHistory(settingsOnDeletedThread);

		history = navigationHistoryReducer(history, {
			type: "reconcile",
			fallback: welcome,
			reconcile: (location) =>
				location.view === "settings"
					? { ...location, thread: welcome.thread }
					: null,
		});

		expect(history.current).toEqual(account);
	});
});

export type NavigationHistory<T> = {
	back: T[];
	current: T;
	forward: T[];
};

export type NavigationHistoryAction<T> =
	| { type: "navigate"; destination: T }
	| { type: "back" }
	| { type: "forward" }
	| { type: "replace"; destination: T }
	| {
			type: "reconcile";
			fallback: T;
			reconcile: (location: T) => T | null;
	  };

function reconcileLocations<T>(
	locations: T[],
	reconcile: (location: T) => T | null,
): T[] {
	return locations.flatMap((location) => {
		const reconciled = reconcile(location);
		return reconciled === null ? [] : [reconciled];
	});
}

export function createNavigationHistory<T>(
	initialLocation: T,
): NavigationHistory<T> {
	return {
		back: [],
		current: initialLocation,
		forward: [],
	};
}

export function navigationHistoryReducer<T>(
	state: NavigationHistory<T>,
	action: NavigationHistoryAction<T>,
): NavigationHistory<T> {
	switch (action.type) {
		case "navigate":
			return {
				back: [...state.back, state.current],
				current: action.destination,
				forward: [],
			};
		case "back": {
			const destination = state.back.at(-1);
			if (!destination) return state;
			return {
				back: state.back.slice(0, -1),
				current: destination,
				forward: [state.current, ...state.forward],
			};
		}
		case "forward": {
			const destination = state.forward[0];
			if (!destination) return state;
			return {
				back: [...state.back, state.current],
				current: destination,
				forward: state.forward.slice(1),
			};
		}
		case "replace":
			return {
				...state,
				current: action.destination,
			};
		case "reconcile":
			return {
				back: reconcileLocations(state.back, action.reconcile),
				current: action.reconcile(state.current) ?? action.fallback,
				forward: reconcileLocations(state.forward, action.reconcile),
			};
	}
}

