import type { ChatMessage } from "@/lib/chat-schema";

/**
 * Header-level accounting of the child agents a session has started.
 *
 * There is no dedicated subagent event on the wire: the sidecar forwards
 * subagent activity into the parent session's stream without an agentId
 * (see sidecar/context.ts), so the only per-agent signal the webview can see
 * is the spawning tool call itself. Every counting rule below is therefore
 * derived from tool messages, which stay correct for live turns, for turns
 * materialized from a run result, and for hydrated history alike.
 */

export type SessionAgentRunState =
	| "running"
	| "completed"
	| "failed"
	| "cancelled"
	/** Dispatched, but no observed outcome — a run interrupted by a crash or reload. */
	| "unresolved";

export type SessionAgentActivity = {
	total: number;
	running: number;
	completed: number;
	failed: number;
	cancelled: number;
	unresolved: number;
};

export const EMPTY_AGENT_ACTIVITY: SessionAgentActivity = {
	total: 0,
	running: 0,
	completed: 0,
	failed: 0,
	cancelled: 0,
	unresolved: 0,
};

/**
 * `spawn_agent` runs the sub-agent inside its own execute(), so the tool call's
 * lifetime is the sub-agent's lifetime. Older transcripts recorded the same
 * call as `subagent_<name>`.
 */
const SUBAGENT_RUN_TOOL_NAMES = new Set([
	"spawn_agent",
	"spawn-agent",
	"spawn_agent_tool",
]);

const TEAM_RUN_TOOL_NAME = "team_run_task";

/** Tools whose results report the current status of previously dispatched runs. */
const TEAM_RUN_REPORT_TOOL_NAMES = new Set([
	"team_await_runs",
	"team_list_runs",
	"team_cancel_run",
]);

function normalizeToolName(toolName: string | undefined): string {
	return toolName?.trim().toLowerCase() ?? "";
}

function isSubagentRunTool(toolName: string): boolean {
	return (
		SUBAGENT_RUN_TOOL_NAMES.has(toolName) || toolName.startsWith("subagent_")
	);
}

export function isAgentRunToolName(toolName: string | undefined): boolean {
	const normalized = normalizeToolName(toolName);
	return isSubagentRunTool(normalized) || normalized === TEAM_RUN_TOOL_NAME;
}

type ToolPayload = {
	toolName?: string;
	input?: unknown;
	result?: unknown;
	isError?: boolean;
};

function asRecord(value: unknown): Record<string, unknown> | null {
	if (!value || typeof value !== "object" || Array.isArray(value)) {
		return null;
	}
	return value as Record<string, unknown>;
}

function parseJson(value: string): unknown {
	try {
		return JSON.parse(value) as unknown;
	} catch {
		return undefined;
	}
}

/**
 * Hydrated `tool_result` blocks carry the payload as text, so a result that
 * arrived as JSON has to be reparsed before its fields can be read.
 */
function normalizeResult(result: unknown): unknown {
	if (typeof result !== "string") {
		return result;
	}
	const trimmed = result.trim();
	if (!trimmed.startsWith("{") && !trimmed.startsWith("[")) {
		return result;
	}
	return parseJson(trimmed) ?? result;
}

function toStringValue(value: unknown): string | undefined {
	return typeof value === "string" && value.length > 0 ? value : undefined;
}

/** Mirrors ToolActivity's in-progress rule so the header agrees with the transcript. */
function isToolCallInProgress(
	hookEventName: string | undefined,
	payload: ToolPayload | null,
): boolean {
	if (
		hookEventName === "tool_call_start" ||
		hookEventName === "history_tool_use"
	) {
		return true;
	}
	return Boolean(payload) && payload?.result == null && !payload?.isError;
}

function mapTeamRunStatus(status: string | undefined): SessionAgentRunState {
	switch (status) {
		case "queued":
		case "running":
			return "running";
		case "completed":
			return "completed";
		case "failed":
			return "failed";
		case "cancelled":
		case "interrupted":
			return "cancelled";
		default:
			return "running";
	}
}

/** A sub-agent that hit its abort signal reports `finishReason: "aborted"`. */
function subagentStateFromResult(result: unknown): SessionAgentRunState {
	const finishReason = toStringValue(
		asRecord(normalizeResult(result))?.finishReason,
	);
	return finishReason === "aborted" ? "cancelled" : "completed";
}

function collectRunReports(
	result: unknown,
): Array<{ id: string; status?: string }> {
	const normalized = normalizeResult(result);
	const entries = Array.isArray(normalized) ? normalized : [normalized];
	const out: Array<{ id: string; status?: string }> = [];
	for (const entry of entries) {
		const record = asRecord(entry);
		if (!record) {
			continue;
		}
		// team_list_runs/team_await_runs report `id`; team_cancel_run reports `runId`.
		const id = toStringValue(record.id) ?? toStringValue(record.runId);
		if (!id) {
			continue;
		}
		out.push({ id, status: toStringValue(record.status) });
	}
	return out;
}

/**
 * Fold a session's tool messages into per-run states.
 *
 * Sub-agent runs and *sync* teammate runs are keyed by their tool message id,
 * because the tool call returns only once the agent is done. An *async*
 * teammate run returns a `runId` immediately and keeps working in the
 * background, so it is keyed by that runId and its state is refined by any
 * later team_await_runs / team_list_runs / team_cancel_run result.
 */
function collectAgentRunStates(
	messages: ChatMessage[],
): Map<string, SessionAgentRunState> {
	const states = new Map<string, SessionAgentRunState>();
	const asyncRunIds = new Set<string>();

	for (const message of messages) {
		if (message.role !== "tool") {
			continue;
		}
		const metaToolName = normalizeToolName(message.meta?.toolName);
		const isRunTool =
			isSubagentRunTool(metaToolName) || metaToolName === TEAM_RUN_TOOL_NAME;
		const isReportTool = TEAM_RUN_REPORT_TOOL_NAMES.has(metaToolName);
		// Parsing every tool payload would cost a JSON.parse per message on each
		// streaming flush, so only messages that can matter are parsed. A message
		// without meta.toolName is parsed to recover the name from the payload.
		if (metaToolName && !isRunTool && !isReportTool) {
			continue;
		}
		const payload = parseJson(message.content) as ToolPayload | undefined;
		const toolName = metaToolName || normalizeToolName(payload?.toolName);
		if (!toolName) {
			continue;
		}

		if (TEAM_RUN_REPORT_TOOL_NAMES.has(toolName)) {
			for (const report of collectRunReports(payload?.result)) {
				if (asyncRunIds.has(report.id)) {
					states.set(report.id, mapTeamRunStatus(report.status));
				}
			}
			continue;
		}

		const isSubagent = isSubagentRunTool(toolName);
		if (!isSubagent && toolName !== TEAM_RUN_TOOL_NAME) {
			continue;
		}

		if (isToolCallInProgress(message.meta?.hookEventName, payload ?? null)) {
			states.set(message.id, "running");
			continue;
		}
		if (payload?.isError) {
			states.set(message.id, "failed");
			continue;
		}
		if (isSubagent) {
			states.set(message.id, subagentStateFromResult(payload?.result));
			continue;
		}

		// team_run_task: only async mode outlives its tool call. Its returned
		// `status` is unreliable in sync mode (it reports "running" on success),
		// so the dispatch mode decides how the run is tracked.
		const result = asRecord(normalizeResult(payload?.result));
		const requestedMode = toStringValue(asRecord(payload?.input)?.runMode);
		const mode = toStringValue(result?.mode) ?? requestedMode;
		const runId = toStringValue(result?.runId);
		if (mode === "async" && runId) {
			asyncRunIds.add(runId);
			states.set(runId, mapTeamRunStatus(toStringValue(result?.status)));
			// Drop the dispatching call's own entry: the run it started is tracked
			// under runId, and counting both would double count one agent.
			states.delete(message.id);
			continue;
		}
		states.set(message.id, "completed");
	}

	return states;
}

/**
 * Count the child agents started during a session, bucketed by outcome.
 *
 * `sessionActive` distinguishes a run that is genuinely still working from one
 * that was recorded without an outcome — a hydrated transcript keeps its
 * unfinished `tool_use` blocks forever, and reporting those as "running" in an
 * idle session would be wrong.
 */
export function buildSessionAgentActivity(
	messages: ChatMessage[],
	options?: { sessionActive?: boolean },
): SessionAgentActivity {
	const sessionActive = options?.sessionActive ?? false;
	const states = collectAgentRunStates(messages);
	if (states.size === 0) {
		return EMPTY_AGENT_ACTIVITY;
	}

	const activity: SessionAgentActivity = {
		...EMPTY_AGENT_ACTIVITY,
		total: states.size,
	};
	for (const state of states.values()) {
		if (state === "running") {
			if (sessionActive) {
				activity.running += 1;
			} else {
				activity.unresolved += 1;
			}
			continue;
		}
		activity[state] += 1;
	}
	return activity;
}

export function hasAgentActivity(activity: SessionAgentActivity): boolean {
	return activity.total > 0;
}

/**
 * One child agent as recorded by the backend, from `list_session_agents`.
 *
 * The roster is authoritative where it exists: it carries each agent's real
 * persisted status and its own session id, which is what makes peeking at a
 * transcript possible. It lags the live stream though — a row appears only once
 * the runtime has persisted the spawn — so counts still fall back to the
 * message-derived tally while a turn is in flight.
 */
export type SessionAgentEntry = {
	sessionId: string;
	agentId: string;
	parentAgentId?: string;
	kind: "subagent" | "teamtask";
	status: string;
	/** The task the agent was given — its first prompt. */
	prompt?: string;
	/** Most recent step the agent took, for an at-a-glance progress line. */
	lastAction?: string;
	teamName?: string;
	provider?: string;
	model?: string;
	startedAt: string;
	endedAt?: string;
	hasMessages: boolean;
};

/** Persisted session statuses map onto the same buckets as tool-derived runs. */
export function agentEntryState(status: string): SessionAgentRunState {
	switch (status.trim().toLowerCase()) {
		case "running":
		case "pending":
			return "running";
		case "completed":
			return "completed";
		case "failed":
			return "failed";
		case "cancelled":
			return "cancelled";
		case "idle":
			return "unresolved";
		default:
			return "unresolved";
	}
}

export function summarizeAgentEntries(
	entries: SessionAgentEntry[],
): SessionAgentActivity {
	const activity: SessionAgentActivity = {
		...EMPTY_AGENT_ACTIVITY,
		total: entries.length,
	};
	for (const entry of entries) {
		activity[agentEntryState(entry.status)] += 1;
	}
	return activity;
}

/**
 * Reconcile the persisted roster with the live tool-derived tally.
 *
 * Neither source is complete on its own: the roster knows each agent's identity
 * and true status but only after persistence, while the tally sees a spawn the
 * moment its tool call starts but can never name the agent. Taking the larger
 * total keeps a just-started agent visible without double counting one that
 * both sources already agree on.
 */
export function mergeAgentActivity(
	entries: SessionAgentEntry[],
	derived: SessionAgentActivity,
	options?: { sessionActive?: boolean },
): SessionAgentActivity {
	if (entries.length === 0) {
		return derived;
	}
	const roster = summarizeAgentEntries(entries);
	if (derived.total <= roster.total) {
		return roster;
	}
	// Extra spawns the roster has not caught up with are still in flight.
	const pending = derived.total - roster.total;
	const sessionActive = options?.sessionActive ?? false;
	return {
		...roster,
		total: derived.total,
		running: roster.running + (sessionActive ? pending : 0),
		unresolved: roster.unresolved + (sessionActive ? 0 : pending),
	};
}

/** Screen-reader / tooltip text: "3 agents: 1 running, 2 completed". */
export function describeAgentActivity(activity: SessionAgentActivity): string {
	const parts: string[] = [];
	if (activity.running > 0) {
		parts.push(`${activity.running} running`);
	}
	if (activity.completed > 0) {
		parts.push(`${activity.completed} completed`);
	}
	if (activity.failed > 0) {
		parts.push(`${activity.failed} failed`);
	}
	if (activity.cancelled > 0) {
		parts.push(`${activity.cancelled} cancelled`);
	}
	if (activity.unresolved > 0) {
		parts.push(`${activity.unresolved} with no recorded outcome`);
	}
	const noun = activity.total === 1 ? "agent" : "agents";
	if (parts.length === 0) {
		return `${activity.total} ${noun}`;
	}
	return `${activity.total} ${noun}: ${parts.join(", ")}`;
}

import { describe, expect, it } from "vitest";
import {
	buildSessionDiffState,
	mergeToolDiffs,
	type SessionHookEvent,
} from "./session-diff";

function editorCreateEvent(path: string, newText: string): SessionHookEvent {
	return {
		hookName: "tool_result",
		toolName: "editor",
		toolInput: { path, new_text: newText },
		toolOutput: { success: true, result: `File created: ${path}` },
	};
}

function editorReplaceEvent(path: string, diffBody: string): SessionHookEvent {
	return {
		hookName: "tool_result",
		toolName: "editor",
		toolInput: { path, old_text: "before", new_text: "after" },
		toolOutput: {
			success: true,
			result: `Edited ${path}\n\`\`\`diff\n${diffBody}\n\`\`\``,
		},
	};
}

describe("mergeToolDiffs path canonicalization", () => {
	it("merges relative and absolute spellings of the same file into one entry", () => {
		// Regression: a file created with a relative path and later edited via
		// its absolute path was listed twice, splitting the counts and showing
		// stale content as a separate entry.
		const events = [
			editorCreateEvent("journal.txt", "line one\nline two"),
			editorReplaceEvent("/tmp/qa-ws/journal.txt", "+3: line three"),
		];

		const merged = mergeToolDiffs(events, "/tmp/qa-ws");

		expect(merged).toHaveLength(1);
		expect(merged[0]).toMatchObject({
			path: "journal.txt",
			additions: 3,
			deletions: 0,
		});
		expect(merged[0]?.hunks).toHaveLength(2);
	});

	it("collapses parent segments so escaped spellings merge with the absolute path", () => {
		const merged = mergeToolDiffs(
			[
				editorCreateEvent("../shared/config.txt", "x"),
				editorReplaceEvent("/tmp/shared/config.txt", "+2: y"),
			],
			"/tmp/qa-ws",
		);
		expect(merged).toHaveLength(1);
		expect(merged[0]).toMatchObject({
			path: "/tmp/shared/config.txt",
			additions: 2,
			deletions: 0,
		});
	});

	it("collapses redundant segments inside the workspace", () => {
		const merged = mergeToolDiffs(
			[
				editorCreateEvent("sub/../journal.txt", "one"),
				editorReplaceEvent("/tmp/qa-ws/./journal.txt", "+2: two"),
			],
			"/tmp/qa-ws",
		);
		expect(merged).toHaveLength(1);
		expect(merged[0]).toMatchObject({
			path: "journal.txt",
			additions: 2,
			deletions: 0,
		});
	});

	it("keeps canonicalizing when the cwd is the filesystem root", () => {
		const merged = mergeToolDiffs(
			[
				editorCreateEvent("notes.txt", "one"),
				editorReplaceEvent("/notes.txt", "+2: two"),
			],
			"/",
		);
		expect(merged).toHaveLength(1);
		expect(merged[0]).toMatchObject({
			path: "notes.txt",
			additions: 2,
			deletions: 0,
		});
	});

	it("merges Windows casing variants of the same file", () => {
		const merged = mergeToolDiffs(
			[
				editorCreateEvent("Journal.txt", "one"),
				editorReplaceEvent("c:\\users\\saoud\\journal.txt", "+2: two"),
			],
			"C:\\Users\\Saoud",
		);
		expect(merged).toHaveLength(1);
		expect(merged[0]).toMatchObject({
			path: "Journal.txt",
			additions: 2,
			deletions: 0,
		});
	});

	it("keeps files outside the cwd on their resolved path", () => {
		const merged = mergeToolDiffs(
			[editorCreateEvent("/etc/other/config.txt", "x")],
			"/tmp/qa-ws",
		);
		expect(merged).toHaveLength(1);
		expect(merged[0]?.path).toBe("/etc/other/config.txt");
	});

	it("keeps distinct files separate", () => {
		const merged = mergeToolDiffs(
			[
				editorCreateEvent("a.txt", "one"),
				editorCreateEvent("/tmp/qa-ws/b.txt", "two"),
			],
			"/tmp/qa-ws",
		);
		expect(merged.map((entry) => entry.path).sort()).toEqual([
			"a.txt",
			"b.txt",
		]);
	});

	it("falls back to raw path keys without a cwd", () => {
		const merged = mergeToolDiffs([
			editorCreateEvent("journal.txt", "one"),
			editorCreateEvent("/tmp/qa-ws/journal.txt", "two"),
		]);
		// Without a cwd there is no way to know these are the same file.
		expect(merged).toHaveLength(2);
	});

	it("sums the summary across canonicalized entries", () => {
		const state = buildSessionDiffState(
			[
				editorCreateEvent("journal.txt", "line one\nline two"),
				editorReplaceEvent("/tmp/qa-ws/journal.txt", "+3: line three"),
			],
			"/tmp/qa-ws",
		);
		expect(state.summary).toEqual({ additions: 3, deletions: 0 });
	});
});

import { resolveWorkspaceFilePath } from "./workspace-paths";

export type SessionHookEvent = {
	hookEventName?:
		| "tool_call"
		| "tool_result"
		| "agent_end"
		| "agent_error"
		| "session_shutdown"
		| string;
	hookName?:
		| "tool_call"
		| "tool_result"
		| "agent_end"
		| "agent_error"
		| "session_shutdown"
		| string;
	toolName?: string;
	toolInput?: unknown;
	toolOutput?: unknown;
	toolError?: string;
};

export type SessionDiffHunk = {
	oldStart: number;
	newStart: number;
	old: string;
	new: string;
};

export type SessionFileDiff = {
	path: string;
	additions: number;
	deletions: number;
	hunks: SessionDiffHunk[];
};

export type SessionDiffSummary = {
	additions: number;
	deletions: number;
};

export type SessionDiffState = {
	fileDiffs: SessionFileDiff[];
	summary: SessionDiffSummary;
};

export const EMPTY_DIFF_SUMMARY: SessionDiffSummary = {
	additions: 0,
	deletions: 0,
};

function asRecord(value: unknown): Record<string, unknown> | null {
	if (!value || typeof value !== "object") {
		return null;
	}
	return value as Record<string, unknown>;
}

function toStringValue(value: unknown): string | undefined {
	return typeof value === "string" && value.length > 0 ? value : undefined;
}

/**
 * Tool outputs arrive in several shapes depending on the source: a plain
 * record (live hook events), a JSON-encoded string, or a list of content
 * blocks such as [{ type: "text", text: "<json>" }] (persisted history).
 */
function normalizeToolOutput(value: unknown): Record<string, unknown> | null {
	if (typeof value === "string") {
		try {
			return asRecord(JSON.parse(value));
		} catch {
			return null;
		}
	}
	if (Array.isArray(value)) {
		for (const entry of value) {
			const record = asRecord(entry);
			if (!record) {
				continue;
			}
			if (typeof record.text === "string") {
				const inner = normalizeToolOutput(record.text);
				if (inner) {
					return inner;
				}
				continue;
			}
			return record;
		}
		return null;
	}
	return asRecord(value);
}

function getHookEventName(event: SessionHookEvent): string {
	return event.hookEventName ?? event.hookName ?? "";
}

function countAddedLines(value: string | undefined): number {
	if (!value) {
		return 0;
	}
	return value.split("\n").filter((line) => line.length > 0).length;
}

function stripApplyPatchWrapperLines(lines: string[]): string[] {
	const result: string[] = [];
	let insidePatch = false;

	for (const line of lines) {
		if (line.startsWith("*** Begin Patch")) {
			insidePatch = true;
			result.push(line);
			continue;
		}
		if (line === "*** End Patch") {
			insidePatch = false;
			result.push(line);
			continue;
		}

		const isBashWrapperLine =
			line.startsWith("%%bash") ||
			line.startsWith("apply_patch") ||
			line === "EOF" ||
			line.startsWith("```");
		if (isBashWrapperLine && !insidePatch) {
			continue;
		}

		result.push(line);
	}

	return result;
}

export function parseApplyPatchInput(input: string): SessionFileDiff[] {
	const lines = stripApplyPatchWrapperLines(
		input.split("\n").map((line) => line.replace(/\r$/, "")),
	);
	const fileDiffs: SessionFileDiff[] = [];

	let index = 0;
	const findNextActionLine = (start: number): number => {
		for (let i = start; i < lines.length; i += 1) {
			const line = lines[i] ?? "";
			if (
				line.startsWith("*** Add File: ") ||
				line.startsWith("*** Update File: ") ||
				line.startsWith("*** Delete File: ") ||
				line === "*** End Patch"
			) {
				return i;
			}
		}
		return lines.length;
	};

	while (index < lines.length) {
		const line = lines[index] ?? "";
		if (line.startsWith("*** Add File: ")) {
			const path = line.substring("*** Add File: ".length).trim();
			const end = findNextActionLine(index + 1);
			const addedLines: string[] = [];
			for (let i = index + 1; i < end; i += 1) {
				const bodyLine = lines[i] ?? "";
				if (bodyLine.startsWith("+")) {
					addedLines.push(bodyLine.slice(1));
				}
			}
			fileDiffs.push({
				path,
				additions: addedLines.length,
				deletions: 0,
				hunks:
					addedLines.length > 0
						? [
								{
									oldStart: 1,
									newStart: 1,
									old: "",
									new: addedLines.join("\n"),
								},
							]
						: [],
			});
			index = end;
			continue;
		}

		if (line.startsWith("*** Delete File: ")) {
			const path = line.substring("*** Delete File: ".length).trim();
			fileDiffs.push({
				path,
				additions: 0,
				deletions: 0,
				hunks: [],
			});
			index += 1;
			continue;
		}

		if (line.startsWith("*** Update File: ")) {
			const path = line.substring("*** Update File: ".length).trim();
			const end = findNextActionLine(index + 1);

			let additions = 0;
			let deletions = 0;
			let oldLineNo = 1;
			let newLineNo = 1;
			let activeHunk:
				| {
						oldStart: number;
						newStart: number;
						old: string[];
						new: string[];
				  }
				| undefined;
			const hunks: SessionDiffHunk[] = [];

			const flushActiveHunk = () => {
				if (!activeHunk) {
					return;
				}
				hunks.push({
					oldStart: activeHunk.oldStart,
					newStart: activeHunk.newStart,
					old: activeHunk.old.join("\n"),
					new: activeHunk.new.join("\n"),
				});
				activeHunk = undefined;
			};

			for (let i = index + 1; i < end; i += 1) {
				const bodyLine = lines[i] ?? "";
				if (bodyLine.startsWith("@@")) {
					flushActiveHunk();
					continue;
				}
				if (bodyLine.startsWith("+")) {
					additions += 1;
					if (!activeHunk) {
						activeHunk = {
							oldStart: oldLineNo,
							newStart: newLineNo,
							old: [],
							new: [],
						};
					}
					activeHunk.new.push(bodyLine.slice(1));
					newLineNo += 1;
					continue;
				}
				if (bodyLine.startsWith("-")) {
					deletions += 1;
					if (!activeHunk) {
						activeHunk = {
							oldStart: oldLineNo,
							newStart: newLineNo,
							old: [],
							new: [],
						};
					}
					activeHunk.old.push(bodyLine.slice(1));
					oldLineNo += 1;
					continue;
				}
				if (bodyLine.startsWith(" ")) {
					flushActiveHunk();
					oldLineNo += 1;
					newLineNo += 1;
					continue;
				}
				if (bodyLine === "*** End of File") {
					flushActiveHunk();
				}
			}
			flushActiveHunk();

			fileDiffs.push({
				path,
				additions,
				deletions,
				hunks,
			});
			index = end;
			continue;
		}

		index += 1;
	}

	return fileDiffs;
}

function parseDiffFromEditorResult(
	resultText: string,
): Pick<SessionFileDiff, "additions" | "deletions" | "hunks"> {
	const lines = resultText.split("\n");
	const startIdx = lines.findIndex((line) => line.trim() === "```diff");
	if (startIdx < 0) {
		return { additions: 0, deletions: 0, hunks: [] };
	}
	const endIdx = lines.findIndex(
		(line, idx) => idx > startIdx && line.trim() === "```",
	);
	const body = lines.slice(
		startIdx + 1,
		endIdx > startIdx ? endIdx : undefined,
	);

	const old: string[] = [];
	const next: string[] = [];
	let additions = 0;
	let deletions = 0;
	let oldStart: number | undefined;
	let newStart: number | undefined;

	for (const raw of body) {
		const match = raw.match(/^([+-])(\d+):\s?(.*)$/);
		if (!match) {
			continue;
		}

		const op = match[1];
		const lineNo = Number.parseInt(match[2], 10);
		const text = match[3] ?? "";
		if (op === "-") {
			deletions += 1;
			old.push(text);
			oldStart = oldStart ?? lineNo;
			continue;
		}

		additions += 1;
		next.push(text);
		newStart = newStart ?? lineNo;
	}

	if (additions + deletions === 0) {
		return { additions: 0, deletions: 0, hunks: [] };
	}

	return {
		additions,
		deletions,
		hunks: [
			{
				oldStart: oldStart ?? 1,
				newStart: newStart ?? 1,
				old: old.join("\n"),
				new: next.join("\n"),
			},
		],
	};
}

function parseEditorFileDiff(event: SessionHookEvent): SessionFileDiff | null {
	if (
		getHookEventName(event) !== "tool_result" ||
		event.toolName !== "editor" ||
		event.toolError
	) {
		return null;
	}

	const input = asRecord(event.toolInput);
	const output = normalizeToolOutput(event.toolOutput);
	if (!input || !output || output.success === false) {
		return null;
	}

	// Current editor schema has no `command` field; derive the operation from
	// the input shape (legacy `command` values still take precedence).
	const command =
		toStringValue(input.command) ??
		(input.insert_line != null
			? "insert"
			: toStringValue(input.old_text) != null
				? "str_replace"
				: "create");
	const pathFromInput = toStringValue(input.path);
	const query = toStringValue(output.query);
	const pathFromQuery = query?.includes(":")
		? query.split(":").slice(1).join(":")
		: undefined;
	const path = pathFromInput || pathFromQuery;
	if (!path) {
		return null;
	}

	const resultText = toStringValue(output.result) ?? "";

	if (command === "str_replace" && !resultText.startsWith("File created")) {
		const parsed = parseDiffFromEditorResult(resultText);
		return {
			path,
			additions: parsed.additions,
			deletions: parsed.deletions,
			hunks: parsed.hunks,
		};
	}

	if (
		command === "create" ||
		command === "insert" ||
		command === "str_replace"
	) {
		const newContent =
			toStringValue(input.new_text) ??
			toStringValue(input.file_text) ??
			toStringValue(input.new_str) ??
			"";
		return {
			path,
			additions: countAddedLines(newContent),
			deletions: 0,
			hunks: newContent
				? [
						{
							oldStart: 1,
							newStart: 1,
							old: "",
							new: newContent,
						},
					]
				: [],
		};
	}

	return null;
}

function parseApplyPatchFileDiffs(event: SessionHookEvent): SessionFileDiff[] {
	if (
		getHookEventName(event) !== "tool_result" ||
		event.toolName !== "apply_patch" ||
		event.toolError
	) {
		return [];
	}

	const output = normalizeToolOutput(event.toolOutput);
	if (!output || output.success === false) {
		return [];
	}

	// apply_patch accepts either { input: string } or a raw patch string.
	const patchInput =
		toStringValue(event.toolInput) ??
		toStringValue(asRecord(event.toolInput)?.input);
	if (!patchInput) {
		return [];
	}

	return parseApplyPatchInput(patchInput);
}

/**
 * Collapses "." and ".." segments and rebuilds the path with the given
 * separator. The webview has no `node:path`, so this is a string-level
 * equivalent; both separator styles are treated as separators, matching
 * `resolveWorkspaceFilePath`. ".." segments that would climb above an
 * absolute root are dropped; on relative paths leading ".." is kept.
 */
function collapsePathSegments(path: string, separator: string): string {
	const rootMatch = path.match(/^(?:\\\\|[A-Za-z]:[\\/]|[\\/])/);
	const rawRoot = rootMatch?.[0] ?? "";
	const root =
		rawRoot === ""
			? ""
			: rawRoot === "\\\\"
				? "\\\\"
				: /^[A-Za-z]:/.test(rawRoot)
					? rawRoot.slice(0, 2) + separator
					: separator;
	const segments: string[] = [];
	for (const segment of path.slice(rawRoot.length).split(/[\\/]+/)) {
		if (!segment || segment === ".") {
			continue;
		}
		if (segment === "..") {
			if (segments.length > 0 && segments[segments.length - 1] !== "..") {
				segments.pop();
			} else if (!root) {
				segments.push("..");
			}
			continue;
		}
		segments.push(segment);
	}
	return root + segments.join(separator);
}

/**
 * Tool calls address the same file inconsistently across a session — one
 * edit uses "journal.txt", a later one "/tmp/workspace/journal.txt". Keying
 * diffs by the raw string would list that file twice with split counts, so
 * paths are canonicalized against the session cwd first: resolved against
 * the cwd with "." and ".." segments collapsed, so "../shared/file.txt"
 * and its absolute spelling share one key, and a filesystem-root cwd such
 * as "/" still canonicalizes. Windows sessions (drive-letter or UNC cwd)
 * compare case-insensitively, matching `normalizeWorkspacePath`. Files
 * inside the cwd display as workspace-relative paths; everything else
 * displays as the resolved path, both in the first spelling seen.
 */
function canonicalizeDiffPath(
	path: string,
	cwd?: string,
): { key: string; display: string } {
	const trimmed = path.trim().replace(/^\.\//, "");
	const baseRaw = (cwd ?? "").trim();
	if (!baseRaw) {
		return { key: trimmed, display: trimmed };
	}
	const separator =
		baseRaw.includes("\\") && !baseRaw.includes("/") ? "\\" : "/";
	const base = collapsePathSegments(baseRaw, separator);
	if (!base) {
		return { key: trimmed, display: trimmed };
	}
	const resolved = collapsePathSegments(
		resolveWorkspaceFilePath(trimmed, base),
		separator,
	);
	const caseInsensitive = /^[A-Za-z]:/.test(base) || base.startsWith("\\\\");
	const comparable = (value: string) =>
		caseInsensitive ? value.toLowerCase() : value;
	const basePrefix = base.endsWith(separator) ? base : base + separator;
	const withinBase =
		resolved.length > basePrefix.length &&
		comparable(resolved).startsWith(comparable(basePrefix));
	return {
		key: comparable(resolved),
		display: withinBase ? resolved.slice(basePrefix.length) : resolved,
	};
}

export function mergeToolDiffs(
	events: SessionHookEvent[],
	cwd?: string,
): SessionFileDiff[] {
	const byPath = new Map<string, SessionFileDiff>();

	for (const event of events) {
		const diffs: SessionFileDiff[] = [];
		const editorDiff = parseEditorFileDiff(event);
		if (editorDiff) {
			diffs.push(editorDiff);
		}
		diffs.push(...parseApplyPatchFileDiffs(event));
		if (diffs.length === 0) {
			continue;
		}

		for (const diff of diffs) {
			const { key, display } = canonicalizeDiffPath(diff.path, cwd);
			const existing = byPath.get(key);
			if (!existing) {
				byPath.set(key, { ...diff, path: display });
				continue;
			}

			byPath.set(key, {
				...existing,
				additions: existing.additions + diff.additions,
				deletions: existing.deletions + diff.deletions,
				hunks: [...existing.hunks, ...diff.hunks].slice(-30),
			});
		}
	}

	return Array.from(byPath.values());
}

export function summarizeFileDiffs(
	fileDiffs: SessionFileDiff[],
): SessionDiffSummary {
	return fileDiffs.reduce(
		(acc, fileDiff) => {
			acc.additions += fileDiff.additions;
			acc.deletions += fileDiff.deletions;
			return acc;
		},
		{ ...EMPTY_DIFF_SUMMARY },
	);
}

export function buildSessionDiffState(
	events: SessionHookEvent[],
	cwd?: string,
): SessionDiffState {
	const fileDiffs = mergeToolDiffs(events, cwd);
	return {
		fileDiffs,
		summary: summarizeFileDiffs(fileDiffs),
	};
}

export type SessionHistoryStatus =
	| "running"
	| "completed"
	| "failed"
	| "cancelled"
	| "idle";

export type SessionMetadata = {
	title?: string;
	/**
	 * Favorited sessions. Stored in session metadata rather than desktop-local
	 * state so every client reading the session sees the same flag.
	 */
	pinned?: boolean;
	git?: {
		url?: string;
		branch?: string;
	};
	sessionHistoryOrigin?: {
		mode?: string;
		version?: string;
		trigger?: string;
	};
	[key: string]: unknown;
};

export const PINNED_METADATA_KEY = "pinned";

export interface SessionHistoryItem {
	sessionId: string;
	source?: string;
	status: SessionHistoryStatus;
	provider: string;
	model: string;
	cwd: string;
	workspaceRoot: string;
	parentSessionId?: string;
	isSubagent?: boolean;
	prompt?: string;
	startedAt: string;
	endedAt?: string;
	metadata?: SessionMetadata;
}

export const SCHEDULED_SESSION_SOURCE = "hub-schedule";
export const ALL_SESSION_SOURCES = "__all_session_sources__";

export function getSessionSource(
	session: Pick<SessionHistoryItem, "source" | "metadata">,
): string {
	const source = session.source?.trim();
	if (source) {
		return source;
	}
	return typeof session.metadata?.source === "string"
		? session.metadata.source.trim()
		: "";
}

export function getSessionSourceLabel(source: string): string {
	const knownLabel = {
		cli: "CLI",
		desktop: "Desktop",
		vscode: "VS Code",
		"vscode-webview": "VS Code",
	}[source.trim().toLowerCase()];
	if (knownLabel) {
		return knownLabel;
	}
	return source
		.trim()
		.split(/[-_\s]+/)
		.filter(Boolean)
		.map((part) => part.charAt(0).toUpperCase() + part.slice(1))
		.join(" ");
}

export function getSessionSources<T extends { source?: string }>(
	sessions: readonly T[],
): string[] {
	return [
		...new Set(
			sessions
				.map((session) => session.source?.trim())
				.filter((source): source is string => Boolean(source)),
		),
	].sort((a, b) => a.localeCompare(b));
}

export function filterSessionsBySource<T extends { source?: string }>(
	sessions: readonly T[],
	source: string,
): T[] {
	if (source === ALL_SESSION_SOURCES) {
		return [...sessions];
	}
	return sessions.filter((session) => session.source?.trim() === source);
}

export function getSessionMetadataTitle(metadata?: SessionMetadata): string {
	if (!metadata) {
		return "";
	}
	return typeof metadata.title === "string" ? metadata.title.trim() : "";
}

export function getSessionMetadataPinned(metadata?: SessionMetadata): boolean {
	return metadata?.[PINNED_METADATA_KEY] === true;
}

export function getSessionMetadataIsScheduled(
	metadata?: SessionMetadata,
): boolean {
	const origin = metadata?.sessionHistoryOrigin;
	if (!origin || typeof origin !== "object" || Array.isArray(origin)) {
		return false;
	}
	return (
		typeof origin.trigger === "string" &&
		origin.trigger.trim() === SCHEDULED_SESSION_SOURCE
	);
}

export function getSessionMetadataGitBranch(
	metadata?: SessionMetadata,
): string {
	const git = metadata?.git;
	if (!git || typeof git !== "object" || Array.isArray(git)) {
		return "";
	}
	return typeof git.branch === "string" ? git.branch.trim() : "";
}

